TURATH_CHUNK(21,[{"num":4200,"demo":false,"sanad":"","matn":["عن رجل من بني يربوع، قال: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَسَمِعْتُهُ وَهُوَ يُكَلِّمُ النَّاسَ يَقُولُ: يَدُ المُعْطِي الْعُلْيَا، أُمَّكَ وَأَبَاكَ، وَأُخْتَكَ وَأَخَاكَ، ثُمَّ أَدْنَاكَ فَأَدْنَاكَ . قَالَ: فَقَالَ رَجُلٌ: يَا رَسُولَ الله، هَؤُلاءِ بَنُو ثَعْلَبَةَ الَّذِينَ أَصَابُوا فُلانًا؟ قَالَ: فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَلا لا تَجْنِي نَفْسٌ عَلَى أُخْرَى ."],"takhrij":"صحيح: رواه الإمام أحمد (16613) عن يونس، حدّثنا أبو عوانة، عن الأشعث بن سليم، عن أبيه، عن رجل من بني يربوع، فذكره.","grade":"صحيح","chapter_ar":"باب بأن اليد المعطية أفضل من اليد السائلة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Imam Ahmad (16613) and al-Nasa’i (4837).","chapter_en":"That the giving hand is better than the asking hand","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":1,"content":{"translation":{"en":["A man from Banu Yarbuʿ said: I came to the Prophet ﷺ and heard him while he was speaking to the people, saying: “The hand of the giver is the upper hand: your mother, your father, your sister, your brother, then the nearest, then the nearest.” A man said: “O Messenger of Allah ﷺ, are these Banu Thaʿlabah the ones who harmed so-and-so?” The Messenger of Allah ﷺ said: “Indeed, no person is held responsible for another person’s crime.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (16613)، والنسائي (4837)."},{"num":4201,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدريّ: أَنَّ نَاسًـا مِنْ الأَنْصَـارِ سَـأَلُـوا رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَأَعْطَاهُمْ، ثُمَّ سَأَلُوهُ فَأَعْطَاهُمْ، حَتَّى نَفِدَ مَا عِنْدَهُ ثُمَّ قَال: مَا يَكُونُ عِنْدِي مِنْ خَيْرٍ فَلَنْ أَدَّخِرَهُ عَنْكُم، وَمَنْ يَسْتَعْفِفْ يُعِفَّهُ الله، وَمَنْ يَسْتَغْنِ يُغْنِهِ الله، وَمَنْ يَتَصَبَّرْ يُصَبِّرْهُ الله، وَمَا أُعْطِيَ أَحَدٌ عَطَاءً هُوَ خَيْرٌ وَأَوْسَعُ مِنْ الصَّبْرِ ."],"takhrij":"متفق عليه: رواه مالك في الصدقة (7) عن ابن شهاب، عن عطاء بن يزيد اللّيثيّ، عن أبي سعيد الخدريّ، فذكره.","grade":"متفق عليه","chapter_ar":"باب الاستعفاف عن المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (7), al-Bukhari (1469), and Muslim (1053).","chapter_en":"Refraining from asking people","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Abu Saʿid al-Khudri reported that some people from the Ansar asked the Messenger of Allah ﷺ, so he gave them. Then they asked him again, so he gave them, until what he had was exhausted. Then he said: “Whatever good I have, I will never withhold it from you. Whoever seeks to remain chaste and restrained, Allah will make him chaste. Whoever seeks self-sufficiency, Allah will make him self-sufficient. Whoever forces himself to be patient, Allah will grant him patience. And no one has ever been given a gift better and more expansive than patience.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (7)، والبخاري (1469)، ومسلم (1053)."},{"num":4202,"demo":false,"sanad":"","matn":["عن أبي سعيد: أَنَّ رَجُلا مِنْ الأَنْصَارِ كَانَتْ بِهِ حَاجَةٌ، فَقَالَ لَهُ أَهْلُهُ: ائْتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَاسْأَلْهُ، فَأَتَاهُ وَهُوَ يَخْطُبُ وَهُوَ يَقُول: مَنْ اسْتَعَفَّ أَعَفَّهُ الله، وَمَنْ اسْتَغْنَى أَغْنَاهُ الله، وَمَنْ سَأَلَنَا فَوَجَدْنَا لَهُ أَعْطَيْنَاهُ قَالَ: فَذَهَبَ وَلَمْ يَسْأَلْ."],"takhrij":"صحيح: رواه الإمام أحمد (10989) عن هُشيم، حدّثنا أبو بشر، عن أبي نضرة، عن أبي سعيد، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الاستعفاف عن المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Imam Ahmad (10989).","chapter_en":"Refraining from asking people","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Abu Saʿid reported that a man from the Ansar was in need, so his family said to him, “Go to the Prophet ﷺ and ask him.” He came to him while he was delivering a sermon and saying: “Whoever seeks to refrain from asking, Allah will make him chaste. Whoever seeks self-sufficiency, Allah will make him self-sufficient. Whoever asks us, and we find something for him, we will give him.” He said: So the man left and did not ask."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (10989)."},{"num":4203,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّ أَهْلَهُ شَكَوْا إِلَيْهِ الْحَاجَةَ، فَخَرَجَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيَسْأَلَهُ لَهُمْ شَيْئًا، فَوَافَقَهُ عَلَى الْمِنْبَرِ، وَهُوَ يَقُولُ: أَيُّهَا النَّاسُ، قَدْ آنَ لَكُمْ أَنْ تَسْتَغْنُوا عَنِ الْمَسْأَلَةِ، فَإِنَّهُ مَنْ يَسْتَعْفِفْ يُعِفَّهُ اللهُ، وَمَنْ يَسْتَغْنِ يُغْنِهِ اللهُ، وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ مَا رُزِقَ عَبْدٌ شَيْئًا أَوْسَعَ مِنَ الصَّبْرِ، وَلَئِنْ أَبَيْتُمْ إِلَاّ أَنْ تَسْأَلُونِي لأُعْطِيَنَّكُمْ مَا وَجَدْتُ."],"takhrij":"حسن: رواه ابن حبان (3399) من طريق اللّيث، عن ابن عجلان، عن سعيد المقبريّ، عن أبي سعيد الخدريّ، فذكره.","grade":"حسن","chapter_ar":"باب الاستعفاف عن المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Ibn Hibban (3399).","chapter_en":"Refraining from asking people","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Abu Saʿid al-Khudri reported that his family complained to him of need, so he went out to the Messenger of Allah ﷺ to ask something for them. He found him on the pulpit saying: “O people, the time has come for you to do without asking, for whoever seeks restraint, Allah will make him restrained; and whoever seeks independence, Allah will make him independent. By the One in Whose Hand is Muhammad’s soul, no servant has ever been given anything broader than patience. Yet if you insist on asking me, I will surely give you whatever I find.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (3399)."},{"num":4204,"demo":false,"sanad":"","matn":["عن حكيم بن حزام، عن النبيّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قال: الْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى، وَابْدَأْ بِمَنْ تَعُولُ، وَخَيْرُ الصَّدَقَةِ عَنْ ظَهْرِ غِنًى، وَمَنْ يَسْتَعْفِفْ يُعِفَّهُ الله، وَمَنْ يَسْتَغْنِ يُغْنِهِ الله ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1427) عن موسى بن إسماعيل، حدّثنا وهيب، حدّثنا هشام، عن أبيه، عن حكيم بن حزام، فذكره.","grade":"متفق عليه","chapter_ar":"باب الاستعفاف عن المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (1427) and Muslim (1034).","chapter_en":"Refraining from asking people","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Hakim ibn Hizam reported that the Prophet ﷺ said: “The upper hand is better than the lower hand. Begin with those under your care. The best charity is that which is given while one remains self-sufficient. Whoever seeks restraint, Allah will make him restrained, and whoever seeks self-sufficiency, Allah will make him self-sufficient.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[4071,11998],"tks":"متفق عليه: رواه البخاري (1427)، ومسلم (1034)."},{"num":4205,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كَانَ بِالْكُوفَةِ أَمِيرٌ، قَالَ: فَخَطَبَ يَوْمًا، فَقَالَ: إِنَّ فِي إِعْطَاءِ هَذَا الْمَالِ فِتْنَةً، وَفِي إِمْسَاكِهِ فِتْنَةً، وَبِذَلِكَ قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي خُطْبَتِهِ حَتَّى فَرَغَ، ثُمَّ نَزَلَ."],"takhrij":"صحيح: رواه أحمد (20586) قال: حدثنا محمد بن جعفر، حدثنا شعبة، قال: سمعت إسحاق بن سويد، قال: سمعت مطرِّف بن عبد الله بن الشخير، يحدث عن رجل من أصحاب النبي صلى الله عليه وسلم ، فذكره.","grade":"صحيح","chapter_ar":"باب الاستعفاف عن المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (20586).","chapter_en":"Refraining from asking people","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["A man from the Companions of the Prophet ﷺ said: He was a governor in Kufah, and one day he delivered a sermon and said: “There is trial in giving out this wealth, and there is trial in withholding it. And upon this the Messenger of Allah ﷺ once stood in his sermon until he finished, then came down.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (20586)."},{"num":4206,"demo":false,"sanad":"","matn":["عن معاوية بن أبي سفيان، قال: قال رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لا تُلْحِفُوا فِي المَسْأَلَةِ، فَوَالله لا يَسْأَلُنِي أَحَدٌ مِنْكُمْ شَيْئًا فَتُخْرِجَ لَهُ مَسْأَلَتُهُ مِنِّي شَيْئًا وَأَنَا لَهُ كَارِهٌ فَيُبَارَكَ لَهُ فِيمَا أَعْطَيْتُهُ ."],"takhrij":"صحيح: رواه مسلم في الزكاة (1038) عن محمد بن عبدالله بن نمير، حدّثنا سفيان، عن عمرو ، عن وهب بن منبه، عن أخيه همّام، عن معاوية، فذكره.","grade":"صحيح","chapter_ar":"باب كراهية الإلحاف في المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1038).","chapter_en":"The dislike of persistent begging","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":3,"content":{"translation":{"en":["Muʿawiyah ibn Abi Sufyan said: The Messenger of Allah ﷺ said: “Do not persist in begging. By Allah, none of you asks me for something such that his asking extracts something from me while I dislike it, and then finds blessing in what I gave him.”"]},"buhuth":{"en":["The word ilhaf means insistence and persistence. It is said that a beggar committed ilhaf in his request when he kept pressing, meaning that he stays attached to the person being asked until he gives him something."]},"intro":{"ar":["قال الله تعالى:","( لَا يَسْأَلُونَ النَّاسَ إِلْحَافًا ) [البقرة: ٢٧٣]."],"en":["Allah the Exalted said:","“They do not ask people persistently.” [Surah al-Baqarah, 2:273]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1038)."},{"num":4207,"demo":false,"sanad":"","matn":["عن رجل من بني أسد أنه قال: نَزَلْتُ أَنَا وَأَهْلِي بِبَقِيعِ الْغَرْقَدِ فَقَالَ لِي أَهْلِي اذْهَبْ إِلَى رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَاسْأَلْهُ لَنَا شَيْئًا نَأْكُلهُ، وَجَعَلُوا يَذْكُرُونَ مِنْ حَاجَتِهِمْ فَذَهَبْتُ إِلَى رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَوَجَدْتُ عِنْدَهُ رَجُلا يَسْأَلُهُ وَرَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  يَقُول: لا أَجِدُ مَا أُعْطِيكَ . فَتَوَلَّى الرَّجُلُ عَنْهُ وَهُوَ مُغْضَبٌ وَهُوَ يَقُولُ: لَعَمْرِي إِنَّكَ لَتُعْطِي مَنْ شِئْتَ. فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّهُ لَيَغْضَبُ عَلَيَّ أَنْ لا أَجِدَ مَا أُعْطِيهِ! مَنْ سَأَلَ مِنْكُمْ وَلَهُ أُوقِيَّةٌ أَوْ عَدْلُهَا فَقَدْ سَأَلَ إِلحَافًا .","قَالَ الأَسَدِيُّ: فَقُلْتُ: لَلَقْحَةٌ لَنَا خَيْرٌ مِنْ أُوقِيَّةٍ.","قَالَ: فَرَجَعْتُ وَلَمْ أَسْأَلْهُ، فَقُدِمَ عَلَى رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  بَعْدَ ذَلِكَ بِشَعِيرٍ وَزَبِيبٍ فَقَسَمَ لَنَا مِنْهُ حَتَّى أَغْنَانَا الله عَزَّ وَجَلَّ."],"takhrij":"صحيح: رواه مالك في الصّدقة (11) عن زيد بن أسلم، عن عطاء بن يسار، عن رجل من بني أسد، فذكره.","grade":"صحيح","chapter_ar":"باب كراهية الإلحاف في المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Malik (11), Abu Dawud (1627), al-Nasa’i (2597), and Ahmad (16411).","chapter_en":"The dislike of persistent begging","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":3,"content":{"translation":{"en":["A man from Banu Asad said: I settled with my family in Baqiʿ al-Gharqad, and my family said to me, “Go to the Messenger of Allah ﷺ and ask him for something for us to eat,” and they kept mentioning their needs. So I went to the Messenger of Allah ﷺ and found a man with him asking him, while the Messenger of Allah ﷺ was saying: “I do not find anything to give you.” So the man turned away angrily, saying: “By my life, you give to whomever you wish.” The Messenger of Allah ﷺ said: “He becomes angry with me because I do not find what to give him. Whoever among you asks while he has an uqiyyah or its equivalent has asked persistently.” The Asadi said: So I said to myself, “We have a milking camel, and that is better than an uqiyyah.” So I returned and did not ask him.","Later barley and raisins came to the Messenger of Allah ﷺ, and he distributed some to us until Allah made us independent."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (11)، وأبو داود (1627)، والنسائي (2597)، وأحمد (16411)."},{"num":4208,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ :: مَنْ سَأَلَ وَلَهُ قِيمَةُ أُوقِيَّةٍ، فَقَدْ أَلْحَفَ .."],"takhrij":"حسن: رواه أبو داود (1628)، والنسائي (2599) كلاهما عن قتيبة بن سعيد، حدّثنا عبدالرحمن بن أبي الرجال، عن عُمارة بن غزية، عن عبدالرحمن بن أبي سعيد الخدريّ، عن أبيه أبي سعيد، فذكر الحديث، واللّفظ لأبي داود.","grade":"حسن","chapter_ar":"باب كراهية الإلحاف في المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (1628) and al-Nasa’i (2599), and this is the wording of Abu Dawud.","chapter_en":"The dislike of persistent begging","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":3,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: The Messenger of Allah ﷺ said: “Whoever asks while possessing the value of one uqiyyah has begged persistently.”"]},"buhuth":{"en":["In al-Nasa’i’s version:","“Whoever seeks independence, Allah, Mighty and Majestic, will enrich him; whoever seeks restraint, Allah, Mighty and Majestic, will make him restrained; whoever seeks sufficiency, Allah, Mighty and Majestic, will suffice him; and whoever asks while possessing the value of one uqiyyah has begged persistently.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1628)، والنسائي (2599)، واللفظ لأبي داود."},{"num":4209,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو بن العاص قال: قال رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَنْ سَأَلَ وَلَهُ أَرْبَعُونَ دِرْهَمًا فَهُوَ المُلْحِفُ ."],"takhrij":"حسن: رواه النسائيّ (2595) عن أحمد بن سليمان، قال: أخبرنا يحيى ابن آدم، عن سفيان بن عيينة، عن داود بن شابور، عن عمرو بن شعيب، عن أبيه، عن جدّه، فذكره.","grade":"حسن","chapter_ar":"باب كراهية الإلحاف في المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by al-Nasa’i (2595), and graded authentic by Ibn Khuzaymah (2448).","chapter_en":"The dislike of persistent begging","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs said: The Messenger of Allah ﷺ said: “Whoever asks while having forty dirhams is one who begs persistently.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (2595)، وصححه ابن خزيمة (2448)."},{"num":4210,"demo":false,"sanad":"","matn":["عن رَجُلٍ مِنْ مُزَيْنَةَ أَنَّهُ قَالَتْ لَهُ أُمُّـهُ: أَلا تَنْـطَلِقُ فَتَسْأَلَ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  كَمَا يَسْأَلُهُ النَّاسُ، فَانْطَلَقْتُ أَسْأَلُهُ فَوَجَدْتُهُ قَائِمًا يَخْطُبُ وَهُوَ يَقُولُ: مَنْ اسْتَعَفَّ أَعَفَّهُ الله، وَمَنْ اسْتَغْنَى أَغْنَاهُ الله، وَمَنْ سَأَلَ النَّاسَ وَلَهُ عِدْلُ خَمْسِ أَوَاقٍ فَقَدْ سَأَلَ إِلحَافًا .","فَقُلْتُ بَيْنِي وَبَيْنَ نَفْسِي: لَنَاقَةٌ لَهُ هِيَ خَيْرٌ مِنْ خَمْسِ أَوَاقٍ، وَلِغُلامِهِ نَاقَةٌ أُخْرَى هِيَ خَيْرٌ مِنْ خَمْسِ أَوَاقٍ، فَرَجَعْتُ وَلَمْ أَسْأَلْهُ."],"takhrij":"حسن: رواه الإمام أحمد (17237) عن أبي بكر الحنفيّ، قال: حدّثنا عبد الحميد بن جعفر، عن أبيه، عن رجل من مزينة، فذكره.","grade":"حسن","chapter_ar":"باب كراهية الإلحاف في المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Imam Ahmad (17237).","chapter_en":"The dislike of persistent begging","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":3,"content":{"translation":{"en":["A man from Muzaynah reported that his mother said to him: “Will you not go and ask the Messenger of Allah ﷺ just as people ask him?” So I went to ask him, and found him standing delivering a sermon, saying: “Whoever seeks restraint, Allah will make him restrained; whoever seeks self-sufficiency, Allah will make him self-sufficient; and whoever asks people while having the equivalent of five uqiyyahs has asked persistently.”","So I said to myself: “A she-camel of his is better than five uqiyyahs, and his servant has another she-camel that is better than five uqiyyahs.” So I returned and did not ask him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (17237)."},{"num":4211,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، يَرْفَعُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا تُلْحِفُوا بِالْمَسْأَلَةِ، فَإِنَّهُ مَنْ يَسْتَخْرِجُ مِنَا بِهَا شَيْئًا لَا يُبَارَكُ لَهُ فِيهِ."],"takhrij":"صحيح: رواه أبو يعلى (5628) عن عبيدالله بن عمر القواريريّ، حدّثنا حماد، عن عمرو - قال حماد وليث، عن عمرو، عن ابن عمر، فذكره.","grade":"صحيح","chapter_ar":"باب كراهية الإلحاف في المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Abu Yaʿla (5628).","chapter_en":"The dislike of persistent begging","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿUmar reported as a marfuʿ narration to the Prophet ﷺ that he said: “Do not persist in asking, for whoever extracts something from us by means of it will find no blessing in it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو يعلى (5628)."},{"num":4212,"demo":false,"sanad":"","matn":["عن عمر بن الخطاب، قال: قَدْ كَانَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  يُعْطِينِي الْعَطَاءَ فَأَقُولُ: أَعْطِهِ أَفْقَرَ إِلَيْهِ مِنِّي، حَتَّى أَعْطَانِي مَرَّةً مَالا فَقُلْتُ: أَعْطِهِ أَفْقَرَ إِلَيْهِ مِنِّي، فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : خُذْهُ وَمَا جَاءَكَ مِنْ هَذَا المَالِ وَأَنْتَ غَيْرُ مُشْرِفٍ وَلا سَائِلٍ فَخُذْهُ، وَمَا لا فَلا تُتْبِعْهُ نَفْسَكَ ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1473)، ومسلم في الزكاة (1045) كلاهما من طريق يونس، عن ابن شهاب، عن سالم بن عبدالله بن عمر، عن أبيه، قال: سمعت عمر بن الخطاب، فذكره.","grade":"متفق عليه","chapter_ar":"باب فيمن أُعطي من غير مسألة ولا إشراف نفس","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1473) and Muslim (1045).","chapter_en":"Regarding one who is given something without asking and without coveting it","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":4,"content":{"translation":{"en":["ʿUmar ibn al-Khattab said: The Messenger of Allah ﷺ used to give me a stipend, and I would say, “Give it to someone poorer than me,” until one time he gave me some wealth and I said, “Give it to someone poorer than me.” So the Messenger of Allah ﷺ said: “Take it. Whatever comes to you from this wealth while you are neither seeking it eagerly nor asking for it, then take it. But whatever does not come in that way, do not let your soul chase after it.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1473)، ومسلم (1045)."},{"num":4213,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: إنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  كَانَ يُعْطِي عُمَرَ بْنَ الخَطَّابِ الْعَطَاءَ فَيَقُولُ لَهُ عُمَرُ: أَعْطِهِ يَا رَسُولَ الله أَفْقَرَ إِلَيْهِ مِنِّي. فَقَالَ لَهُ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : خُذْهُ فَتَمَوَّلْهُ أَوْ تَصَدَّقْ بِهِ، وَمَا جَاءَكَ مِنْ هَذَا المَالِ وَأَنْتَ غَيْرُ مُشْرِفٍ وَلا سَائِلٍ فَخُذْهُ، وَمَا لا فَلا تُتْبِعْهُ نَفْسَكَ .","قَالَ سَالِمٌ: فَمِنْ أَجْلِ ذَلِكَ كَانَ ابْنُ عُمَرَ لا يَسْأَلُ أَحَدًا شَيْئًا، وَلا يَرُدُّ شَيْئًا أُعْطِيَهُ."],"takhrij":"صحيح: رواه مسلم في الزكاة (1045: 111) عن أبي الطاهر، عن ابن وهب، عن عمرو بن الحارث، عن ابن شهاب، عن سالم، عن ابن عمر، فذكره.","grade":"صحيح","chapter_ar":"باب فيمن أُعطي من غير مسألة ولا إشراف نفس","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1045 no. 111).","chapter_en":"Regarding one who is given something without asking and without coveting it","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ used to give ʿUmar ibn al-Khattab some stipend, and ʿUmar would say to him, “Give it, O Messenger of Allah ﷺ, to someone poorer than me.” So the Messenger of Allah ﷺ said to him: “Take it and keep it as wealth, or give it in charity. Whatever comes to you from this wealth while you are neither seeking it eagerly nor asking for it, then take it. And whatever does not come in that way, do not let your soul pursue it.”","Salim said: Because of that, Ibn ʿUmar would not ask anyone for anything, nor would he refuse anything that was given to him."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1045: 111)."},{"num":4214,"demo":false,"sanad":"","matn":["عن حكيم بن حزام، قال: سَأَلْتُ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَأَعْطَانِي، ثُمَّ سَأَلْتُهُ فَأَعْطَانِي، ثُمَّ سَأَلْتُهُ فَأَعْطَانِي، ثُمَّ قَالَ: يَا حَكِيمُ إِنَّ هَذَا المَالَ خَضِرَةٌ حُلْوَةٌ، فَمَنْ أَخَذَهُ بِسَخَاوَةِ نَفْسٍ بُورِكَ لَهُ فِيهِ، وَمَنْ أَخَذَهُ بِإِشْرَافِ نَفْسٍ لَمْ يُبَارَكْ لَهُ فِيهِ، كَالَّذِي يَأْكُلُ وَلا يَشْبَعُ، الْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى .","قَالَ حَكِيمٌ: فَقُلْتُ: يَا رَسُولَ الله، وَالَّذِي بَعَثَكَ بِالحَقِّ لا أَرْزَأُ أَحَدًا بَعْدَكَ شَيْئًا حَتَّى أُفَارِقَ الدُّنْيَا.","فَكَانَ أَبُو بَكْرٍ يَدْعُو حَكِيمًا إِلَى الْعَطَاءِ فَيَأْبَى أَنْ يَقْبَلَهُ مِنْهُ، ثُمَّ إِنَّ عُمَرَ دَعَاهُ لِيُعْطِيَهُ فَأَبَى أَنْ يَقْبَلَ مِنْهُ شَيْئًا. فَقَالَ عُمَرُ: إِنِّي أُشْهِدُكُمْ يَا مَعْشَرَ المُسْلِمِينَ عَلَى حَكِيمٍ أَنِّي أَعْرِضُ عَلَيْهِ حَقَّهُ مِنْ هَذَا الْفَيْءِ فَيَأْبَى أَنْ يَأْخُذَهُ، فَلَمْ يَرْزَأْ حَكِيمٌ أَحَدًا مِنْ النَّاسِ بَعْدَ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  حَتَّى تُوُفِّيَ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1472)، ومسلم في الزكاة (1035) كلاهما من طريق الزهريّ، عن عروة بن الزبير وسعيد بن المسيب، عن حكيم بن حزام، فذكر الحديث. اللّفظ للبخاريّ. وأما مسلم فرواه مختصراً.","grade":"متفق عليه","chapter_ar":"باب فيمن أُعطي من غير مسألة ولا إشراف نفس","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1472) and Muslim (1035).","chapter_en":"Regarding one who is given something without asking and without coveting it","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":4,"content":{"translation":{"en":["Hakim ibn Hizam said: I asked the Messenger of Allah ﷺ and he gave me. Then I asked him again and he gave me. Then I asked him again and he gave me. Then he said: “O Hakim, this wealth is fresh and sweet. Whoever takes it with a generous soul will be blessed in it, and whoever takes it with greedy expectation will not be blessed in it. He is like one who eats and is never satisfied. And the upper hand is better than the lower hand.” Hakim said: So I said, “O Messenger of Allah ﷺ, by the One who sent you with the truth, I will not diminish anyone’s wealth after you by asking for anything until I leave this world.”","Thereafter Abu Bakr, may Allah be pleased with him, would call Hakim to receive an allowance, but he refused to accept it from him. Then ʿUmar, may Allah be pleased with him, called him to give him something, but he refused to accept anything from him. So ʿUmar said: “O Muslims, I call you to witness concerning Hakim that I offer him his due from this public wealth, but he refuses to take it.”","So Hakim did not ask anyone among the people for anything after the Messenger of Allah ﷺ until he died."]},"buhuth":{"en":["In one wording in Muslim: “Whoever takes it with a content soul.”","The phrase “with a generous soul” means with openness and ease, without greed or insistence.","The phrase “with eager expectation” means that the soul looks toward it and longs for it.","And “I will not diminish” means: I will not reduce anyone’s wealth by asking him for something."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1472)، ومسلم (1035)."},{"num":4215,"demo":false,"sanad":"","matn":["عن خالد بن عدي الجهنيّ، قال: سمعتُ رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قال: مَنْ بَلَغَهُ مَعْرُوفٌ عَنْ أَخِيهِ مِنْ غَيْرِ مَسْأَلَةٍ وَلا إِشْرَافِ نَفْسٍ فَلْيَقْبَلْهُ وَلا يَرُدَّهُ فَإِنَّمَا هُوَ رِزْقٌ سَاقَهُ الله عَزَّ وَجَلَّ إِلَيْهِ ."],"takhrij":"صحيح: رواه أحمد (17936)، وأبو يعلى (925)، والطّبرانيّ (4124) كلّهم من طريق عبدالله بن يزيد المقرئ، حدّثنا سعيد بن أبي أيوب، حدّثني أبو الأسود، عن بكير بن عبدالله، عن بسر بن سعيد، عن خالد بن عدي، فذكره.","grade":"صحيح","chapter_ar":"باب فيمن أُعطي من غير مسألة ولا إشراف نفس","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (17936), Abu Yaʿla (925), and al-Tabarani (4124).","chapter_en":"Regarding one who is given something without asking and without coveting it","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":4,"content":{"translation":{"en":["Khalid ibn ʿAdi al-Juhani said: I heard the Messenger of Allah ﷺ say: “Whoever receives an act of kindness from his brother without asking for it and without his soul yearning for it, let him accept it and not reject it, for it is only provision that Allah, Mighty and Majestic, has sent to him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (17936)، وأبو يعلى (925)، والطبراني (4124)."},{"num":4216,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبيّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قـــــــــال: مَنْ آتَاهُ الله مِنْ هَذَا المَالِ شَيْئًا مِنْ غَيْرِ أَنْ يَسْأَلَهُ فَلْيَقْبَلْهُ فَإِنَّمَا هُوَ رِزْقٌ سَاقَهُ الله عَزَّ وَجَلَّ إِلَيْهِ ."],"takhrij":"صحيح: رواه الإمام أحمد من ثلاثة طرق: منها عن يزيد (7921). ومنها عن عفان (8294). ومنها عن بهز (10358) كلّهم عن همّام بن يحيى، عن قتادة، عن عبد الملك، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب فيمن أُعطي من غير مسألة ولا إشراف نفس","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (7921), (8294), and (10358).","chapter_en":"Regarding one who is given something without asking and without coveting it","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah reported from the Prophet ﷺ that he said: “Whoever is given something from this wealth by Allah without asking for it, let him accept it, for it is provision that Allah, Mighty and Majestic, has sent to him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (7921)، وahmad(8294، 10358)."},{"num":4217,"demo":false,"sanad":"","matn":["عن أبي هريرة، أنّ رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قال: لَيْسَ المسكِينُ بِهَذَا الطَّوَّافِ الَّذِي يَطُوفُ عَلَى النَّاسِ فَتَرُدُّهُ اللُّقْمَةُ وَاللُّقْمَتَانِ وَالتَّمْرَةُ وَالتَّمْرَتَانِ . قَالُوا: فَمَا المِسْكِينُ يَا رَسُولَ الله؟ قَالَ: الَّذِي لا يَجِدُ غِنًى يُغْنِيهِ، وَلا يَفْطَنُ النَّاسُ لَهُ فَيُتَصَدَّقَ عَلَيْهِ، وَلا يَقُومُ فَيَسْأَلَ النَّاسَ ."],"takhrij":"متفق عليه: رواه مالك في كتاب صفة النبيّ صلى الله عليه وسلم  (7) عن أبي الزّناد، عن الأعرج، عن أبي هريرة، أنّ رسول الله صلى الله عليه وسلم  قال (فذكره).","grade":"متفق عليه","chapter_ar":"باب ما جاء في تفسير المسكين","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (7), al-Bukhari (1479), and Muslim (1039).","chapter_en":"What has been reported regarding the definition of the poor person","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “The poor person is not this one who goes around among people and is sent away with one bite or two, or with one date or two.” They said, “Then who is the poor person, O Messenger of Allah ﷺ?” He said: “He is the one who does not find enough to make him self-sufficient, and people do not notice him so that charity may be given to him, and he does not get up and ask people.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13400],"tks":"متفق عليه: رواه مالك (7)، والبخاري (1479)، ومسلم (1039)."},{"num":4218,"demo":false,"sanad":"","matn":["عن أبي هريرة، أنّ رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قال: لَيْسَ المِسْكِينُ بِالَّذِي تَرُدُّهُ التَّمْرَةُ وَالتَّمْرَتَانِ وَلا اللُّقْمَةُ وَاللُّقْمَتَانِ، إِنَّمَا المِسْكِينُ المُتَعَفِّفُ اقْرَءُوا إِنْ شِئْتُمْ: لَا يَسْأَلُونَ النَّاسَ إِلْحَافًا [البقرة: 273] ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4539) ومسلم في الزكاة (1039) كلاهما من حديث محمد بن جعفر، قال حدثني شريك بن أبي نمر، أن عطاء بن يسار وعبد الرحمن بن أبي عمرة الأنصاري قالا: سمعنا أبا هريرة يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تفسير المسكين","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (4539) and Muslim (1039).","chapter_en":"What has been reported regarding the definition of the poor person","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “The poor person is not the one who is turned away with one date or two, nor with one bite or two. Rather, the poor person is the one who restrains himself from asking. Recite, if you wish: ‘They do not ask people persistently.’” [Surah al-Baqarah, 2:273]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4539)، ومسلم (1039)."},{"num":4219,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبيّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قال: لَيْسَ الْمِسْكِينُ الَّذِي تَرُدُّهُ الأُكْلَةَ وَالأُكْلَتَانِ، وَلَكِن المِسْكِينُ الَّذِي لَيْسَ لَهُ غِنًى وَيَسْتَحْيِي أَوْ لا يَسْأَلُ النَّاسَ إِلحَافًا ."],"takhrij":"صحيح: رواه البخاريّ في الزكاة (1476) عن حجاج بن منهال، حدّثنا شعبة، أخبرني محمد بن زياد، قال: سمعت أبا هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تفسير المسكين","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (1476).","chapter_en":"What has been reported regarding the definition of the poor person","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah reported from the Prophet ﷺ that he said: “The poor person is not the one who is turned away with one meal or two. Rather, the poor person is the one who has no sufficiency and feels too shy, or does not ask people persistently.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1476)."},{"num":4220,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: قال رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لَيْسَ المِسْكِينُ الَّذِي تَرُدُّهُ التَّمْرَةُ وَالتَّمْرَتَانِ وَالأَكْلَةُ وَالْأَكْلَتَانِ، وَلَكِنَّ المِسْكِينَ الَّذِي لَا يَسْأَلُ النَّاسَ شَيْئًا وَلَا يَفْطَنُونَ بِهِ فَيُعْطُونَهُ ."],"takhrij":"صحيح: رواه أبو داود (1631) من طرق عن جرير، عن الأعمش، عن أبي صالح، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تفسير المسكين","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (1631).","chapter_en":"What has been reported regarding the definition of the poor person","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “The poor person is not the one who is turned away with one date or two, or one meal or two. Rather, the poor person is the one who does not ask people for anything, and people do not notice him and so they do not give him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1631)."},{"num":4221,"demo":false,"sanad":"","matn":["عن أبي هريرة، أنّ رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قال: وَالَّذِي نَفْسِي بِيَدِهِ لأَنْ يَأْخُذَ أَحَدُكُمْ حَبْلَهُ فَيَحْتَطِبَ عَلَى ظَهْرِهِ خَيْرٌ لَهُ مِنْ أَنْ يَأْتِيَ رَجُلا أَعْطَاهُ الله مِنْ فَضْلِهِ فَيَسْأَلَهُ أَعْطَاهُ أَوْ مَنَعَهُ ."],"takhrij":"متفق عليه: رواه مالك في الصدقة (60) عن أبي الزناد، عن الأعرج، عن أبي هريرة، فذكره. ورواه البخاري في الزكاة (1470) عن عبدالله بن يوسف، عن مالك، ورواه مسلم في الزكاة (1042) من وجه آخر عن أبي هريرة.","grade":"متفق عليه","chapter_ar":"باب الحث على العمل والتكسب","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (60), al-Bukhari (1470), and Muslim (1042).","chapter_en":"Encouragement to work and earn a living","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “By the One in Whose Hand is my soul, if one of you were to take his rope, gather firewood, and carry it on his back, that would be better for him than going to a man whom Allah has given from His bounty and asking him, whether he gives him something or refuses him.”"]}},"tuhfa":{},"full":1,"rep":[5412],"tks":"متفق عليه: رواه مالك (60)، والبخاري (1470)، ومسلم (1042)."},{"num":4222,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَفْتَحُ الْإِنْسَانُ عَلَى نَفْسِهِ بَابَ مَسْأَلَةٍ، إِلَّا فَتَحَ اللَّهُ عَلَيْهِ بَابَ فَقْرٍ، يَأْخُذُ الرَّجُلُ حَبْلَهُ، فَيَعْمِدُ إِلَى الْجَبَلِ، فَيَحْتَطِبُ عَلَى ظَهْرِهِ، فَيَأْكُلُ بِهِ، خَيْرٌ لَهُ مِنْ أَنْ يَسْأَلَ النَّاسَ مُعْطًى أَوْ مَمْنُوعًا."],"takhrij":"صحيح: رواه أحمد (9421)، والطبري في مسند عمر بن الخطاب من تهذيب الآثار (25)، وابن حبان (3387)، والقضاعي في مسند الشهاب (821) كلهم من حديث العلاء بن عبد الرحمن، عن أبيه، عن أبي هريرة فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الحث على العمل والتكسب","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (9421), al-Tabari in Tahdhib al-Athar (25), Ibn Hibban (3387), and al-Qudaʿi in Musnad al-Shihab (821).","chapter_en":"Encouragement to work and earn a living","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “No person opens for himself the door of begging except that Allah opens for him the door of poverty. A man taking his rope, going to the mountain, gathering firewood on his back, and eating from that is better for him than asking people, whether he is given something or refused.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أحمد (9421)، والطبري في تهذيب الآثار (25)، وابن حبان (3387)، والقضاعي في سند الشهاب (821)."},{"num":4223,"demo":false,"sanad":"","matn":["عن الزبير بن العوّام، عن النبيّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قال: لأَنْ يَأْخُذَ أَحَدُكُمْ حَبْلَهُ فَيَأْتِيَ بِحُزْمَةِ الحَطَبِ عَلَى ظَهْرِهِ فَيَبِيعَهَا فَيَكُفَّ الله بِهَا وَجْهَهُ خَيْرٌ لَهُ مِنْ أَنْ يَسْأَلَ النَّاسَ أَعْطَوْهُ أَوْ مَنَعُوهُ ."],"takhrij":"صحيح: رواه البخاريّ في الزكاة (1471) عن موسى، حدثنا وهيب، حدثنا هشام، عن أبيه، عن الزبير بن العوّام، فذكره.","grade":"صحيح","chapter_ar":"باب الحث على العمل والتكسب","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (1471).","chapter_en":"Encouragement to work and earn a living","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":6,"content":{"translation":{"en":["Al-Zubayr ibn al-ʿAwwam reported that the Prophet ﷺ said: “If one of you were to take his rope, bring a bundle of firewood on his back, and sell it, and thereby Allah protects his face, that is better for him than asking people, whether they give him something or withhold it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[5415],"tks":"صحيح: رواه البخاري (1471)."},{"num":4224,"demo":false,"sanad":"","matn":["عن ثوبان، قال: قال رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَنْ يَتَقَبَّلْ لِي بِوَاحِدَةٍ أَتَقَبَّلْ لَهُ بِالجَنَّةِ؟ . قُلْتُ: أَنَا. قَالَ: لا تَسْأَل النَّاسَ شَيْئًا .","قَال: فَكَانَ ثَوْبَانُ يَقَعُ سَوْطُهُ وَهُوَ رَاكِبٌ فَلا يَقُولُ لأَحَدٍ: نَاوِلْنِيهِ حَتَّى يَنْزِلَ فَيَأْخُذَهُ."],"takhrij":"صحيح: رواه أبو داود (1643)، والنسائي (2591)، وابن ماجه (1837) - واللّفظ له - من حديث ابن أبي ذئب، حدثني محمد بن قيس، عن عبدالرحمن بن يزيد بن معاوية، عن ثوبان، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ثواب من لا يسأل الناس شيئًا","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (1643), al-Nasa’i (2591), and Ibn Majah (1837), and this is the wording of Ibn Majah.","chapter_en":"The reward of the one who asks nothing from people","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["Thawban said: The Messenger of Allah ﷺ said: “Who will guarantee one thing for me, and I will guarantee Paradise for him?” I said, “I will.” He said: “Do not ask people for anything.” He said: So when Thawban’s whip fell while he was riding, he would not ask anyone, “Hand it to me,” until he himself got down and picked it up."]},"buhuth":{"en":["In the wording of al-Nasa’i: “Who will guarantee one thing for me, and Paradise will be his?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1643)، والنسائي (2591)، وابن ماجه (1837)، واللفظ له."},{"num":4225,"demo":false,"sanad":"","matn":["عن ابن مسعود، قال: قال رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَنْ أَصَابَتْهُ فَاقَةٌ فَأَنْزَلَهَا بِالنَّاسِ لَمْ تُسَدَّ فَاقَتُهُ وَمَنْ أَنْزَلَهَا بالله أَوْشَكَ الله لَهُ بِالْغِنَى، إِمَّا بِمَوْتٍ عَاجِلٍ أَوْ غِنًى عَاجِلٍ ."],"takhrij":"حسن: رواه أبو داود (1645)، والترمذي (2327) كلاهما من حديث بشير بن سلمان، عن سيار أبي حمزة، عن طارق، عن ابن مسعود، فذكره.","grade":"حسن","chapter_ar":"باب من ابتلي بالفقر فلجأ إلى الله، جعل الله له مخرجًا عاجلًا أو آجلًا","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (1645) and al-Tirmidhi (2327). This is the wording of Abu Dawud.","chapter_en":"Whoever is afflicted by poverty and turns to Allah, Allah will make for him a way out sooner or later","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":8,"content":{"translation":{"en":["Ibn Masʿud said: The Messenger of Allah ﷺ said: “Whoever is struck by poverty and presents it to people, his poverty will not be relieved. But whoever presents it to Allah, Allah will soon grant him sufficiency, either by a quick death or by quick wealth.”"]},"buhuth":{"en":["The wording of al-Tirmidhi is:","“Whoever is afflicted by poverty and presents it to people, his poverty will not be relieved. But whoever is afflicted by poverty and presents it to Allah, Allah will soon send him provision, either sooner or later.”","Al-Tirmidhi said: A hasan sahih gharib hadith.","The phrase “presents it to people” means that he exposes his need to them in order to remove his poverty.","As for the phrase “quick wealth”, its meaning is that Allah sends him sufficiency through hidden means while he does not realize it, such as gifts, grants, and other things. This is indicated by the saying of Allah the Exalted:","“And whoever fears Allah, He will make for him a way out, and will provide for him from where he does not expect.” [Surah al-Talaq, 65:2–3]","And in the wording of al-Tirmidhi: “or later”, meaning that Allah delays his sufficiency for his own benefit, though he may not realize it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1645)، والترمذي (2327). واللفظ لأبي داود."},{"num":4226,"demo":false,"sanad":"","matn":["عن أنس بن مالك، قال: كُنْتُ أَمْشِي مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  وَعَلَيْهِ بُرْدٌ نَجْرَانِيٌّ غَلِيظُ الحَاشِيَةِ فَأَدْرَكَهُ أَعْرَابِيٌّ فَجَذَبَهُ جَذْبَةً شَدِيدَةً حَتَّى نَظَرْتُ إِلَى صَفْحَةِ عَاتِقِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَدْ أَثَّرَتْ بِهِ حَاشِيَةُ الرِّدَاءِ مِنْ شِدَّةِ جَذْبَتِهِ ثُمَّ قَال: مُرْ لِي مِنْ مَالِ الله الَّذِي عِنْدَكَ! فَالْتَفَتَ إِلَيْهِ فَضَحِكَ ثُمَّ أَمَرَ لَهُ بِعَطَاءٍ."],"takhrij":"متفق عليه: رواه البخاريّ في فرض الخمس (3149) عن يحيى بن بكير، ومسلم في الزكاة (1057) من طريق إسحاق بن سليمان الرّازيّ، وابن وهب كلّهم عن مالك بن أنس، عن إسحاق بن عبدالله بن أبي طلحة، عن أنس بن مالك، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب حق السائل لا يسقط ولو أفحش في كلامه","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (3149) and Muslim (1057).","chapter_en":"The right of the one who asks is not dropped even if he speaks harshly","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["Anas ibn Malik said: I was walking with the Prophet ﷺ while he was wearing a Najrani cloak with a rough border. A desert Arab caught up with him and pulled him so forcefully that I looked at the side of the Prophet’s shoulder and saw that the edge of the cloak had left a mark on it because of the severity of his pull. Then he said: “Order that I be given from the wealth of Allah that is with you!” So he turned to him, smiled, and then ordered that something be given to him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3149)، ومسلم (1057)."},{"num":4227,"demo":false,"sanad":"","matn":["عن عمر بن الخطّاب، قال: قَسَمَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَسْمًا فَقُلْتُ: والله يَا رَسُولَ الله لَغَيْرُ هَؤُلاءِ كَانَ أَحَقَّ بِهِ مِنْهُمْ. قَال: إِنَّهُمْ خَيَّرُونِي أَنْ يَسْأَلُونِي بِالْفُحْشِ أَوْ يُبَخِّلُونِي فَلَسْتُ بِبَاخِلٍ ."],"takhrij":"صحيح: رواه مسلم (1056) من طريق جرير، عن الأعمش، عن أبي وائل، عن سلمان بن ربيعة، قال: قال عمر بن الخطّاب، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب حق السائل لا يسقط ولو أفحش في كلامه","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1056).","chapter_en":"The right of the one who asks is not dropped even if he speaks harshly","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["ʿUmar ibn al-Khattab said: The Messenger of Allah ﷺ distributed something, and I said: “By Allah, O Messenger of Allah ﷺ, others besides these were more deserving of it than them.” He said: “They have left me with only two choices: either they ask me with offensive speech, or they accuse me of stinginess, and I am not stingy.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1056)."},{"num":4228,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدريّ، قال: قَالَ عُمَر: يَا رَسُولَ الله، لَقَدْ سَمِعْتُ فُلانًا وَفُلانًا يُحْسِنَانِ الثَّنَاءَ يَذْكُرَانِ أَنَّكَ أَعْطَيْتَهُمَا دِينَارَيْنِ قَالَ: فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لَكِنَّ والله فُلانًا مَا هُوَ كَذَلِكَ، لَقَدْ أَعْطَيْتُهُ مِنْ عَشَرَةٍ إِلَى مِائَةٍ فَمَا يَقُولُ ذَاكَ! أَمَا والله إِنَّ أَحَدَكُمْ لَيُخْرِجُ مَسْأَلَتَهُ مِنْ عِنْدِي يَتَأَبَّطُهَا - يَعْنِي تَكُونُ تَحْتَ إِبْطِهِ- يَعْنِي نَارًا .قَالَ: قَالَ عُمَرُ: يَا رَسُولَ الله لِمَ تُعْطِيهَا إِيَّاهُمْ؟ قَال: فَمَا أَصْنَعُ يَأْبَوْنَ إِلا ذَاكَ وَيَأْبَى الله لِي الْبُخْلَ ."],"takhrij":"صحيح: رواه أحمد (11004)، والبزّار - كشف الأستار (925) - كلاهما من حديث أبي بكر بن عياش، عن الأعمش، عن أبي صالح، عن أبي سعيد، فذكره.","grade":"صحيح","chapter_ar":"باب حق السائل لا يسقط ولو أفحش في كلامه","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (11004), al-Bazzar in Kashf al-Astar (925), and authenticated by Ibn Hibban (3412, 3414).","chapter_en":"The right of the one who asks is not dropped even if he speaks harshly","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: ʿUmar said, “O Messenger of Allah ﷺ, I heard so-and-so and so-and-so” — meaning two men — “speaking well of you and mentioning that you gave them two dinars.” So the Prophet ﷺ said: “But by Allah, so-and-so is not like that. I have given him from ten up to one hundred, yet he does not say that. By Allah, one of you may leave me carrying his request tucked under his arm — meaning that it is fire.” He said: ʿUmar said, “O Messenger of Allah ﷺ, then why do you give it to them?” He said: “What can I do? They insist on that, and Allah refuses for me to be stingy.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (11004)، والبزار في كشف الأستار (925)، وصححه ابن حبان (3412، 3414)."},{"num":4229,"demo":false,"sanad":"","matn":["عَنِ ابْنِ بُجَيْدٍ الأَنْصَارِيِّ ثُمَّ الْحَارِثِيِّ، عَنْ جَدَّتِهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: رُدُّوا السَّائِلَ وَلَوْ بِظِلْفٍ مُحْرَقٍ."],"takhrij":"حسن: رواه مالك في كتاب صفة النبيّ صلى الله عليه وسلم  (8) عن زيد بن أسلم، عن ابن بجيد الأنصاريّ، فذكره. وصحّحه ابن حبان (3374) ورواه من هذا الوجه.","grade":"حسن","chapter_ar":"باب ما جاء في حق السائل أن لا يُرد إلا بشيء ولو كان حقيرًا","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Malik (8), authenticated by Ibn Hibban (3374), and also narrated by Abu Dawud (1667) and al-Tirmidhi (665).","chapter_en":"What has been reported that the one who asks should not be turned away except with something, even if it is small","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":10,"content":{"translation":{"en":["Ibn Bujayd al-Ansari al-Harithi reported from his grandmother that the Messenger of Allah ﷺ said: “Respond to the poor person, even if only with a burnt hoof.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه مالك (8)، وصححه ابن حبان (3374)، ورواه أبو داود (1667)، والترمذي (665)."},{"num":4230,"demo":false,"sanad":"","matn":["عن ابن عباس، أنّ رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قال: أَلا أُخْبِرُكُمْ بِخَيْرِ النَّاسِ مَنْزِلا؟ . قُلْنَا: بَلَى يَا رَسُولَ الله، قَال: رَجُلٌ آخِذٌ بِرَأْسِ فَرَسِهِ فِي سَبِيلِ الله عزوجل حَتَّى يَمُوتَ أَوْ يُقْتَلَ. وَأُخْبِرُكُمْ بِالَّذِي يَلِيهِ؟ . قُلْنَا: نَعَمْ يَا رَسُولَ الله، قَال: رَجُلٌ مُعْتَزِلٌ فِي شِعْبٍ يُقِيمُ الصَّلاةَ وَيُؤْتِي الزَّكَاةَ، وَيَعْتَزِلُ شُرُورَ النَّاسِ. وَأُخْبِرُكُمْ بِشَرِّ النَّاسِ؟ . قُلْنَا: نَعَمْ يَا رَسُولَ الله، قَال: الَّذِي يُسْأَلُ بالله عزوجل وَلا يُعْطِي بِهِ ."],"takhrij":"حسن: رواه النسائي (2569) عن محمد بن رافع، حدّثنا ابن أبي فديك، قال: أخبرنا ابن أبي ذئب، عن سعيد بن خالد القارظي، عن إسماعيل بن عبدالرحمن، عن عطاء بن يسار، عن ابن عباس، فذكره.","grade":"حسن","chapter_ar":"باب من يُسأل بالله عز وجل ولا يعطي به","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by al-Nasa’i (2569), Ibn Hibban in his Sahih (604), Ahmad (2116), and al-Tirmidhi (1652), who graded it hasan.","chapter_en":"The one who is asked in the name of Allah and does not give","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿAbbas reported that the Messenger of Allah ﷺ said: “Shall I tell you about the best of people in rank?” We said: “Yes, O Messenger of Allah ﷺ.” He said: “A man holding the reins of his horse in the path of Allah, Mighty and Majestic, until he dies or is killed. Shall I tell you about the one next to him?” We said: “Yes, O Messenger of Allah ﷺ.” He said: “A man living apart in a mountain pass, establishing prayer, giving zakah, and keeping away from the evils of people. Shall I tell you about the worst of people?” We said: “Yes, O Messenger of Allah ﷺ.” He said: “The one who is asked in the name of Allah, Mighty and Majestic, and does not give.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (2569)، وابن حبان في صحيحه (604)، وأحمد (2116)، والترمذي (1652) وحسنه."},{"num":4231,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: قال رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَنْ اسْتَعَاذَكُمْ بالله فَأَعِيذُوهُ، وَمَنْ سَأَلَكُمْ بالله فَأَعْطُوهُ، وَمَنْ دَعَاكُمْ فَأَجِيبُوهُ، وَمَنْ آتَى إِلَيْكُمْ مَعْرُوفًا فَكَافِئُوهُ، فَإِنْ لَمْ تَجِدُوا فَادْعُوا الله لَهُ حَتَّى تَعْلَمُوا أَنْ قَدْ كَافَأْتُمُوهُ ."],"takhrij":"صحيح: رواه أبو داود (5109)، والنسائي (2568) كلاهما من حديث أبي عوانة (هو وضّاح اليشكري)، عن الأعمش، عن مجاهد، عن ابن عمر، فذكره.","grade":"صحيح","chapter_ar":"باب من يُسأل بالله عز وجل ولا يعطي به","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (5109) and al-Nasa’i (2568).","chapter_en":"The one who is asked in the name of Allah and does not give","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said: “Whoever seeks your protection in the name of Allah, then grant him protection. Whoever asks you in the name of Allah, then give to him. Whoever invites you, then answer him. Whoever does you a favor, then repay him. If you do not find anything with which to repay him, then supplicate to Allah for him until you know that you have repaid him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (5109)، والنسائي (2568)."},{"num":4232,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: قال رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَنْ سَأَلَكُمْ بالله فَأَعْطُوهُ، وَمَنْ دَعَاكُمْ فَأَجِيبُوهُ، وَلَوْ أُهْدِيَ إِلَيَّ كُرَاعٌ لَقَبِلْتُ، وَلَوْ دُعِيتُ إِلَى كُرَاعٍ لأَجَبْتُ ."],"takhrij":"صحيح: رواه الإمام أحمد (10651) عن أسود بن عامر، أخبرنا أبو بكر بن عياش، عن الأعمش، عن أبي حازم، عن أبي هريرة، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب من يُسأل بالله عز وجل ولا يعطي به","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (10651), and authenticated by al-Hakim (1506).","chapter_en":"The one who is asked in the name of Allah and does not give","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Whoever asks you in the name of Allah, then give to him. Whoever invites you, then answer him. Even if a simple lower leg (trotter) were given to me as a gift, I would accept it, and if I were invited to a meal of a lower leg (trotter), I would respond.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (10651)، وصححه الحاكم (1506)."},{"num":4233,"demo":false,"sanad":"","matn":["عن ابن عباس، أنّ رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قال: مَنْ اسْتَعَاذَ بالله فَأَعِيذُوهُ، وَمَنْ سَأَلَكُمْ بِوَجْهِ الله فَأَعْطُوهُ .","وفي رواية: مَنْ سَأَلَكُمْ بالله ."],"takhrij":"حسن: رواه أبو داود (5108) عن نصر بن علي، وعبيدالله بن عمر الجشميّ، قالا: حدّثنا خالد بن الحارث، حدّثنا سعيد - قال نصر: ابن أبي عروبة -، عن قتادة، عن أبي نهيك، عن ابن عباس، فذكره.","grade":"حسن","chapter_ar":"باب المبايعة على عدم سؤال الناس شيئًا","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (5108).","chapter_en":"Giving the pledge not to ask people for anything","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbas reported that the Messenger of Allah ﷺ said: “Whoever seeks refuge by Allah, then grant him refuge. And whoever asks you by the Face of Allah, then give to him.” And in another narration: “Whoever asks you by Allah.”"]},"buhuth":{"en":["Understanding of the chapter:","This was during the time of the Prophet ﷺ. As for today, most beggars are not truly in need; rather, many of them are deceptive. So it is better not to give them anything, so that others are not also encouraged to take up begging."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (5108)."},{"num":4234,"demo":false,"sanad":"","matn":["عن عوف بن مالك الأشجعيّ، قال: كُنَّا عِنْدَ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  تِسْعَةً أَوْ ثَمَانِيَةً أَوْ سَبْعَةً فَقَالَ: أَلا تُبَايِعُونَ رَسُولَ الله؟ . وَكُنَّا حَدِيثَ عَهْدٍ بِبَيْعَةٍ فَقُلْنَا: قَدْ بَايَعْنَاكَ يَا رَسُولَ الله ثُمَّ قَالَ: أَلا تُبَايِعُونَ رَسُولَ الله؟ . فَقُلْنَا: قَدْ بَايَعْنَاكَ يَا رَسُولَ الله، ثُمَّ قَالَ: أَلا تُبَايِعُونَ رَسُولَ الله؟ . قَالَ: فَبَسَطْنَا أَيْدِيَنَا وَقُلْنَا: قَدْ بَايَعْنَاكَ يَا رَسُولَ الله فَعَلامَ نُبَايِعُكَ؟ قَالَ: عَلَى أَنْ تَعْبُدُوا الله وَلا تُشْرِكُوا بِهِ شَيْئًا، وَالصَّلَوَاتِ الخَمْسِ، وَتُطِيعُوا - وَأَسَرَّ كَلِمَةً خَفِيَّةً - وَلا تَسْأَلُوا النَّاسَ شَيْئًا .","فَلَقَدْ رَأَيْتُ بَعْضَ أُولَئِكَ النَّفَرِ يَسْقُطُ سَوْطُ أَحَدِهِمْ فَمَا يَسْأَلُ أَحَدًا يُنَاوِلُهُ إِيَّاهُ."],"takhrij":"صحيح: رواه مسلم في الزكاة (1043) من طريق مروان بن محمد الدّمشقيّ، ثنا سعيد، عن ربيعة بن يزيد، عن أبي إدريس الخولانيّ، عن أبي مسلم الخولانيّ، عن عوف بن مالك الأشجعيّ، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب المبايعة على عدم سؤال الناس شيئًا","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1043).","chapter_en":"Giving the pledge not to ask people for anything","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":12,"content":{"translation":{"en":["ʿAwf ibn Malik al-Ashjaʿi said: We were with the Messenger of Allah ﷺ, nine or eight or seven of us, and he said: “Will you not give the pledge to the Messenger of Allah ﷺ?” We had only recently given a pledge, so we said: “We already gave you the pledge, O Messenger of Allah ﷺ.” Then he said: “Will you not give the pledge to the Messenger of Allah ﷺ?” So we said: “We already gave you the pledge, O Messenger of Allah ﷺ.” Then he said: “Will you not give the pledge to the Messenger of Allah ﷺ?” He said: So we stretched out our hands and said: “We have already pledged to you, O Messenger of Allah ﷺ, so upon what shall we pledge to you?” He said: “That you worship Allah and do not associate anything with Him, establish the five prayers, and obey…” Then he said quietly a hidden phrase: “And do not ask people for anything.”","I truly saw some of those men whose whip would fall from one of them, and he would not ask anyone to hand it back to him."]}},"tuhfa":{},"full":1,"rep":[240,7644],"tks":"صحيح: رواه مسلم (1043)."},{"num":4235,"demo":false,"sanad":"","matn":["عن عبدالله بن عمر، قال: قال النبيّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَا يَزَالُ الرَّجُلُ يَسْأَلُ النَّاسَ حَتَّى يَأْتِيَ يَوْمَ الْقِيَامَةِ وَلَيْسَ فِي وَجْهِهِ مُزْعَةُ لحْمٍ ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1474)، ومسلم في الزكاة (1040: 104) كلاهما من طريق الليث، عن عبيدالله بن أبي جعفر، عن حمزة بن عبيدالله بن عمر، أنه سمع أباه، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الترهيب من المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1474) and Muslim (1040 no. 104).","chapter_en":"Reports warning severely against begging","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: The Prophet ﷺ said: “A man continues asking people until he comes on the Day of Resurrection with not a shred of flesh on his face.”"]},"buhuth":{"en":["The phrase “a shred of flesh” means a small piece of flesh."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1474)، ومسلم (1040: 104)."},{"num":4236,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: سمعت رسول لله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  يقول: المَسْأَلَةُ كُدُوحٌ فِي وَجْهِ صَاحِبِهَا يَوْمَ الْقِيَامَةِ، فَمَنْ بَدَنَ فَلْيَسْتَبْقِ عَلَى وَجْهِهِ وَأَهْوَنُ المَسْأَلَةِ مَسْأَلَةُ ذِي الرَّحِمِ تَسْأَلُهُ فِي حَاجَةٍ، وَخَيْرُ المَسْأَلَةِ المَسْأَلَةُ عَنْ ظَهْرِ غِنًى، وَابْدَأْ بِمَنْ تَعُولُ ."],"takhrij":"صحيح: رواه الإمام أحمد (5680) عن أبي النّضر، حدّثنا إسحاق بن سعيد، عن أبيه، عن ابن عمر، قال (فذكره). وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء من الترهيب من المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Imam Ahmad (5680).","chapter_en":"Reports warning severely against begging","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Ibn ʿUmar said: I heard the Messenger of Allah ﷺ say: “Begging is scratches on the face of its owner on the Day of Resurrection. So whoever wishes may leave such marks on his face. The lightest form of asking is when one asks a relative for a need. And the best asking is asking from a position of sufficiency. And begin with those under your care.”"]},"buhuth":{"en":["As for the phrase “the best asking”, this is how it appears in the Musnad and in Majmaʿ al-Zawa’id. The more well-known wording is: “The best charity is that given while one remains self-sufficient,” as mentioned earlier. If this wording is correct, then its meaning is that if a person must ask, then he should ask a generous wealthy person who gives charity while living in abundance."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (5680)."},{"num":4237,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدريّ، قال: قال رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّ هَذَا المَالَ خَضِرَةٌ حُلْوَةٌ فَنِعْمَ صَاحِبُ المُسْلِمِ مَا أَعْطَى مِنْهُ الْمِسْكِينَ وَالْيَتِيمَ وَابْنَ السَّبِيلِ أَوْ كَمَا قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَإِنَّهُ مَنْ يَأْخُذُهُ بِغَيْرِ حَقِّهِ كَالَّذِي يَأْكُلُ وَلا يَشْبَعُ وَيَكُونُ شَهِيدًا عَلَيْهِ يَوْمَ الْقِيَامَةِ ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1465)، ومسلم في الزكاة (1052: 123) كلاهما من طريق هشام الدّستوائيّ، عن يحيى بن أبي كثير، عن هلال بن أبي ميمونة، عن عطاء بن يسار، عن أبي سعيد الخدريّ، فذكره في حديث طويل يأتي بتمامه في موضعه.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الترهيب من المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1465) and Muslim (1052 no. 123).","chapter_en":"Reports warning severely against begging","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: The Messenger of Allah ﷺ said: “This wealth is fresh and sweet. What an excellent possession it is for a Muslim when he gives from it to the poor person, the orphan, and the traveler” — or as the Prophet ﷺ said — “but whoever takes it without right is like one who eats and is never satisfied, and it will testify against him on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1465)، ومسلم (1052: 123)."},{"num":4238,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: قال رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَنْ سَأَلَ النَّاسَ أَمْوَالَهُمْ تَكَثُّرًا فَإِنَّمَا يَسْأَلُ جَمْرًا فَلْيَسْتَقِلَّ أَوْ لِيَسْتَكْثِرْ ."],"takhrij":"صحيح: رواه مسلم في الزّكاة (1041) من طرق عن ابن فضيل، عن عمارة بن القعقاع، عن أبي زرعة، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء من الترهيب من المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1041).","chapter_en":"Reports warning severely against begging","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Whoever asks people for their wealth in order to increase his own wealth is only asking for burning coals. So let him ask for little of it or much.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1041)."},{"num":4239,"demo":false,"sanad":"","matn":["عن عبدالله بن مسعود، قال: قال رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَنْ سَأَلَ وَلَهُ مَا يُغْنِيهِ جَاءَتْ يَوْمَ الْقِيَامَةِ خُمُوشٌ أَوْ خُدُوشٌ أَوْ كُدُوحٌ فِي وَجْهِهِ . فَقَالَ يَا رَسُولَ الله، وَمَا الْغِنَى؟ قَال: خَمْسُونَ دِرْهَمًا أَوْ قِيمَتُهَا مِنْ الذَّهَبِ ."],"takhrij":"صحيح: رواه أبو داود (1626) -واللّفظ له-، والنسائي (2593)، وابن ماجه (1840) كلّهم من طريق يحيى بن آدم، حدّثنا سفيان، عن حكيم بن جبير، عن محمد بن عبدالرحمن بن يزيد، عن أبيه، عن عبدالله، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء من الترهيب من المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (1626) — this is his wording — al-Tirmidhi (650), al-Nasa’i (2593), and Ibn Majah (1840).","chapter_en":"Reports warning severely against begging","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullah ibn Masʿud said: The Messenger of Allah ﷺ said: “Whoever asks while having what is enough for him will come on the Day of Resurrection with scratches, claw marks, or wounds on his face.” It was said: “O Messenger of Allah ﷺ, what counts as sufficiency?” He said: “Fifty dirhams, or their value in gold.”"]},"buhuth":{"en":["The word “khumush” is like “khudush” in both pattern and meaning.","And “kuduh” means the marks left by scratches; every trace made by scratching, biting, and the like is called kuduh."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1626) — واللفظ له — والترمذي (650)، والنسائي (2593)، وابن ماجه (1840)."},{"num":4240,"demo":false,"sanad":"","matn":["عن سمرة بن جندب، عن النبيّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قال: المَسَائِلُ كُدُوحٌ يَكْدَحُ بِهَا الرَّجُلُ وَجْهَهُ فَمَنْ شَاءَ أَبْقَى عَلَى وَجْهِهِ وَمَنْ شَاءَ تَرَكَ، إِلا أَنْ يَسْأَلَ الرَّجُلُ ذَا سُلْطَانٍ أَوْ فِي أَمْرٍ لا يَجِدُ مِنْهُ بُدًّا ."],"takhrij":"صحيح: رواه أبو داود (1639)، والنسائي (2600)، والترمذيّ (681) كلّهم من حديث شعبة، عن عبد الملك بن عمير، عن زيد بن عقبة الفزاريّ، عن سمرة بن جندب، فذكره. إلاّ أن الترمذي فقد رواه من حديث سفيان، عن عبد الملك بن عمير، وقال: حديث حسن صحيح .","grade":"صحيح","chapter_ar":"باب ما جاء من الترهيب من المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (1639), al-Nasa’i (2600), al-Tirmidhi (681), and authenticated by Ibn Hibban (3397).","chapter_en":"Reports warning severely against begging","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Samurah ibn Jundub reported from the Prophet ﷺ that he said: “Requests are wounds by which a man wounds his face. So whoever wishes may leave such marks on his face, and whoever wishes may leave them off — except when a person asks a ruler, or in a matter in which he has no other choice.”"]},"buhuth":{"en":["In one narration: “when a man asks a ruler”, meaning the one who controls the public treasury, so he may give him from it if he deserves it.","And in the wording of al-Tirmidhi: “a strain by which a man strains his face.”","The word kadd means hardship in labor and in seeking earnings, which produces toil and exhaustion in the face."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1639)، والنسائي (2600)، والترمذي (681)، وصححه ابن حبان (3397)."},{"num":4241,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّ الرَّجُلَ مِنْكُمْ لَيَأْتِينِي فَيَسْألُنِي فَأُعْطِيهِ فَيَنْطَلِقُ، وَمَا يَحْمِلُ فِي حِضْنِهِ إِلَّا النَّارَ."],"takhrij":"صحيح: رواه عبد بن حميد (1113) عن عبيدالله بن موسى، عن إسرائيل بن يونس، عن منصور، عن سالم بن أبي الجعد، عن جابر، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء من الترهيب من المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by ʿAbd ibn Humayd (1113), and authenticated by Ibn Hibban (3392).","chapter_en":"Reports warning severely against begging","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said: “A man among you may come to me and ask me, and I give him, then he leaves carrying nothing in his lap except fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه عبد بن حميد (1113)، وصححه ابن حبان (3392)."},{"num":4242,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ سَأَلَ مَسْأَلَةً وَهُوَ عَنْهَا غَنِيٌّ، كَانَتْ شَيْئًا فِي وَجْهِهِ يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه أحمد (22420)، والبزّار -كشف الأستار (932)-، والطبراني في الكبير (1407) كلّهم من طريق يزيد بن زريع، عن سعيد ابن أبي عروبة، عن قتادة، عن سالم بن أبي الجعد، عن معدان بن أبي طلحة، عن ثوبان، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الترهيب من المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (22420), al-Bazzar in Kashf al-Astar (932), and al-Tabarani in al-Kabir (1407).","chapter_en":"Reports warning severely against begging","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Thawban reported from the Prophet ﷺ that he said: “Whoever asks for something while he is free of need of it, it will be a blemish on his face on the Day of Resurrection.”"]},"buhuth":{"en":["The word “shayn” means a mark and a disgrace."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (22420)، والبزار في كشف الأستار (932)، والطبراني في الكبير (1407)."},{"num":4243,"demo":false,"sanad":"","matn":["عن سهل ابن الحنظليّة - صاحب رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  - قال: قَدِمَ عَلَى رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  عُيَيْنَةُ بْنُ حِصْنٍ وَالأَقْرَعُ بْنُ حَابِسٍ فَسَأَلاهُ فَأَمَرَ لهُمَا بِمَا سَأَلا وَأَمَرَ مُعَاوِيَةَ فَكَتَبَ لهُمَا بِمَا سَأَلا، فَأَمَّا الأَقْرَعُ فَأَخَذَ كِتَابَهُ فَلَفَّهُ فِي عِمَامَتِهِ وَانْطَلَقَ، وَأَمَّا عُيَيْنَةُ فَأَخَذَ كِتَابَهُ وَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  مَكَانَهُ فَقَالَ: يَا مُحَمَّدُ أَتُرَانِي حَامِلا إِلَى قَوْمِي كِتَابًا لا أَدْرِي مَا فِيهِ كَصَحِيفَـةِ المُتَلَمِّسِ! فَأَخْبَرَ مُعَاوِيَةُ بِقَوْلِهِ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَقَـــالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَنْ سَأَلَ وَعِنْدَهُ مَا يُغْنِيهِ فَإِنَّمَا يَسْتَكْثِرُ مِنْ النَّارِ - وَقَالَ النُّفَيْلِيُّ فِي مَوْضِعٍ آخَرَ: مِنْ جَمْرِ جَهَنَّمَ - فَقَالُوا: يَا رَسُولَ الله وَمَا يُغْنِيهِ؟ - وَقَالَ النُّفَيْلِيُّ فِي مَوْضِعٍ آخَرَ: وَمَا الْغِنَى الَّذِي لا تَنْبَغِي مَعَهُ المَسْأَلَةُ؟ - قَالَ: قَدْرُ مَا يُغَدِّيهِ وَيُعَشِّيه ."],"takhrij":"صحيح: رواه أبو داود (1629) عن عبدالله بن محمد النّفيليّ، حدّثنا مسكين، حدّثنا محمد بن المهاجر، عن ربيعة بن يزيد، عن أبي كبشة السّلوليّ، حدّثنا سهل بن الحنظلية، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء من الترهيب من المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (1629), Ahmad (17625), and authenticated by Ibn Khuzaymah (2391) and Ibn Hibban (3394, 545).","chapter_en":"Reports warning severely against begging","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Sahl ibn al-Hanzaliyyah — a companion of the Messenger of Allah ﷺ — said: ʿUyaynah ibn Hisn and al-Aqraʿ ibn Habis came to the Messenger of Allah ﷺ and asked him. He ordered that they be given what they asked for, and he instructed Muʿawiyah to write for them what they had requested. As for al-Aqraʿ, he took his paper, wrapped it in his turban, and left. But ʿUyaynah took his paper and came back to the Prophet ﷺ and said: “Muhammad, do you expect me to carry to my people a document whose contents I do not know, like the document of al-Mutalammis?” So Muʿawiyah informed the Messenger of Allah ﷺ of what he had said, and the Messenger of Allah ﷺ said: “Whoever asks while having what is enough for him is only seeking more fire for himself” — and al-Nufayli said elsewhere: “from the embers of Hell.” They said: “O Messenger of Allah ﷺ, what counts as enough for him?” And al-Nufayli said elsewhere: “What is the level of wealth with which asking is no longer proper?” He said: “Enough to provide him with his morning and evening meal.”"]},"buhuth":{"en":["As for the phrase “the document of al-Mutalammis”: al-Mutalammis was Jarir ibn ʿAbd al-Masih al-Dabbi, a well-known pre-Islamic poet. He and Tarafah ibn al-ʿAbd satirized ʿAmr ibn Hind, the king of al-Hirah. So he wrote two letters to his governor and made them think they contained rewards, while in fact he had written ordering their execution. Al-Mutalammis opened his letter, understood what it contained, fled, and survived. Tarafah, however, took the letter to the governor hoping for a reward, and was killed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1629)، وأحمد (17625)، وصححه ابن خزيمة (2391)، وابن حبان (3394، 545)."},{"num":4244,"demo":false,"sanad":"","matn":["عن عبيدالله بن عدي بن الخيار، أَنَّ رَجُلَيْنِ حَدَّثَاهُ أَنَّهُمَا أَتَيَا رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  يَسْأَلانِهِ مِن الصَّدَقَةِ فَقَلَّبَ فِيهِمَا الْبَصَرَ، فَرَآهُمَا جَلْدَيْنِ فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنْ شِئْتُمَا أعطيتُكُما ولا حَظَّ فِيهَا لِغَنِيٍّ ولا لِقَوِيٍّ مُكْتَسِبٍ ."],"takhrij":"صحيح: رواه أبو داود (1633)، والنسائيّ (2599) كلاهما من حديث هشام بن عروة، عن أبيه، عن عبيدالله بن عدي، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب فيمن لا تحل له المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (1633), al-Nasa’i (2598), and Imam Ahmad (17972).","chapter_en":"Those for whom asking is not lawful","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":14,"content":{"translation":{"en":["ʿUbaydullah ibn ʿAdi ibn al-Khiyar reported that two men told him that they came to the Messenger of Allah ﷺ asking him for charity. He looked them over carefully and saw that they were strong and healthy. So the Messenger of Allah ﷺ said: “If you both wish, I will give to you, but there is no share in it for a rich person nor for a strong person capable of earning.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12475],"tks":"صحيح: رواه أبو داود (1633)، والنسائي (2599)، والإمام أحمد (17972)."},{"num":4245,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: قال رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لا تَحِلُّ الصَّدَقَةُ لِغَنِيٍّ وَلا لِذِي مِرَّةٍ سَوِيٍّ ."],"takhrij":"صحيح: رواه النسائيّ (2598)، وابن ماجه (1839) كلاهما من حديث أبي بكر بن عياش، عن أبي حُصين، عن سالم بن أبي الجعد، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب فيمن لا تحل له المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasa’i (2598), Ibn Majah (1839), and authenticated by Ibn Hibban (3290).","chapter_en":"Those for whom asking is not lawful","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":14,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Charity is not lawful for a wealthy person, nor for one who is strong and sound.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (2598)، وابن ماجه (1839)، وصححه ابن حبان (3290)."},{"num":4246,"demo":false,"sanad":"","matn":["عن عبدالله بن عمرو، عن النبيّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قال: لا تَحِلُّ الصَّدَقَةُ لِغَنِيٍّ وَلا لِذِي مِرَّةٍ سَوِيٍّ ."],"takhrij":"حسن: رواه أبو داود (1634)، والترمذي (652) كلاهما من حديث سعد بن إبراهيم، عن ريحان بن يزيد، عن عبدالله بن عمرو، فذكره.","grade":"حسن","chapter_ar":"باب فيمن لا تحل له المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (1634), al-Tirmidhi (652), who graded it hasan, and al-Hakim (1478).","chapter_en":"Those for whom asking is not lawful","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs reported from the Prophet ﷺ that he said: “Charity is not lawful for a rich person, nor for one who is strong and physically sound.”"]},"buhuth":{"en":["The word “mirrah” means strength and vigor.","And “sawiyy” describes such a person as physically sound and healthy in body."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1634)، والترمذي (652) وحسنه، والحاكم (1478)."},{"num":4247,"demo":false,"sanad":"","matn":["عن رجل من بني هلال، قال: سمعت رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  يقول: لا تَصْلُحُ الصَّدَقَةُ لِغَنِيٍّ وَلا لِذِي مِرَّةٍ سَوِيٍّ ."],"takhrij":"حسن: رواه أحمد (16594) عن أبي عبدالرحمن عبدالله بن يزيد، قال: حدّثنا عكرمة، قال: حدّثنا أبو زُميل سماك، قال: حدّثني رجل من بني هلال، فذكره.","grade":"حسن","chapter_ar":"باب فيمن لا تحل له المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (16594).","chapter_en":"Those for whom asking is not lawful","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":14,"content":{"translation":{"en":["A man from Banu Hilal said: I heard the Messenger of Allah ﷺ say: “Charity is not suitable for a rich person, nor for one who is strong and sound.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (16594)."},{"num":4248,"demo":false,"sanad":"","matn":["عَنْ حُبْشِيِّ بْنِ جُنَادَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ سَأَلَ مِنْ غَيْرِ فَقْرٍ، فَكَأَنَّمَا يَأْكُلُ الْجَمْرَ."],"takhrij":"صحيح: رواه أحمد (17508، 17509)، والطبرانيّ في المعجم الكبير (3506، 3508)، وابن خزيمة في صحيحه (2446)، والبيهقي في شعب الإيمان (3241) كلهم من حديث أبي إسحاق السبيعي، قال: حدثنا حُبشي بن جُنادة السلولي، قال: فذكره.","grade":"صحيح","chapter_ar":"باب فيمن لا تحل له المسألة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (17508, 17509), al-Tabarani in al-Kabir (3506, 3508), and Ibn Khuzaymah in his Sahih (2446).","chapter_en":"Those for whom asking is not lawful","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":14,"content":{"translation":{"en":["Hubshi ibn Junadah said: The Messenger of Allah ﷺ said: “Whoever asks without being poor, it is as though he is eating burning coals.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (17508، 17509)، والطبراني في الكبير (3506، 3508)، وابن خزيمة في صحيحه (2446)."},{"num":4249,"demo":false,"sanad":"","matn":["عن أبي هريرة، أَنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  صَلَّى عَلَى رَجُلٍ تَرَكَ دِينَارَيْنِ أَوْ ثَلاثَةً فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : كَيَّتَانِ أَوْ ثَلاثَةٌ ."],"takhrij":"صحيح: رواه أحمد (9538)، والبزار - كشف الأستار (3650) كلاهما من حديث يحيى بن سعيد، عن فضيل بن غزوان، قال: حدثني أبو حازم، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء من الترهيب للغني الذي يظهر الفقر ليتصدق عليه الناس","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (9538), and al-Bazzar in Kashf al-Astar (3650).","chapter_en":"Warnings for the wealthy person who pretends to be poor so people will give him charity","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ prayed over a man who had left behind two or three dinars, and the Prophet ﷺ said: “Two brands or three.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (9538)، والبزار في كشف الأستار (3650)."},{"num":4250,"demo":false,"sanad":"","matn":["عن عبدالله بن مسعود، قال: لَحِقَ بِالنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  عَبْدٌ أَسْوَدُ فَمَاتَ فَأُوذِنَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَقَالَ: انْظُرُوا هَلْ تَرَكَ شَيْئًا؟ . فَقَالُوا: تَرَكَ دِينَارَيْنِ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : كَيَّتَانِ ."],"takhrij":"حسن: رواه الإمام أحمد (3843)، وأبو يعلى (4997) كلاهما من حديث زائدة، عن عاصم بن أبي النجود، عن زر، عن عبدالله، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الترهيب للغني الذي يظهر الفقر ليتصدق عليه الناس","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (3843), Abu Yaʿla (4997), and authenticated by Ibn Hibban (3263).","chapter_en":"Warnings for the wealthy person who pretends to be poor so people will give him charity","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":15,"content":{"translation":{"en":["ʿAbdullah ibn Masʿud said: A Black servant joined the Prophet ﷺ and then died. The Prophet ﷺ was informed, and he said: “Look and see whether he left anything behind.” They said: “He left two dinars.” So the Prophet ﷺ said: “Two brands.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (3843)، وأبو يعلى (4997)، وصححه ابن حبان (3263)."},{"num":4251,"demo":false,"sanad":"","matn":["عن أبي أمامة: أَنَّ رَجُلا مِنْ أَهْلِ الصُّفَّةِ تُوُفِّيَ وَتَرَكَ دِينَارًا فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لَهُ كَيَّةٌ . قَالَ: ثُمَّ تُوُفِّيَ آخَرُ فَتَرَكَ دِينَارَيْنِ، فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : كَيَّتَانِ ."],"takhrij":"حسن: رواه الإمام أحمد (22172) عن حجّاج، قال: سمعت شعبة يحدّث عن قتادة، وهاشم، قال: حدّثني شعبة، أخبرنا قتادة، قال: سمعت أبا الجعد يحدّث - قال هاشم في حديثه: أبو الجعد مولى لبني ضُبيعة -، عن أبي أمامة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الترهيب للغني الذي يظهر الفقر ليتصدق عليه الناس","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (22172), and al-Tabarani in al-Kabir (7573).","chapter_en":"Warnings for the wealthy person who pretends to be poor so people will give him charity","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":15,"content":{"translation":{"en":["Abu Umamah reported that a man from the people of al-Suffah died and left behind one dinar, so the Messenger of Allah ﷺ said: “One brand.” Then another died and left behind two dinars, so the Messenger of Allah ﷺ said: “Two brands.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (22172)، والطبراني في الكبير (7573)."},{"num":4252,"demo":false,"sanad":"","matn":["عن المغيرة بن شعبة، أنّه سَمِع النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  يَقُولُ: إِنَّ الله كَرِهَ لَكُمْ ثَلاثًا: قِيلَ وَقَالَ، وَإِضَاعَةَ المالِ، وَكَثْرَةَ السُّؤَالِ ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1477)، ومسلم في الأقضية (593: 13) كلاهما من طريق إسماعيل بن عليّة، عن خالد الحذّاء، حدّثني ابن أَشْوَع، عن الشعبيّ، حدّثني كاتب المغيرة بن شعبة، قال: كتب معاوية إلى المغيرة بن شعبة: أن اكتب إليَّ بشيء سمعتَه من النبيّ صلى الله عليه وسلم ، فكتب إليه سمعت النبيَّ صلى الله عليه وسلم  يقول (فذكره).","grade":"متفق عليه","chapter_ar":"باب كراهية كثرة السؤال","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1477) and Muslim (593 no. 13).","chapter_en":"The dislike of excessive asking","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":16,"content":{"translation":{"en":["Al-Mughirah ibn Shuʿbah reported that he heard the Prophet ﷺ say: “Allah has disliked for you three things: gossiping with ‘it was said’ and ‘he said,’ wasting wealth, and asking too much.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1477)، ومسلم (593: 13)."},{"num":4253,"demo":false,"sanad":"","matn":["عن بهز بن حكيم، عن أبيـه، عن جـدِّه، قـال: سمعت رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  يقول: لا يَأْتِي رَجُلٌ مَوْلاهُ يَسْأَلُهُ مِنْ فَضْلٍ عِنْدَهُ فَيَمْنَعُهُ إِيَّاهُ إِلا دُعِيَ لَهُ يَوْمَ الْقِيَامَةِ شُجَاعٌ أَقْرَعُ يَتَلَمَّظُ فَضْلَهُ الَّذِي مَنَعَ ."],"takhrij":"حسن: رواه النسائيّ (2566)، وأبو داود إثر حديث رقم (5139) كلاهما من حديث بهز بن حكيم، بإسناده، مثله، واللفظ للنسائيّ.","grade":"حسن","chapter_ar":"باب كراهية منع الفضل لقريب محتاج إذا سأله","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by al-Nasa’i (2566), and Abu Dawud after hadith no. (5139), and this is the wording of al-Nasa’i.","chapter_en":"The dislike of withholding surplus from a needy relative when he asks","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":17,"content":{"translation":{"en":["Bahz ibn Hakim, from his father, from his grandfather, said: I heard the Messenger of Allah ﷺ say: “No man comes to his master asking him from surplus that he has, and then his master withholds it from him, except that on the Day of Resurrection a bald-headed serpent will be called for him, licking its lips over the surplus that he withheld.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (2566)، وأبو داود عقب حديث رقم (5139)، واللفظ للنسائي."},{"num":4254,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدريّ، قـال: أُصِيبَ رَجُـلٌ فِي عَهْـدِ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فِي ثِمَارٍ ابْتَاعَهَا فَكَثُرَ دَيْنُهُ فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : تَصَدَّقُوا عَلَيْهِ . فَتَصَدَّقَ النَّاسُ عَلَيْهِ فَلَمْ يَبْلُغْ ذَلِكَ وَفَاءَ دَيْنِهِ. فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  لِغُرَمَائِهِ: خُذُوا مَا وَجَدْتُمْ وَلَيْسَ لَكُمْ إِلا ذَلِكَ ."],"takhrij":"صحيح: رواه مسلم في كتاب المساقاة (1556) عن قتيبة بن سعيد، حدّثنا ليث، عن بكير بن الأشج، عن عياض بن عبدالله، عن أبي سعيد، فذكره.","grade":"صحيح","chapter_ar":"باب من تحل له الصدقة من الغارمين وغيرهم","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1556).","chapter_en":"Those for whom charity is lawful, including debtors and others","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":18,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: A man during the time of the Messenger of Allah ﷺ suffered a loss concerning fruits he had purchased, and his debt became heavy. So the Messenger of Allah ﷺ said: “Give charity to him.” So people gave charity to him, but it did not cover his debt in full. Then the Messenger of Allah ﷺ said to his creditors: “Take what you find, and you have no right to anything beyond that.”"]},"intro":{"ar":["قال الله تعالى:","( إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَابْنِ السَّبِيلِ فَرِيضَةً مِنَ اللَّهِ وَاللَّهُ عَلِيمٌ حَكِيمٌ ) [سورة التوبة: ٦٠]."],"en":["Allah the Exalted said:","“Zakah expenditures are only for the poor, the needy, those employed to collect it, those whose hearts are to be reconciled, for freeing slaves, for those in debt, in the cause of Allah, and for the stranded traveler — an obligation from Allah. And Allah is All-Knowing, All-Wise.” [Surah al-Tawbah, 9:60]"]}},"tuhfa":{},"full":1,"rep":[5634,5765,12484],"tks":"صحيح: رواه مسلم (1556)."},{"num":4255,"demo":false,"sanad":"","matn":["عن قبيصة بن مُخارق الهلاليّ، قال: تَحَمَّلْتُ حَمَالَةً فَأَتَيْتُ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  أَسْأَلُهُ فِيهَا فَقَالَ: أَقِمْ حَتَّى تَأْتِيَنَا الصَّدَقَةُ فَنَأْمُرَ لَكَ بِهَا . قَالَ: ثُمَّ قَالَ: يَا قَبِيصَةُ إِنَّ المَسْأَلَةَ لا تَحِلُّ إِلا لأَحَدِ ثَلاثَةٍ: رَجُلٍ تَحَمَّلَ حَمَالَةً فَحَلَّتْ لَهُ المَسْأَلَةُ حَتَّى يُصِيبَهَا ثُمَّ يُمْسِكُ، وَرَجُلٌ أَصَابَتْهُ جَائِحَةٌ اجْتَاحَتْ مَالَهُ فَحَلَّتْ لَهُ المَسْأَلَةُ حَتَّى يُصِيبَ قِوَامًا مِنْ عَيْشٍ - أَوْ قَالَ سِدَادًا مِنْ عَيْشٍ -، وَرَجُلٌ أَصَابَتْهُ فَاقَةٌ حَتَّى يَقُومَ ثَلاثَةٌ مِنْ ذَوِي الْحِجَا مِنْ قَوْمِهِ لَقَدْ أَصَابَتْ فُلانًا فَاقَةٌ فَحَلَّتْ لَهُ المَسْأَلَةُ حَتَّى يُصِيبَ قِوَامًا مِنْ عَيْشٍ - أَوْ قَالَ سِدَادًا مِنْ عَيْشٍ - فَمَا سِوَاهُنَّ مِنْ المَسْأَلَةِ يَا قَبِيصَةُ سُحْتًا يَأْكُلُهَا صَاحِبُهَا سُحْتًا ."],"takhrij":"صحيح: رواه مسلم في الزكاة (1044) من طرق عن حماد بن زيد، عن هارون بن رياب، حدثني كنانة بن نعيم العدويّ، عن قبيصة بن مخارق الهلالي، فذكره.","grade":"صحيح","chapter_ar":"باب من تحل له الصدقة من الغارمين وغيرهم","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1044) and Ibn Khuzaymah (2360).","chapter_en":"Those for whom charity is lawful, including debtors and others","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":18,"content":{"translation":{"en":["Qabisah ibn Mukhariq al-Hilali said: I undertook a financial liability on behalf of others, so I came to the Messenger of Allah ﷺ to ask him concerning it. He said: “Stay until charity funds come to us, and then we will order that something be given to you from them.” Then he said: “O Qabisah, asking is not lawful except for one of three people: a man who has undertaken a liability, so asking becomes lawful for him until he secures it, then he must stop; a man struck by a calamity that destroys his wealth, so asking becomes lawful for him until he obtains enough to sustain his living — or he said: enough to meet his needs; and a man afflicted by poverty, until three wise people from his people say: ‘Poverty has indeed struck so-and-so,’ then asking becomes lawful for him until he obtains enough to sustain his living — or he said: enough to meet his needs. Whatever is besides these, O Qabisah, is unlawful gain, and the one who takes it consumes what is unlawful.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12043,12485],"tks":"صحيح: رواه مسلم (1044)، وابن خزيمة (2360)."},{"num":4256,"demo":false,"sanad":"","matn":["عن عائشة، قالت: وَقَعَتْ جُوَيْرِيَةُ بِنْتُ الحَارِثِ بْنِ المُصْطَلِقِ فِي سَهْمِ ثَابِتِ بْنِ قَيْسِ بْنِ شَمَّاسٍ - أَوْ ابْنِ عَمٍّ لَهُ - فَكَاتَبَتْ عَلَى نَفْسِهَا وَكَانَتْ امْرَأَةً مَلاحَةً تَأْخُذُهَا الْعَيْنُ. قَالَتْ عَائِشَةُ رَضِيَ الله عَنْهَا: فَجَاءَتْ تَسْأَلُ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فِي كِتَابَتِهَا فَلَمَّا قَامَتْ عَلَى الْبَابِ فَرَأَيْتُهَا كَرِهْتُ مَكَانَهَا وَعَرَفْتُ أَنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  سَيَرَى مِنْهَا مِثْلَ الَّذِي رَأَيْتُ فَقَالَتْ: يَا رَسُولَ الله أَنَا جُوَيْرِيَةُ بِنْتُ الحَارِثِ وَإِنَّمَا كَانَ مِنْ أَمْرِي مَا لا يَخْفَى عَلَيْكَ وَإِنِّي وَقَعْتُ فِي سَهْمِ ثَابِتِ بْنِ قَيْسِ بْنِ شَمَّاسٍ وَإِنِّي كَاتَبْتُ عَلَى نَفْسِي فَجِئْتُكَ أَسْأَلُكَ فِي كِتَابَتِي فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : فَهَلْ لَكِ إِلَى مَا هُوَ خَيْرٌ مِنْهُ؟ . قَالَتْ: وَمَا هُوَ يَا رَسُولَ الله؟ قَالَ: أُؤَدِّي عَنْكِ كِتَابَتَكِ وَأَتَزَوَّجُكِ . قَالَتْ: قَدْ فَعَلْتُ. قَالَتْ فَتَسَامَعَ تَعْنِي النَّاسَ أَنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَدْ تَزَوَّجَ جُوَيْرِيَةَ فَأَرْسَلُوا مَا فِي أَيْدِيهِمْ مِنْ السَّبْيِ فَأَعْتَقُوهُمْ وَقَالُوا أَصْهَارُ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَمَا رَأَيْنَا امْرَأَةً كَانَتْ أَعْظَمَ بَرَكَةً عَلَى قَوْمِهَا مِنْهَا أُعْتِقَ فِي سَبَبِهَا مِائَةُ أَهْلِ بَيْتٍ مِنْ بَنِي المُصْطَلِقِ.","قَالَ أَبُو دَاوُد هَذَا حُجَّةٌ فِي أَنَّ الْوَلِيَّ هُوَ يُزَوِّجُ نَفْسَهُ."],"takhrij":"حسن: رواه أبو داود (3931) عن عبدالعزيز بن يحيى أبي الأصبغ الحراني، حدّثنا محمد - يعني ابن سلمة -، عن محمد بن إسحاق، عن محمد ابن جعفر بن الزبير، عن عروة بن الزبير، عن عائشة، فذكرته.","grade":"حسن","chapter_ar":"باب من تحل له الصدقة من الغارمين وغيرهم","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (3931), Ahmad (26265), and authenticated by Ibn Hibban (4054) and al-Hakim (4/26).","chapter_en":"Those for whom charity is lawful, including debtors and others","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":18,"content":{"translation":{"en":["ʿA’ishah said: Juwayriyyah bint al-Harith ibn al-Mustaliq fell into the share of Thabit ibn Qays ibn Shammas — or a cousin of his — and she made a contract to buy her freedom. She was a very beautiful woman who would catch the eye. ʿA’ishah, may Allah be pleased with her, said: She came to ask the Messenger of Allah ﷺ about her contract, and when she stood at the door, I saw her and disliked her presence there, because I knew the Messenger of Allah ﷺ would see in her what I had seen. She said: “O Messenger of Allah ﷺ, I am Juwayriyyah bint al-Harith, and my situation is known to you. I fell into the share of Thabit ibn Qays ibn Shammas, and I made a contract to buy my freedom, so I have come to ask you concerning my contract.” The Messenger of Allah ﷺ said: “Would you like something better than that?” She said: “What is it, O Messenger of Allah ﷺ?” He said: “I will pay off your contract for you and marry you.” She said: “Yes, I accept.” She said: Then the people heard that the Messenger of Allah ﷺ had married Juwayriyyah, so they released those captives they had in their hands and said: “They are the in-laws of the Messenger of Allah ﷺ.” We did not know of any woman who brought greater blessing to her people than she did, for because of her, one hundred households from Banu al-Mustaliq were set free. Abu Dawud said: This is evidence that a guardian may marry off under his own authority in such a case."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3931)، والإمام أحمد (26265)، وصححه ابن حبان (4054)، والحاكم (4/26)."},{"num":4257,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدريّ، قال: قال رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لا تَحِلُّ الصَّدَقَةُ لِغَنِيٍّ إِلا لِخَمْسَةٍ: لِعَامِلٍ عَلَيْهَا، أَوْ لِغَازٍ فِي سَبِيلِ الله، أَوْ لِغَنِيٍّ اشْتَرَاهَا بِمَالِهِ، أَوْ فَقِيرٍ تُصُدِّقَ عَلَيْهِ فَأَهْدَاهَا لِغَنِيٍّ أَوْ غَارِمٍ ."],"takhrij":"صحيح: رواه أبو داود (1636)، وابن ماجه (1841) - واللّفظ له - كلاهما من حديث عبدالرزاق -وهو في مصنفه (7151)- قال: حدّثنا معمر، عن زيد بن أسلم، عن عطاء بن يسار، عن أبي سعيد الخدريّ، فذكره.","grade":"صحيح","chapter_ar":"باب من تحل له الصدقة من الغارمين وغيرهم","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (1636), Ibn Majah (1841) — this is his wording — and authenticated by Ibn Khuzaymah (2374).","chapter_en":"Those for whom charity is lawful, including debtors and others","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":18,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: The Messenger of Allah ﷺ said: “Charity is not lawful for a rich person except in five cases: one who is employed to collect it, one who is fighting in the cause of Allah, a rich person who bought it with his own wealth, a poor person to whom it was given and who then gifted it to a rich person, or a debtor.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12486],"tks":"صحيح: رواه أبو داود (1636)، وابن ماجه (1841) — واللفظ له — وصححه ابن خزيمة (2374)."},{"num":4258,"demo":false,"sanad":"","matn":["عن بهز بن حكيم، عن أبيه، عن جـدّه، قـال: قُلْتُ: يَا رَسُولَ الله إِنَّا قَوْمٌ نَتَسَاءَلُ أَمْوَالَنَا؟ قَالَ: يَتَسَاءَلُ الرَّجُلُ فِي الجَائِحَةِ أَوْ الْفَتْقِ لِيُصْلِحَ بِهِ بَيْنَ قَوْمِهِ فَإِذَا بَلَغَ أَوْ كَرَبَ اسْتَعَفَّ ."],"takhrij":"حسن: رواه الإمام أحمد (20033)، وعبدالرزاق (20018) ومن طريقه الطبرانيّ في الكبير 19/ (406) ومن طرق أخرى أيضاً كلّهم من حديث بهز بن حكيم، عن أبيه، عن جدّه، فذكره.","grade":"حسن","chapter_ar":"باب من تحل له الصدقة من الغارمين وغيرهم","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (20033), ʿAbd al-Razzaq (20018), and through him al-Tabarani in al-Kabir (19/406).","chapter_en":"Those for whom charity is lawful, including debtors and others","part_en":"Zakat","group_ar":"جموع أبواب الترغيب في التعفف والقناعة والترهيب من المسألة وتحريمها لغير أهلها","group_en":"Collected Chapters on Encouragement toward Self-Restraint, Contentment, Warning against Begging, and Its Prohibition for Those Who Are Not Entitled to It","part_no":14,"group_no":9,"chapter_no":18,"content":{"translation":{"en":["Bahz ibn Hakim, from his father, from his grandfather, said: I said, “O Messenger of Allah ﷺ, we are a people who ask one another for our wealth?” He said: “A man may ask in the case of a disaster or a rupture among people, so that he may bring reconciliation between his people. Then once he has reached what is needed, or has nearly reached it, he should stop and refrain.”"]},"buhuth":{"en":["The word “al-fatq” means a split, discord between groups, and the breaking apart of unity. So it is permissible for a man to ask for wealth in order to reconcile between his people regarding injuries and bloodshed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (20033)، وعبد الرزاق (20018)، ومن طريقه الطبراني في الكبير (19/ح 966)."},{"num":4259,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ مَرَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  بِتَمْرَةٍ فِي الطَّرِيقِ، قَالَ لَوْلاَ أَنِّي أَخَافُ أَنْ تَكُونَ مِنَ الصَّدَقَةِ لأَكَلْتُهَا."],"takhrij":"متفق عليه: رواه البخاريّ في اللقطة (2431)، ومسلم في الزكاة (1071: 165) كلاهما من طريق منصور، عن طلحة بن مصرّف، ثنا أنس ابن مالك، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب تحريم الصدقة على النبي ﷺ وعلى أهل بيته","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2431) and Muslim (1071 no. 165).","chapter_en":"The prohibition of charity for the Prophet ﷺ and for the people of his household","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Anas reported that the Messenger of Allah ﷺ passed by a date lying on the road and said: “If I did not fear that it might be from charity, I would have eaten it.”"]}},"tuhfa":{},"full":1,"rep":[5954],"tks":"متفق عليه: رواه البخاري (2431)، ومسلم (1071: 165)."},{"num":4260,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قال: والله إِنِّي لأَنْقَلِبُ إِلَى أَهْلِي فَأَجِدُ التَّمْرَةَ سَاقِطَةً عَلَى فِرَاشِي أَوْ فِي بَيْتِي فَأَرْفَعُهَا لآكُلَهَا ثُمَّ أَخْشَى أَنْ تَكُونَ صَدَقَةً أَوْ مِن الصَّدَقَةِ فَأُلْقِيهَا ."],"takhrij":"متفق عليه: رواه البخاريّ في اللّقطة (2432)، ومسلم في الزكاة (1070: 163) كلاهما من طريق معمر، عن همام بن منبه، عن أبي هريرة، فذكر الحديث. واللّفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب تحريم الصدقة على النبي ﷺ وعلى أهل بيته","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2432) and Muslim (1070 no. 163). This is the wording of Muslim.","chapter_en":"The prohibition of charity for the Prophet ﷺ and for the people of his household","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “By Allah, I return to my family and find a date fallen on my bed or in my house, and I pick it up to eat it. Then I fear that it may be charity, or from charity, so I throw it away.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2432)، ومسلم (1070: 163). واللفظ لمسلم."},{"num":4261,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: أَخَذَ الحَسَنُ بْنُ عَلِيٍّ تَمْرَةً مِنْ تَمْرِ الصَّدَقَةِ فَجَعَلَهَا فِي فِيهِ فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كِخْ كِخْ ارْمِ بِهَا أَمَا عَلِمْتَ أَنَّا لا نَأْكُلُ الصَّدَقَةَ ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1491)، ومسلم في الزكاة (1069) كلاهما من حديث شعبة، عن محمّد بن زياد، سمعت أبا هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم الصدقة على النبي ﷺ وعلى أهل بيته","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1491) and Muslim (1069).","chapter_en":"The prohibition of charity for the Prophet ﷺ and for the people of his household","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: Al-Hasan ibn ʿAli took a date from the dates of charity and put it in his mouth. So the Messenger of Allah ﷺ said: “Spit it out, spit it out! Throw it away. Do you not know that we do not eat charity?”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1491)، ومسلم (1069)."},{"num":4262,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: كَانَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  يُؤْتَى بِالتَّمْرِ عِنْدَ صِرَامِ النَّخْلِ فَيَجِيءُ هَذَا بِتَمْرِهِ وَهَذَا مِنْ تَمْرِهِ حَتَّى يَصِيرَ عِنْدَهُ كَوْمًا مِنْ تَمْرٍ فَجَعَلَ الحَسَنُ وَالحُسَيْنُ رَضِيَ الله عَنْهُمَا يَلْعَبَانِ بِذَلِكَ التَّمْرِ فَأَخَذَ أَحَدُهُمَا تَمْرَةً فَجَعَلَهَـا فِي فِيهِ فَنَظَرَ إِلَيْـهِ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَأَخْرَجَهَـا مِنْ فِيهِ فَقَـال: أَمَا عَلِمْتَ أَنَّ آلَ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  لَا يَأْكُلُونَ الصَّدَقَةَ ."],"takhrij":"صحيح: رواه البخاريّ في الزّكاة (1485) عن عمر بن محمد بن الحسن الأسديّ، حدّثنا أبي، حدّثنا إبراهيم بن طهمان، عن محمد بن زياد، عن أبي هريرة، فذكره. وجاءت قصّة الحسن عن أبي الحوراء، وابن أبي ليلى.","grade":"صحيح","chapter_ar":"باب تحريم الصدقة على النبي ﷺ وعلى أهل بيته","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (1485).","chapter_en":"The prohibition of charity for the Prophet ﷺ and for the people of his household","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: Dates used to be brought to the Messenger of Allah ﷺ at the time of harvesting, and this person would bring some of his dates and that person would bring some of his, until a heap of dates gathered before him. Al-Hasan and al-Husayn, may Allah be pleased with them, began playing with those dates, and one of them took a date and put it in his mouth. The Messenger of Allah ﷺ looked at him and removed it from his mouth, then said: “Do you not know that the family of Muhammad ﷺ do not eat charity?”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1485)."},{"num":4263,"demo":false,"sanad":"","matn":["عن أبي الحوراء السّعديّ، قال: قُلْتُ لِلْحَسَنِ بْنِ عَلِيٍّ: مَا تَذْكُرُ مِنْ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ؟ قَالَ: أَذْكُرُ أَنِّي أَخَذْتُ تَمْرَةً مِنْ تَمْرِ الصَّدَقَةِ فَأَلْقَيْتُهَا فِي فِيَّ فَانْتَزَعَهَا رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  بِلُعَابِهَا فَأَلْقَاهَا فِي التَّمْرِ فَقَالَ لَهُ رَجُلٌ: مَا عَلَيْكَ لَوْ أَكَلَ هَذِهِ التَّمْرَةَ قَالَ: إِنَّا لا نَأْكُلُ الصَّدَقَةَ . قَالَ: وَكَانَ يَقُولُ دَعْ مَا يَرِيبُكَ إِلَى مَا لا يَرِيبُكَ، فَإِنَّ الصِّدْقَ طُمَأْنِينَةٌ وَإِنَّ الْكَذِبَ رِيبَةٌ . قَالَ: وَكَانَ يُعَلِّمُنَا هَذَا الدُّعَاءَ: اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ، إِنَّهُ لا يَذِلُّ مَنْ وَالَيْتَ، وَرُبَّمَا قَالَ تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ ."],"takhrij":"صحيح: رواه الإمام أحمد (1723)، وأبو يعلى (6762)، والطبراني في الكبير (1710) كلهم من حديث شعبة، قال: حدثني بريد بن أبي مريم، عن أبي الحوراء السعديّ، قال (فذكره).","grade":"صحيح","chapter_ar":"باب تحريم الصدقة على النبي ﷺ وعلى أهل بيته","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (1723), Abu Yaʿla (6762), al-Tabarani in al-Kabir (1710), and authenticated by Ibn Khuzaymah (2347).","chapter_en":"The prohibition of charity for the Prophet ﷺ and for the people of his household","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Abu al-Hawra’ al-Saʿdi said: I said to al-Hasan ibn ʿAli, “What do you remember from the Messenger of Allah ﷺ?” He said: I remember that I took a date from the dates of charity and put it in my mouth, and the Messenger of Allah ﷺ removed it from my mouth, with my saliva still on it, and put it back among the dates. A man said to him, “What harm would there have been if he had eaten this one date?” He replied: “We do not eat charity.” He also said: “And he used to say: Leave what makes you doubtful for what does not make you doubtful, for truth brings reassurance and falsehood brings doubt.” And he said: “He used to teach us this supplication: O Allah, guide me among those You have guided, grant me well-being among those You have granted well-being, take me into Your care among those You have taken into Your care, bless for me what You have given, and protect me from the evil of what You have decreed. Indeed, the one whom You befriend is never humiliated.” And sometimes he would say: “Blessed are You, our Lord, and Exalted are You.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (1723)، وأبو يعلى (6762)، والطبراني في الكبير (1710)، وصححه ابن خزيمة (2347)."},{"num":4264,"demo":false,"sanad":"","matn":["عَنْ رَبِيعَةَ بْنِ شَيْبَانَ، قَالَ: قُلْتُ لِلحُسَيْنِ بْنِ عَلِيٍّ: رَضِيَ اللَّهُ عَنْهُ: مَا تَعْقِلُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: صَعِدْتُ غُرْفَةً، فَأَخَذْتُ تَمْرَةً، فَلُكْتُهَا فِي فِيَّ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلْقِهَا، فَإِنَّهَا لَا تَحِلُّ لَنَا الصَّدَقَةُ."],"takhrij":"حسن: رواه أحمد (1724، 1731) وابن خزيمة (2349) والطحاوي في شرح المعاني (2/7) كلهم من حديث ثابت بن عمارة، عن ربيعة بن شيبان، قال: فذكره.","grade":"حسن","chapter_ar":"باب تحريم الصدقة على النبي ﷺ وعلى أهل بيته","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (1724, 1731), Ibn Khuzaymah (2349), and al-Tahawi in Sharh al-Maʿani (2/7).","chapter_en":"The prohibition of charity for the Prophet ﷺ and for the people of his household","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Rabiʿah ibn Shayban said: I said to al-Husayn ibn ʿAli, “What do you remember clearly from the Messenger of Allah ﷺ?” He said: I climbed up into an upper room, took a date, and chewed it in my mouth. Then the Prophet ﷺ said: “Throw it away, for charity is not lawful for us.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (1724، 1731)، وابن خزيمة (2349)، والطحاوي في شرح المعاني (2/7)."},{"num":4265,"demo":false,"sanad":"","matn":["عَنْ أَبِي لَيْلَى، قَالَ: كُنْتُ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعِنْدَهُ الْحَسَنُ بْنُ عَلِيٍّ، فَأَخَذَ تَمْرَةً مِنْ تَمْرِ الصَّدَقَةِ فَانْتَزَعَهَا مِنْهُ، وَقَالَ: أَمَا عَلِمْتَ أَنَّهُلَا تَحِلُّ لَنَا الصَّدَقَةُ."],"takhrij":"صحيح: رواه الإمام أحمد (19057)، والطبرانيّ (7/90)، والدّارميّ (1643) كلّهم من حديث زهير، عن عبدالله بن عيسى، عن عيسى، عن عبدالرحمن بن أبي ليلى، عن أبي ليلى، فذكره، واللّفظ للدّارميّ، ولفظهما أطول من هذا. وإسناده صحيح، وعبدالرحمن بن أبي ليلى الكوفي ثقة.","grade":"صحيح","chapter_ar":"باب تحريم الصدقة على النبي ﷺ وعلى أهل بيته","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (19057), al-Tabarani (7/90), and al-Darimi (1643). This is the wording of al-Darimi.","chapter_en":"The prohibition of charity for the Prophet ﷺ and for the people of his household","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Abu Layla said: I was with the Prophet ﷺ, and al-Hasan ibn ʿAli was with him. He took a date from the dates that had been brought, and the Prophet ﷺ pulled it away from him and said: “Do you not know that charity is not lawful for us?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (19057)، والطبراني (7/90)، والدارمي (1643)، واللفظ للدارمي."},{"num":4266,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده، أَنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  كَانَ نَائِمًا فَوَجَدَ تَمْرَةً تَحْتَ جَنْبِهِ فَأَخَذَهَا فَأَكَلَهَا، ثُمَّ جَعَلَ يَتَضَوَّرُ مِنْ آخِرِ اللَّيْلِ وَفَزِعَ لِذَلِكَ بَعْضُ أَزْوَاجِهِ فَقَالَ: إِنِّي وَجَدْتُ تَمْرَةً تَحْتَ جَنْبِي فَأَكَلْتُهَا فَخَشِيتُ أَنْ تَكُونَ مِنْ تَمْرِ الصَّدَقَةِ ."],"takhrij":"حسن: رواه الإمام أحمد (6720) عن أبي بكر الحنفيّ، حدّثنا أسامة بن زيد، عن عمرو بن شعيب، عن أبيه، عن جده، فذكره.","grade":"حسن","chapter_ar":"باب تحريم الصدقة على النبي ﷺ وعلى أهل بيته","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (6720).","chapter_en":"The prohibition of charity for the Prophet ﷺ and for the people of his household","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb, from his father, from his grandfather, reported that the Messenger of Allah ﷺ was sleeping and found a date beneath his side. He picked it up and ate it. Then later in the night he became distressed and restless, and some of his wives were alarmed by that. So he said: “I found a date beneath my side and ate it, then I feared that it might have been from the dates of charity.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (6720)."},{"num":4267,"demo":false,"sanad":"","matn":["عن يزيد بن حيان انْطَلَقْتُ أَنَا وَحُصَيْنُ بْنُ سَبْرَةَ وَعُمَرُ بْنُ مُسْلِمٍ إِلَى زَيْدِ بْنِ أَرْقَمَ فَلَمَّا جَلَسْنَا إِلَيْهِ قَالَ لَهُ حُصَيْنٌ لَقَدْ لَقِيتَ يَا زَيْدُ خَيْرًا كَثِيرًا، رَأَيْتَ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  وَسَمِعْتَ حَدِيثَهُ وَغَزَوْتَ مَعَهُ وَصَلَّيْتَ خَلْفَهُ لَقَدْ لَقِيتَ يَا زَيْدُ خَيْرًا كَثِيرًا، حَدِّثْنَــا يَا زَيْدُ مَا سَمِعْتَ مِنْ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَال: يَا ابْنَ أَخِي والله لَقَدْ كَبِرَتْ سِنِّي وَقَدُمَ عَهْدِي وَنَسِيتُ بَعْضَ الَّذِي كُنْتُ أَعِي مِنْ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَمَا حَدَّثْتُكُمْ فَاقْبَلُوا وَمَا لا فَلا تُكَلِّفُونِيهِ ثُمَّ قَالَ: قَامَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  يَوْمًا فِينَا خَطِيبًا بِمَاءٍ يُدْعَى خُمًّا بَيْنَ مَكَّةَ وَالمَدِينَةِ فَحَمِدَ الله وَأَثْنَى عَلَيْهِ وَوَعَظَ وَذَكَّرَ ثُمَّ قَالَ: أَمَّا بَعْدُ أَلا أَيُّهَا النَّاسُ فَإِنَّمَا أَنَا بَشَرٌ يُوشِكُ أَنْ يَأْتِيَ رَسُولُ رَبِّي فَأُجِيبَ وَأَنَا تَارِكٌ فِيكُمْ ثَقَلَيْنِ أَوَّلُهُمَا كِتَابُ الله، فِيهِ الهُدَى وَالنُّورُ فَخُذُوا بِكِتَابِ الله وَاسْتَمْسِكُوا بِهِ . فَحَثَّ عَلَى كِتَابِ الله وَرَغَّبَ فِيهِ ثُمَّ قَالَ: وَأَهْلُ بَيْتِي، أُذَكِّرُكُمْ الله فِي أَهْلِ بَيْتِي، أُذَكِّرُكُمْ الله فِي أَهْلِ بَيْتِي، أُذَكِّرُكُمْ الله فِي أَهْلِ بَيْتِي . فَقَالَ لَهُ حُصَيْنٌ: وَمَنْ أَهْلُ بَيْتِهِ يَا زَيْدُ؟ أَلَيْسَ نِسَاؤُهُ مِنْ أَهْلِ بَيْتِهِ؟ قَالَ: نِسَاؤُهُ مِنْ أَهْلِ بَيْتِهِ، وَلَكِنْ أَهْلُ بَيْتِهِ مَنْ حُرِمَ الصَّدَقَةَ بَعْدَهُ. قَالَ: وَمَنْ هُم؟ قَالَ: هُمْ آلُ عَلِيٍّ، وَآلُ عَقِيلٍ، وَآلُ جَعْفَرٍ، وَآلُ عَبَّاسٍ. قَالَ: كُلُّ هَؤُلاءِ حُرِمَ الصَّدَقَةَ؟ قَالَ: نَعَمْ."],"takhrij":"صحيح: رواه مسلم في فضائل الصّحابة (2408) من طرق عن إسماعيل ابن إبراهيم المعروف بابن علية، حدثني أبو حيان، حدّثني يزيد بن حيان فذكره.","grade":"صحيح","chapter_ar":"باب أن آل النبي الذين حُرِّمت عليهم الصدقة هم: آل علي، وآل عقيل، وآل جعفر، وآل العباس","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (2408).","chapter_en":"The family of the Prophet for whom charity was forbidden are the families of ʿAli, ʿAqil, Jaʿfar, and al-ʿAbbas","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":2,"content":{"translation":{"en":["Yazid ibn Hayyan said: I, Husayn ibn Sabrah, and ʿUmar ibn Muslim went to Zayd ibn Arqam. When we sat with him, Husayn said to him: “You have received a great deal of good, O Zayd. You saw the Messenger of Allah ﷺ, heard his speech, fought alongside him, and prayed behind him. You have truly received much good, O Zayd. Tell us what you heard from the Messenger of Allah ﷺ.” He said: “My nephew, by Allah, I have grown old, much time has passed, and I have forgotten some of what I used to retain from the Messenger of Allah ﷺ. So whatever I narrate to you, accept it, and what I do not, do not press me about it.” Then he said: The Messenger of Allah ﷺ once stood among us to deliver a sermon at a watering place called Khumm, between Makkah and Madinah. He praised Allah, glorified Him, gave an admonition, and then said: “Now then, O people, I am only a human being. Soon the messenger of my Lord will come to me and I will answer. I am leaving among you two weighty things. The first of them is the Book of Allah, in which there is guidance and light, so hold firmly to the Book of Allah and cling to it.” Then he strongly urged adherence to the Book of Allah and encouraged it. Then he said: “And my household — I remind you by Allah concerning my household, I remind you by Allah concerning my household, I remind you by Allah concerning my household.” Husayn said to him: “Who are the people of his household, O Zayd? Are not his wives among the people of his household?” He said: “His wives are among the people of his household, but the people of his household in this sense are those for whom charity was forbidden after him.” He said: “And who are they?” He said: “They are the family of ʿAli, the family of ʿAqil, the family of Jaʿfar, and the family of al-ʿAbbas.” He said: “Were all of these forbidden from charity?” He said: “Yes.”"]},"buhuth":{"en":["It was also narrated through another route, and in it there is the wording:","“Indeed, I am leaving among you two weighty things. One of them is the Book of Allah, the Mighty and Majestic. It is the rope of Allah. Whoever follows it is upon guidance, and whoever leaves it is upon misguidance.”","And in it we said: “Who are the people of his household? His wives?”","He said: “No. By Allah, a woman may stay with a man for a long period of time, then he divorces her and she returns to her father and her people. The people of his household are his line of origin and his male relatives through his clan, those for whom charity was forbidden after him.”","His statement “the family of ʿAli, the family of ʿAqil, the family of Jaʿfar, and the family of al-ʿAbbas” means the descendants of ʿAbd al-Muttalib ibn Hashim ibn ʿAbd Manaf.","The name of ʿAbd al-Muttalib was Shaybah. He was called ʿAbd al-Muttalib because of his close attachment to his uncle al-Muttalib. So the lineage of the Prophet ﷺ is: Muhammad ibn ʿAbdullah ibn Shaybah ibn Hashim ibn ʿAbd Manaf."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2408)."},{"num":4268,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: بَعَثَنِي أَبِي إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي إِبِلٍ أَعْطَاهَا إِيَّاهُ مِنَ الصَّدَقَةِ."],"takhrij":"صحيح: رواه أبو داود (1653، 1654) بإسنادين: أحدهما عن محمد ابن عبيد المحاربيّ، حدّثنا محمد بن فضيل، عن الأعمش، عن حبيب بن أبي ثابت، عن كريب مولى ابن عباس، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب أن آل النبي الذين حُرِّمت عليهم الصدقة هم: آل علي، وآل عقيل، وآل جعفر، وآل العباس","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (1653, 1654).","chapter_en":"The family of the Prophet for whom charity was forbidden are the families of ʿAli, ʿAqil, Jaʿfar, and al-ʿAbbas","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbas said: My father sent me to the Prophet ﷺ regarding some camels that he had given him from the charity camels."]},"buhuth":{"en":["Al-Bayhaqi said:","“This report can only bear one of two meanings: either it occurred before charity was made forbidden for the descendants of Hashim, and then it was later abrogated; or the Prophet ﷺ had borrowed camels from al-ʿAbbas on behalf of the needy and then returned them to him.”","Quoted in Badhl al-Majhud (8/197)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1653، 1654)."},{"num":4269,"demo":false,"sanad":"","matn":["عن عبد المطلب بن ربيعة بن الحارث حدَّثه، قال: اجْتَمَعَ رَبِيعَةُ بْنُ الحَارِثِ وَالْعَبَّاسُ بْنُ عَبْدِ المُطَّلِبِ فَقَالا: والله لَوْ بَعَثْنَا هَذَيْنِ الْغُلامَيْنِ قَالا لِي وَلِلْفَضْلِ بْنِ عَبَّاسٍ إِلَى رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَكَلَّمَاهُ فَأَمَّرَهُمَا عَلَى هَذِهِ الصَّدَقَاتِ فَأَدَّيَا مَا يُؤَدِّي النَّاسُ وَأَصَابَا مِمَّا يُصِيبُ النَّاسُ، قَالَ: فَبَيْنَمَا هُمَا فِي ذَلِكَ جَاءَ عَلِيُّ بْنُ أَبِي طَالِبٍ فَوَقَفَ عَلَيْهِمَا فَذَكَرَا لَهُ ذَلِكَ، فَقَالَ عَلِيُّ بْنُ أَبِي طَالِبٍ: لا تَفْعَلا فوالله مَا هُوَ بِفَاعِلٍ، فَانْتَحَاهُ رَبِيعَةُ بْنُ الحَارِثِ، فَقَالَ: والله مَا تَصْنَعُ هَذَا إِلا نَفَاسَةً مِنْكَ عَلَيْنَا! فَوَالله لَقَدْ نِلْتَ صِهْرَ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَمَا نَفِسْنَاهُ عَلَيْكَ! قَالَ عَلِيٌّ: أَرْسِلُوهُمَا فَانْطَلَقَا، وَاضْطَجَعَ عَلِيٌّ قَالَ: فَلَمَّا صَلَّى رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  الظُّهْرَ سَبَقْنَاهُ إِلَى الحُجْرَةِ فَقُمْنَا عِنْدَهَا حَتَّى جَاءَ فَأَخَذَ بِآذَانِنَا، ثُمَّ قَالَ: أَخْرِجَا مَا تُصَرِّرَانِ . ثُمَّ دَخَلَ وَدَخَلْنَا عَلَيْهِ، وَهُوَ يَوْمَئِذٍ عِنْدَ زَيْنَبَ بِنْتِ جَحْشٍ. قَالَ: فَتَوَاكَلْنَا الْكَلامَ ثُمَّ تَكَلَّمَ أَحَدُنَا، فَقَالَ: يَا رَسُولَ الله أَنْتَ أَبَرُّ النَّاسِ وَأَوْصَلُ النَّاسِ، وَقَدْ بَلَغْنَا النِّكَاحَ فَجِئْنَا لِتُؤَمِّرَنَا عَلَى بَعْضِ هَذِهِ الصَّدَقَاتِ فَنُؤَدِّيَ إِلَيْكَ كَمَا يُؤَدِّي النَّاسُ وَنُصِيبَ كَمَا يُصِيبُونَ قَالَ: فَسَكَتَ طَوِيلا حَتَّى أَرَدْنَا أَنْ نُكَلِّمَهُ. قَالَ: وَجَعَلَتْ زَيْنَبُ تُلْمِعُ عَلَيْنَا مِنْ وَرَاءِ الْحِجَابِ أَنْ لا تُكَلِّمَاهُ. قَالَ: ثُمَّ قَالَ: إِنَّ الصَّدَقَةَ لا تَنْبَغِي لآلِ مُحَمَّدٍ؛ إِنَّمَا هِيَ أَوْسَاخُ النَّاسِ ادْعُوَا لِي مَحْمِيَةَ - وَكَانَ عَلَى الخُمُسِ - وَنَوْفَلَ بْنَ الحَارِثِ بْنِ عَبْدِ المُطَّلِبِ . قَالَ: فَجَاءَاهُ، فَقَالَ لِمَحْمِيَةَ: أَنْكِحْ هَذَا الْغُلامَ ابْنَتَكَ . لِلْفَضْلِ بْنِ عَبَّاسٍ فَأَنْكَحَهُ، وَقَالَ لِنَوْفَلِ بْنِ الحَارِثِ: أَنْكِحْ هَذَا الْغُلامَ ابْنَتَكَ . لِي فَأَنْكَحَنِي، وَقَالَ لِمَحْمِيَةَ: أَصْدِقْ عَنْهُمَا مِنْ الخُمُسِ كَذَا وَكَذَا .","قَالَ الزُّهْرِيُّ: وَلَمْ يُسَمِّهِ لِي."],"takhrij":"صحيح: رواه مسلم في الزكاة (1072) عن عبدالله بن محمد بن أسماء الضُّبعيّ، حدثنا جويرية، عن مالك، عن الزهريّ، أن عبدالله بن عبدالله بن نوفل بن الحارث بن عبد المطلب حدّثه، أن عبد المطلب بن ربيعة بن الحارث حدّثه، فذكره.","grade":"صحيح","chapter_ar":"باب ترك استعمال آل النبي ﷺ على الصدقة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1072).","chapter_en":"Refraining from appointing the family of the Prophet ﷺ over charity collection","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":3,"content":{"translation":{"en":["ʿAbd al-Muttalib ibn Rabiʿah ibn al-Harith reported: Rabiʿah ibn al-Harith and al-ʿAbbas ibn ʿAbd al-Muttalib gathered and said: “By Allah, if only we sent these two boys” — meaning me and al-Fadl ibn al-ʿAbbas — “to the Messenger of Allah ﷺ so they could speak to him and he might appoint them over these charity collections. Then they would carry out what people carry out, and they would receive something just as people receive.” He said: While they were discussing this, ʿAli ibn Abi Talib came and stood by them. They mentioned that to him, and ʿAli ibn Abi Talib said: “Do not do it, for by Allah, he will not do that.” Then Rabiʿah ibn al-Harith turned directly to him and said: “By Allah, you are only saying this out of jealousy toward us. By Allah, you attained the honor of being related by marriage to the Messenger of Allah ﷺ, and we did not envy you for that.” ʿAli said: “Send them.” So they went, and ʿAli lay down. When the Messenger of Allah ﷺ had prayed Zuhr, we went ahead of him to the room and stood at its door until he came. He took hold of our ears and said: “Bring out what you have been hiding in your hearts.” Then he entered and we entered upon him, and on that day he was with Zaynab bint Jahsh. We each hesitated for the other to speak, then one of us spoke and said: “O Messenger of Allah ﷺ, you are the most righteous of people and the most dutiful in keeping ties. We have now reached the age of marriage, and we came so that you might appoint us over some of these charity collections. Then we would deliver to you just as people deliver, and we would receive something as they receive.” He remained silent for a long time, until we thought of speaking again. Meanwhile, Zaynab was signaling to us from behind the curtain not to speak to him. Then he said: “Charity is not suitable for the family of Muhammad. It is only the impurities of the people. Call for Mahmiyyah” — and he was in charge of the khums — “and Nawfal ibn al-Harith ibn ʿAbd al-Muttalib.” So they came, and he said to Mahmiyyah: “Marry this young man to your daughter,” meaning al-Fadl ibn al-ʿAbbas, and he married him to her. And he said to Nawfal ibn al-Harith: “Marry this young man to your daughter,” meaning me, and he married me to her. Then he said to Mahmiyyah: “Give the bridal gift for both of them from the khums, such-and-such.”"]},"buhuth":{"en":["His statement “Rabiʿah turned directly to him” means he addressed him directly.","His statement “Bring out what you have been hiding” means: bring out what you have been keeping inside your chests of speech.","And “she was signaling” means she was gesturing with her garment or with her hand."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1072)."},{"num":4270,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: كَانَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  إِذَا أُتِيَ بِطَعَامٍ سَأَلَ عَنْهُ أَهَدِيَّةٌ أَمْ صَدَقَةٌ فَإِنْ قِيلَ صَدَقَةٌ قَال لأَصْحَابِهِ: كُلُوا . وَلَمْ يَأْكُلْ وَإِنْ قِيلَ هَدِيَّةٌ ضَرَبَ بِيَدِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَأَكَلَ مَعَهُمْ."],"takhrij":"متفق عليه: رواه البخاريّ في الهبة (2576) عن إبراهيم بن المنذر، حدّثنا معن، حدّثني إبراهيم بن طهمان، عن محمد بن زياد، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب قبول النبي ﷺ الهدية، ورد الصدقة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2576) and Muslim (1077).","chapter_en":"The Prophet ﷺ accepting gifts and declining charity","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: Whenever food was brought to the Messenger of Allah ﷺ, he would ask about it: “Is it a gift or is it charity?” If it was said, “It is charity,” he would say to his companions: “Eat.” But he himself would not eat. And if it was said, “It is a gift,” he would put his hand forward and eat with them."]},"buhuth":{"en":["His statement “when food was brought to him” means food brought from outside his household, and he would ask about it, as stated in the narration of Ahmad (8014)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2576)، ومسلم (1077)."},{"num":4271,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: قال رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لَوْ دُعِيتُ إِلَى كُرَاعٍ لأَجَبْتُ وَلَوْ أُهْدِيَ إِلَيَّ كُرَاعٌ لَقَبِلْتُ ."],"takhrij":"صحيح: رواه البخاريّ في النكاح (5178) عن عبدان، عن أبي حمزة، عن الأعمش، عن أبي حازم، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب قبول النبي ﷺ الهدية، ورد الصدقة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (5178).","chapter_en":"The Prophet ﷺ accepting gifts and declining charity","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “If I were invited to a meal of a trotter, I would respond, and if a trotter were given to me as a gift, I would accept it.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (5178)."},{"num":4272,"demo":false,"sanad":"","matn":["عن عائشة زوج النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، قـالت: كَانَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  يَقْبَلُ الهَدِيَّةَ وَيُثِيبُ عَلَيْهَا."],"takhrij":"صحيح: رواه البخاريّ في الهبة (2585) عن مسدّد، حدّثنا عيسى بن يونس، عن هشام، عن أبيه، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب قبول النبي ﷺ الهدية، ورد الصدقة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (2585).","chapter_en":"The Prophet ﷺ accepting gifts and declining charity","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":4,"content":{"translation":{"en":["ʿA’ishah, the wife of the Prophet ﷺ, said: The Messenger of Allah ﷺ used to accept gifts and give something in return for them."]}},"tuhfa":{},"full":1,"rep":[5980],"tks":"صحيح: رواه البخاري (2585)."},{"num":4273,"demo":false,"sanad":"","matn":["عن بهز بن حكيم، عن أبيه، عن جـده، قـال: كَانَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  إِذَا أُتِيَ بِشَيْءٍ سَأَلَ أَصَدَقَةٌ هِيَ أَمْ هَدِيَّةٌ ؟ فَإِنْ قَالُوا: صَدَقَةٌ لَمْ يَأْكُلْ، وَإِنْ قَالُوا: هَدِيَّةٌ أَكَلَ."],"takhrij":"حسن: رواه الترمذيّ (656)، والنسائيّ (2614) كلاهما من حديث بهز بن حكيم، عن أبيه، عن جدّه، فذكره.","grade":"حسن","chapter_ar":"باب قبول النبي ﷺ الهدية، ورد الصدقة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by al-Tirmidhi (656) and al-Nasa’i (2614). Al-Tirmidhi said: Hasan gharib.","chapter_en":"The Prophet ﷺ accepting gifts and declining charity","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":4,"content":{"translation":{"en":["Bahz ibn Hakim, from his father, from his grandfather, reported: Whenever something was brought to the Messenger of Allah ﷺ, he would ask: “Is it charity, or is it a gift?” If they said, “Charity,” he would not eat. If they said, “A gift,” he would eat."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (656)، والنسائي (2614). قال الترمذي: حسن غريب."},{"num":4274,"demo":false,"sanad":"","matn":["عن سلمان الفارسيّ، قال: كُنْتُ مِنْ أَبْنَاءِ أَسَاوِرَةِ فَارِسَ -فَذَكَرَ الحَدِيثَ- قَالَ: فَانْطَلَقْتُ تَرْفَعُنِي أَرْضٌ وَتَخْفِضُنِي أُخْرَى حَتَّى مَرَرْتُ عَلَى قَوْمٍ مِنْ الأَعْرَابِ فَاسْتَعْبَدُونِي فَبَاعُونِي حَتَّى اشْتَرَتْنِي امْرَأَةٌ فَسَمِعْتُهُمْ يَذْكُرُونَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  وَكَانَ الْعَيْشُ عَزِيزًا فَقُلْتُ لَهَا: هَبِي لِي يَوْمًا فَقَالَتْ: نَعَمْ، فَانْطَلَقْتُ فَاحْتَطَبْتُ حَطَبًا فَبِعْتُهُ فَصَنَعْتُ طَعَامًا فَأَتَيْتُ بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَوَضَعْتُهُ بَيْنَ يَدَيْهِ فَقَالَ: مَا هَذَا؟ . فَقُلْتُ: صَدَقَةٌ. فَقَالَ لأَصْحَابِهِ: كُلُوا . وَلَمْ يَأْكُلْ قُلْتُ: هَذِهِ مِنْ عَلامَاتِهِ، ثُمَّ مَكَثْتُ مَا شَاءَ الله أَنْ أَمْكُثَ فَقُلْتُ: لِمَوْلاتِي هَبِي لِي يَوْمًا. قَالَتْ: نَعَمْ، فَانْطَلَقْتُ فَاحْتَطَبْتُ حَطَبًا بِأَكْثَرَ مِنْ ذَلِكَ فَصَنَعْتُ طَعَامًا فَأَتَيْتُهُ بِهِ، وَهُوَ جَالِسٌ بَيْنَ أَصْحَابِهِ فَوَضَعْتُهُ بَيْنَ يَدَيْهِ فَقَالَ: مَا هَذَا؟ . قُلْتُ: هَدِيَّةٌ فَوَضَعَ يَدَهُ وَقَالَ لأَصْحَابِهِ: خُذُوا بِسْمِ الله . وَقُمْتُ خَلْفَهُ فَوَضَعَ رِدَاءَهُ فَإِذَا خَاتَمُ النُّبُوَّةِ، فَقُلْتُ: أَشْهَدُ أَنَّكَ رَسُولُ الله. فَقَالَ: وَمَا ذَاكَ؟ . فَحَدَّثْتُهُ عَنْ الرَّجُلِ وَقُلْتُ: أَيَدْخُلُ الجَنَّةَ يَا رَسُولَ الله فَإِنَّهُ حَدَّثَنِي أَنَّكَ نَبِيٌّ؟ فَقَالَ: لَنْ يَدْخُلَ الجَنَّةَ إِلا نَفْسٌ مُسْلِمَةٌ . فَقُلْتُ: يَا رَسُولَ الله إِنَّهُ أَخْبَرَنِي أَنَّكَ نَبِيٌّ أَيَدْخُلُ الجَنَّةَ؟ قَالَ: لَنْ يَدْخُلَ الجَنَّةَ إِلا نَفْسٌ مُسْلِمَةٌ ."],"takhrij":"حسن: رواه الإمام أحمد (23712)، والطبراني في الكبير (6/259) كلاهما من حديث إسرائيل، حدّثنا أبو إسحاق، عن أبي قرة الكنديّ، عن سلمان الفارسيّ، فذكره. وصحّحه ابن حبان (7124).","grade":"حسن","chapter_ar":"باب قبول النبي ﷺ الهدية، ورد الصدقة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (23712), al-Tabarani in al-Kabir (6/259), and authenticated by Ibn Hibban (7124).","chapter_en":"The Prophet ﷺ accepting gifts and declining charity","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":4,"content":{"translation":{"en":["Salman al-Farisi said: I was one of the sons of the cavalry nobility of Persia — then he mentioned the long story — and said: So I set out, one land raising me and another lowering me, until I passed by some Bedouin people, and they enslaved me. Then they sold me until a woman bought me. I heard them mentioning the Prophet ﷺ, and living conditions were difficult, so I said to her: “Grant me one day.” She said: “Yes.” So I went and gathered firewood, sold it, prepared some food, and brought it to the Prophet ﷺ and placed it before him. He said: “What is this?” I said: “Charity.” So he said to his companions: “Eat.” And he did not eat. I said: This is one of his signs. Then I stayed as long as Allah willed. Then I said to my mistress: “Give me one day.” She said: “Yes.” So I went and gathered firewood, sold it for more than before, prepared food, and brought it to him while he was sitting among his companions. I placed it before him, and he said: “What is this?” I said: “A gift.” So he put out his hand and said to his companions: “Take it, in the name of Allah.” Then I stood behind him, and he moved his cloak, and there was the seal of prophethood. So I said: I bear witness that you are the Messenger of Allah ﷺ. He said: “What made you say that?” So I told him about the monk, and I said: “Will he enter Paradise, O Messenger of Allah ﷺ? He told me that you would be a prophet.” He said: “No soul will enter Paradise except a Muslim soul.” So I said: “O Messenger of Allah ﷺ, he told me that you would be a prophet. Will he enter Paradise?” He said: “No soul will enter Paradise except a Muslim soul.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (23712)، والطبراني في الكبير (6/259)، وصححه ابن حبان (7124)."},{"num":4275,"demo":false,"sanad":"","matn":["عن أمِّ عطيّة، قالت: بَعَثَ إِلَيَّ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  بِشَاةٍ مِن الصَّدَقَةِ فَبَعَثْتُ إِلَى عَائِشَةَ مِنْهَا بِشَيْءٍ، فَلَمَّا جَاءَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  إِلَى عَائِشَةَ قَالَ: هَلْ عِنْدَكُمْ شَيْءٌ؟ . قَالَتْ: لا إِلا أَنَّ نُسَيْبَةَ بَعَثَتْ إِلَيْنَا مِنْ الشَّاةِ الَّتِي بَعَثْتُمْ بِهَا إِلَيْهَا، قَالَ: إِنَّهَا قَدْ بَلَغَتْ مَحِلَّهَا ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1446)، ومسلم في الزكاة (1076) كلاهما من طريق خالد، عن حفصة بنت سيرين، عن أمّ عطية، فذكرته. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب إذا تحولت الصدقة هدية جازت للنبي ﷺ ولآله","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1446) and Muslim (1076). This is the wording of Muslim.","chapter_en":"If charity becomes a gift, it becomes lawful for the Prophet ﷺ and his family","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Umm ʿAtiyyah said: The Messenger of Allah ﷺ sent me a sheep from the charity animals, and I sent some of it to ʿA’ishah. When the Messenger of Allah ﷺ came to ʿA’ishah, he said: “Do you have anything?” She said: “No, except that Nusaybah sent us some from the sheep that you had sent to her.” He said: “It has reached its lawful destination.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1446)، ومسلم (1076). واللفظ لمسلم."},{"num":4276,"demo":false,"sanad":"","matn":["عن عائشة، قالت: كَانَ فِي بَرِيرَةَ ثَلاثُ سُنَنٍ، فَكَانَتْ إِحْدَى السُّنَنِ الثَّلاثِ: أَنَّهَا أُعْتِقَتْ فَخُيِّرَتْ فِي زَوْجِهَا، وَقَــالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : الْوَلاءُ لِمَنْ أَعْتَقَ . وَدَخَلَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  وَالْبُرْمَةُ تَفُـورُ بِلَحْـمٍ فَقُرِّبَ إِلَيْـهِ خُبْزٌ وَأُدْمٌ مِنْ أُدْمِ الْبَيْتِ فَقَـالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَلَمْ أَرَ بُرْمَةً فِيهَـا لحْمٌ؟ . فَقَـالُوا: بَلَى يَا رَسُولَ الله وَلَكِنْ ذَلِكَ لحْمٌ تُصُدِّقَ بِهِ عَلَى بَرِيرَةَ وَأَنْتَ لا تَأْكُلُ الصَّدَقَةَ، فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : هُوَ عَلَيْهَا صَدَقَةٌ وَهُوَ لَنَا هَدِيَّةٌ ."],"takhrij":"متفق عليه: رواه مالك في الطّلاق (29) عن ربيعة بن أبي عبدالرحمن، عن القاسم بن محمد، عن عائشة أمّ المؤمنين أنها قالت (فذكرته).","grade":"متفق عليه","chapter_ar":"باب إذا تحولت الصدقة هدية جازت للنبي ﷺ ولآله","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (29), al-Bukhari (5279), and Muslim (1075 no. 173).","chapter_en":"If charity becomes a gift, it becomes lawful for the Prophet ﷺ and his family","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["ʿA’ishah said: There were three established rulings connected to Barirah. One of those three was that she was freed and then was given the choice regarding her husband. And the Messenger of Allah ﷺ said: “Loyalty of emancipation belongs to the one who frees.” Then the Messenger of Allah ﷺ entered while the cooking pot was boiling with meat, but bread and some household side dish were brought near him. So the Messenger of Allah ﷺ said: “Did I not see the pot containing meat?” They said: “Yes, O Messenger of Allah ﷺ, but that is meat that was given in charity to Barirah, and you do not eat charity.” So the Messenger of Allah ﷺ said: “For her it is charity, and for us it is a gift.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (29)، والبخاري (5279)، ومسلم (1075/173)."},{"num":4277,"demo":false,"sanad":"","matn":["عن عائشة، أَنَّهَا أَرَادَتْ أَنْ تَشْتَرِيَ بَرِيرَةَ لِلْعِتْقِ وَأَرَادَ مَوَالِيهَا أَنْ يَشْتَرِطُوا وَلاءَهَا فَذَكَرَتْ عَائِشَةُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَقَالَ لَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : اشْتَرِيهَا فَإِنَّمَا الْوَلاءُ لِمَنْ أَعْتَقَ . قَالَتْ: وَأُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  بِلَحْمٍ فَقُلْتُ: هَذَا مَا تُصُدِّقَ بِهِ عَلَى بَرِيرَةَ فَقَالَ: هُوَ لَهَا صَدَقَةٌ وَلَنَا هَدِيَّةٌ ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1493)، ومسلم في الزكاة (1075) كلاهما من طريق شعبة، عن الحكم، عن إبراهيم، عن الأسود، عن عائشة، فذكرته. واللفظ للبخاريّ، ولفظ مسلم مختصر، وفيه تعيين اللّحم بأنه لحم بقر.","grade":"متفق عليه","chapter_ar":"باب إذا تحولت الصدقة هدية جازت للنبي ﷺ ولآله","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1493) and Muslim in the Book of Zakah (1075). This is the wording of al-Bukhari.","chapter_en":"If charity becomes a gift, it becomes lawful for the Prophet ﷺ and his family","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["ʿA’ishah reported that she wanted to buy Barirah in order to free her, but her owners wanted to stipulate that the right of loyalty would remain with them. ʿA’ishah mentioned this to the Prophet ﷺ, and the Prophet ﷺ said to her: “Buy her, for loyalty belongs only to the one who frees.” She said: Meat was then brought to the Prophet ﷺ, and I said: “This is from what was given in charity to Barirah.” So he said: “For her it is charity, and for us it is a gift.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1493)، ومسلم (1075). واللفظ للبخاري."},{"num":4278,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: أهدتْ بريرةُ إلى النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  لحماً تُصُدِّقَ بِهِ عَلَى بَرِيرَةَ فَقَالَ: هُوَ لَهَا صَدَقَةٌ وَلَنَا هَدِيَّةٌ ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1495)، ومسلم في الزكاة (1074) كلاهما من طريق شعبة، عن قتادة، عن أنس، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب إذا تحولت الصدقة هدية جازت للنبي ﷺ ولآله","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari in the Book of Zakah (1495) and Muslim in the Book of Zakah (1074).","chapter_en":"If charity becomes a gift, it becomes lawful for the Prophet ﷺ and his family","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Anas said: Barirah gave the Prophet ﷺ some meat as a gift — meat that had been given in charity to Barirah — and he said: “For her it is charity, and for us it is a gift.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1495)، ومسلم (1074)."},{"num":4279,"demo":false,"sanad":"","matn":["عن جويرية زوج النبيّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  أَنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  دَخَلَ عَلَيْهَا فَقَـــالَ: هَلْ مِنْ طَعَامٍ؟ قَالَتْ: لا والله يَا رَسُولَ الله مَا عِنْدَنَا طَعَامٌ إِلا عَظْمٌ مِنْ شَاةٍ أُعْطِيَتْهُ مَوْلاتِي مِنْ الصَّدَقَةِ، فَقَـالَ: قَرِّبِيهِ فَقَدْ بَلَغَتْ مَحِلَّهَا ."],"takhrij":"صحيح: رواه مسلم في الزكاة (1073) من طرق عن الليث، عن ابن شهاب، ، أنّ عبيد بن السباق، قال: إنّ جويرية زوج النبيّ صلى الله عليه وسلم  أخرته... فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب إذا تحولت الصدقة هدية جازت للنبي ﷺ ولآله","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1073).","chapter_en":"If charity becomes a gift, it becomes lawful for the Prophet ﷺ and his family","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Juwayriyyah, the wife of the Prophet ﷺ, reported that the Messenger of Allah ﷺ entered upon her and said: “Do you have any food?” She said: “No, by Allah, O Messenger of Allah ﷺ, we have no food except a bone from a sheep that was given to my servant from charity.” He said: “Bring it near, for it has already reached its lawful place.”"]},"buhuth":{"en":["Regarding his statement “it has reached its lawful place,” al-Nawawi said: the word is read with a kasrah on the letter ḥa’, meaning that the ruling of charity no longer applied to it, and it had become lawful for us."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1073)."},{"num":4280,"demo":false,"sanad":"","matn":["عن أبي رافع، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  بَعَثَ رَجُلاً عَلَى الصَّدَقَةِ مِنْ بَنِي مَخْزُومٍ فَقَالَ لأَبِي رَافِعٍ: اصْحَبْنِي فَإِنَّكَ تُصِيبُ مِنْهَا. قَال: حَتَّى آتِيَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَأَسْأَلَهُ فَأَتَاهُ فَسَأَلَهُ، فَقَالَ: مَوْلَى الْقَوْمِ مِنْ أَنْفُسِهِمْ وَإِنَّا لا تَحِلُّ لَنَا الصَّدَقَةُ ."],"takhrij":"صحيح: رواه أبو داود (1650)، والترمذيّ (657)، والنسائيّ (2613) كلّهم من طرق عن شعبة، عن الحكم، عن ابن أبي رافع، عن أبي رافع، فذكره.","grade":"صحيح","chapter_ar":"باب كراهية الصدقة على موالي رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (1650), al-Tirmidhi (657), and al-Nasa’i (2613). Al-Tirmidhi said: “Hasan sahih.”","chapter_en":"The dislike of giving charity to the freed servants of the Messenger of Allah ﷺ","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":6,"content":{"translation":{"en":["Abu Rafiʿ reported that the Prophet ﷺ appointed a man from Banu Makhzum over the charity collection. That man said to Abu Rafiʿ: “Come with me, and you will get a share from it.” Abu Rafiʿ said: “Not until I go to the Prophet ﷺ and ask him.” So he came to him and asked him, and he said: “The freed servant of a people is counted as one of them, and charity is not lawful for us.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1650)، والترمذي (657)، والنسائي (2613). قال الترمذي: (( حسن صحيح ))."},{"num":4281,"demo":false,"sanad":"","matn":["عن مَيْمُونَ أَوْ مِهْرَانَ مَوْلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  أَخْبَرَنِي أَنَّهُ مَرَّ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَقَالَ لَهُ يَا مَيْمُونُ أَوْ يَا مِهْرَانُ: إِنَّا أَهْلُ بَيْتٍ نُهِينَا عَنْ الصَّدَقَةِ وَإِنَّ مَوَالِيَنَا مِنْ أَنْفُسِنَا وَلا نَأْكُلُ الصَّدَقَةَ ."],"takhrij":"حسن: رواه الإمام أحمد (16399) عن عبد الرزاق، وهو في مصنفه (6942) وعنه الطبراني أيضاً في الكبير 20/ (836) عن سفيان، عن عطاء ابن السائب، حدّثني أمّ كلثوم ابنة علي، قال: أتيتها بصدقة كان أمر بها، قالت: احذر شبابنا، فإن ميمون أو مهران، فذكره.","grade":"حسن","chapter_ar":"باب كراهية الصدقة على موالي رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (16399) and ʿAbd al-Razzaq in his Musannaf (6942).","chapter_en":"The dislike of giving charity to the freed servants of the Messenger of Allah ﷺ","part_en":"Zakat","group_ar":"جموع أبواب الزكاة بأنها لا تحل للنبي ﷺ","group_en":"Collected chapters on the fact that zakah is not lawful for the Prophet ﷺ","part_no":14,"group_no":10,"chapter_no":6,"content":{"translation":{"en":["Maymun, or Mihran, the freed servant of the Prophet ﷺ, reported that the Prophet ﷺ passed by him and said: “O Maymun” — or “O Mihran” — “We are a household for whom charity has been forbidden, and our freed servants are counted as part of us, and we do not eat charity.”"]},"buhuth":{"en":["His statement “The freed servant of a people is counted as one of them” means following them and adopting their way in avoiding what they avoid. It also appears that the Prophet ﷺ used to provide for him, since Abu Rafiʿ used to handle his needs and service. So the meaning is: if you are sufficiently provided for by what you are given, then do not seek the impurities of people’s wealth, for you are our client and one of us. See: Sharh al-Sunnah (6/103)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (16399)، وعبد الرزاق في مصنفه (6942)."},{"num":4282,"demo":false,"sanad":"","matn":["عن عبدالله بن عمر، أَنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَرَضَ زَكَاةَ الْفِطْرِ صَاعًا مِنْ تَمْرٍ، أَوْ صَاعًا مِنْ شَعِيرٍ عَلَى كُلِّ حُرٍّ أَوْ عَبْدٍ ذَكَرٍ أَوْ أُنْثَى مِنْ المُسْلِمِينَ."],"takhrij":"متفق عليه: رواه مالك في الزكاة (52) عن نافع، عن عبدالله بن عمر، فذكره.","grade":"متفق عليه","chapter_ar":"باب فرض صدقة الفطر على الحر والعبد، والذكر والأنثى، والصغير والكبير من المسلمين","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (52), al-Bukhari (1504), and Muslim (984).","chapter_en":"The obligation of Zakat al-Fitr upon the free and the slave, male and female, young and old among the Muslims","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في صدقة الفطر","group_en":"Collected chapters on what has come regarding Zakat al-Fitr","part_no":14,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar reported that the Messenger of Allah ﷺ made Zakat al-Fitr obligatory as one saʿ of dates, or one saʿ of barley, upon every free person or slave, male or female, among the Muslims."]},"intro_majmu":{"en":["Collected chapters on what has come regarding Zakat al-Fitr"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (52)، والبخاري (1504)، ومسلم (984)."},{"num":4283,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: فَرَضَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  صَدَقَةَ الْفِطْرِ - أَوْ قَالَ رَمَضَانَ - عَلَى الذَّكَرِ وَالأُنْثَى وَالحُرِّ وَالْمَمْلُوكِ صَاعًا مِنْ تَمْرٍ أَوْ صَاعًا مِنْ شَعِيرٍ فَعَدَلَ النَّاسُ بِهِ نِصْفَ صَاعٍ مِنْ بُرٍّ .","فَكَانَ ابْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا يُعْطِي التَّمْرَ فَأَعْوَزَ أَهْلُ المَدِينَةِ مِنْ التَّمْرِ فَأَعْطَى شَعِيرًا، فَكَانَ ابْنُ عُمَرَ يُعْطِي عَنْ الصَّغِيرِ وَالْكَبِيرِ حَتَّى إِنْ كَانَ لِيُعْطِي عَنْ بَنِيَّ، وَكَانَ ابْنُ عُمَرَ رَضِيَ الله عَنْهُمَا يُعْطِيهَا الَّذِينَ يَقْبَلُونَهَا وَكَانُوا يُعْطُونَ قَبْلَ الْفِطْرِ بِيَوْمٍ أَوْ يَوْمَيْنِ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1511)، ومسلم في الزكاة (984: 14) كلاهما من طريق أيوب، عن نافع، عن ابن عمر، فذكره.","grade":"متفق عليه","chapter_ar":"باب فرض صدقة الفطر على الحر والعبد، والذكر والأنثى، والصغير والكبير من المسلمين","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (1511) and Muslim (984 no. 14). This is the wording of al-Bukhari.","chapter_en":"The obligation of Zakat al-Fitr upon the free and the slave, male and female, young and old among the Muslims","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في صدقة الفطر","group_en":"Collected chapters on what has come regarding Zakat al-Fitr","part_no":14,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿUmar said: The Prophet ﷺ made Sadaqat al-Fitr — or he said: the charity of Ramadan — obligatory upon male and female, free and slave, as one saʿ of dates or one saʿ of barley. Then people considered half a saʿ of wheat equivalent to that. Ibn ʿUmar, may Allah be pleased with them, both, used to give dates, but when the people of Madinah had a shortage of dates, he gave barley instead. Ibn ʿUmar used to give on behalf of the young and the old, and he would even give on behalf of my children. He used to give it to those who accepted it, and they used to distribute it one or two days before the Eid al-Fitr."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1511)، ومسلم (984: 14). واللفظ للبخاري."},{"num":4284,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قال: لَيْسَ فِي الْعَبْدِ صَدَقَةٌ إِلا صَدَقَةُ الْفِطْرِ ."],"takhrij":"صحيح: رواه مسلم (982/10) من طرق عن ابن وهب، أخبرني مخرمة، عن أبيه، عن عراك بن مالك، قال: سمعت أبا هريرة يحدّث عن رسول الله صلى الله عليه وسلم ، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب فرض صدقة الفطر على الحر والعبد، والذكر والأنثى، والصغير والكبير من المسلمين","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (982 no. 10).","chapter_en":"The obligation of Zakat al-Fitr upon the free and the slave, male and female, young and old among the Muslims","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في صدقة الفطر","group_en":"Collected chapters on what has come regarding Zakat al-Fitr","part_no":14,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “There is no obligatory charity due upon a slave except the charity of breaking the fast.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (982/10)."},{"num":4285,"demo":false,"sanad":"","matn":["عَنْ قَيْسِ بْنِ سَعْدٍ، قَالَ: أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِصَدَقَةِ الْفِطْرِ قَبْلَ أَنْ تُنْزَلَ الزَّكَاةُ، فَلَمَّا نَزَلَتِ الزَّكَاةُ لَمْ يَأْمُرْنَا وَلَمْ يَنْهَنَا وَنَحْنُ نَفْعَلُهُ."],"takhrij":"صحيح: رواه النسائي (2507)، وابن ماجه (1828) كلاهما من حديث وكيع، عن سفيان، عن سلمة بن كهيل، عن القاسم بن مُخيمرة، عن أبي عمار، عن قيس بن سعد، قال: فذكره. وصحّحه ابن خزيمة (2394).","grade":"صحيح","chapter_ar":"باب أن فرض زكاة الفطر كان قبل فرض الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasa’i (2507), Ibn Majah (1828), and authenticated by Ibn Khuzaymah (2394).","chapter_en":"That the obligation of Zakat al-Fitr came before the obligation of the regular zakah","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في صدقة الفطر","group_en":"Collected chapters on what has come regarding Zakat al-Fitr","part_no":14,"group_no":11,"chapter_no":2,"content":{"translation":{"en":["Qays ibn Saʿd said: The Messenger of Allah ﷺ commanded us to give the charity of breaking the fast before zakah was revealed. Then when zakah was later made obligatory, he neither ordered us again nor forbade us from it, and we continued to practice it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (2507)، وابن ماجه (1828)، وصححه ابن خزيمة (2394)."},{"num":4286,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدريّ، قال: كُنَّا نُخْرِجُ زَكَاةَ الْفِطْرِ صَاعًا مِنْ طَعَامٍ أَوْ صَاعًا مِنْ شَعِيرٍ أَوْ صَاعًا مِنْ تَمْرٍ أَوْ صَاعًا مِنْ أَقِطٍ أَوْ صَاعًا مِنْ زَبِيبٍ وَذَلِكَ بِصَاعِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ."],"takhrij":"متفق عليه: رواه مالك في الزكاة (53) عن زيد بن أسلم، عن عياض بن عبدالله بن سعد بن أبي سرح العامريّ، أنّه سمع أبا سعيد الخدريّ، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب زكاة الفطر صاع من طعام البلد","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (53), al-Bukhari (1506), and Muslim (985).","chapter_en":"Zakat al-Fitr is one saʿ from the staple food of the land","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في صدقة الفطر","group_en":"Collected chapters on what has come regarding Zakat al-Fitr","part_no":14,"group_no":11,"chapter_no":3,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: We used to give Zakat al-Fitr as one saʿ of food, or one saʿ of barley, or one saʿ of dates, or one saʿ of dried yogurt, or one saʿ of raisins, and that was according to the saʿ of the Prophet ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (53)، والبخاري (1506)، ومسلم (985)."},{"num":4287,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري، قـال: كُنَّا نُخْرِجُ إِذْ كَانَ فِينَا رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  زَكَاةَ الْفِطْرِ عَنْ كُلِّ صَغِيرٍ وَكَبِيرٍ حُرٍّ أَوْ مَمْلُوكٍ صَاعًا مِنْ طَعَامٍ أَوْ صَاعًا مِنْ أَقِطٍ أَوْ صَاعًا مِنْ شَعِيرٍ أَوْ صَاعًا مِنْ تَمْرٍ أَوْ صَاعًا مِنْ زَبِيبٍ. فَلَمْ نَزَلْ نُخْرِجُهُ حَتَّى قَدِمَ عَلَيْنَا مُعَاوِيَةُ بْنُ أَبِي سُفْيَانَ حَاجًّا أَوْ مُعْتَمِرًا فَكَلَّمَ النَّاسَ عَلَى الْمِنْبَرِ فَكَانَ فِيمَا كَلَّمَ بِهِ النَّاسَ أَنْ قَالَ: إِنِّي أَرَى أَنَّ مُدَّيْنِ مِنْ سَمْرَاءِ الشَّامِ تَعْدِلُ صَاعًا مِنْ تَمْرٍ فَأَخَذَ النَّاسُ بِذَلِكَ. قَالَ أَبُو سَعِيدٍ: فَأَمَّا أَنَا فَلا أَزَالُ أُخْرِجُهُ كَمَا كُنْتُ أُخْرِجُهُ أَبَدًا مَا عِشْتُ."],"takhrij":"صحيح: رواه مسلم في الزكاة (985) عن عبدالله بن مسلمة بن قعنب، حدثنا داود (يعني ابن قيس)، عن عياض بن عبدالله، عن أبي سعيد الخدريّ، قال (فذكره). ورواه مالك مختصراً كما سبق.","grade":"صحيح","chapter_ar":"باب زكاة الفطر صاع من طعام البلد","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (985).","chapter_en":"Zakat al-Fitr is one saʿ from the staple food of the land","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في صدقة الفطر","group_en":"Collected chapters on what has come regarding Zakat al-Fitr","part_no":14,"group_no":11,"chapter_no":3,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: When the Messenger of Allah ﷺ was among us, we used to give Zakat al-Fitr on behalf of every young and old person, free or owned, as one saʿ of food, or one saʿ of dried yogurt, or one saʿ of barley, or one saʿ of dates, or one saʿ of raisins. We continued doing so until Muʿawiyah ibn Abi Sufyan came to us for Hajj or ʿUmrah and addressed the people from the pulpit. Among what he said to the people was: “I consider two mudd of the wheat of Syria equal to one saʿ of dates.” So the people adopted that. Abu Saʿid said: As for me, I will continue to give it exactly as I used to give it for as long as I live."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (985)."},{"num":4288,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: لَمْ تَكُنِ الصَّدَقَةُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَّا التَّمْرُ وَالزَّبِيبُ وَالشَّعِيرُ، وَلَمْ تَكُنِ الْحِنْطَةُ."],"takhrij":"صحيح: رواه ابن حزيمة (2406) عن محمد بن سفيان بن أبي الزناد الأبلي، حدّثنا عبدالله بن موسى، أخبرنا فضيل بن غزوان، عن نافع، عن ابن عمر، فذكره.","grade":"صحيح","chapter_ar":"باب زكاة الفطر صاع من طعام البلد","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Khuzaymah (2406).","chapter_en":"Zakat al-Fitr is one saʿ from the staple food of the land","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في صدقة الفطر","group_en":"Collected chapters on what has come regarding Zakat al-Fitr","part_no":14,"group_no":11,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: During the time of the Messenger of Allah ﷺ, the charity was only given in dates, raisins, and barley; wheat was not given."]},"buhuth":{"en":["As for giving the cash value instead of food, the majority of scholars hold that it is not permissible, because the Lawgiver obligated Zakat al-Fitr in the form of food. So if one turns away from that, then the prescribed form has been abandoned.","The Hanafis differed and said: it is permissible to give the value of all these items in silver coins or gold coins, because the purpose of Zakat al-Fitr is to spare the poor person from begging on that day. They cited as evidence the saying: “Make them free from asking on a day like this.” But this report is weak.","It was narrated by al-Daraqutni (2133), and in its chain is Abu Maʿshar Najih ibn ʿAbd al-Rahman al-Sindi, who is weak by the agreement of the scholars. His memory deteriorated and he became confused. Al-Bukhari said: “His hadith is objectionable.” Abu Dawud, al-Nasa’i, and others also declared him weak.","As for today, because people’s conditions and circumstances vary, scholars in Egypt, Sudan, and the United Arab Emirates, as well as some members of the Council of Senior Scholars in Saudi Arabia, have given verdicts allowing the giving of cash for Zakat al-Fitr because people may need that more than food. This is considered consistent with the objectives of Islamic law."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن خزيمة (2406)."},{"num":4289,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، رَضِيَ اللَّهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِزَكَاةِ الْفِطْرِ قَبْلَ خُرُوجِ النَّاسِ إِلَى الصَّلاَةِ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1509)، ومسلم في الزكاة (986) كلاهما من طريق موسى بن عقبة، عن نافع، عن ابن عمر، فذكره.","grade":"متفق عليه","chapter_ar":"باب إخراج زكاة الفطر قبل الخروج إلى المصلى","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1509) and Muslim (986).","chapter_en":"Giving Zakat al-Fitr before going out to the prayer place","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في صدقة الفطر","group_en":"Collected chapters on what has come regarding Zakat al-Fitr","part_no":14,"group_no":11,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿUmar reported that the Prophet ﷺ commanded that Zakat al-Fitr be given before the people went out to the Eid prayer."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1509)، ومسلم (986)."},{"num":4290,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: فَرَضَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَدَقَةَ الْفِطْرِ.... وَكَانُوا يُعْطُونَ قَبْلَ الْفِطْرِ بِيَوْمٍ أَوْ يَوْمَيْنِ."],"takhrij":"صحيح: رواه البخاريّ في الزكاة (1511) عن أبي النعمان، حدّثنا حماد ابن زيد، حدّثنا أيوب، عن نافع، عن ابن عمر، فذكره.","grade":"صحيح","chapter_ar":"باب إخراج زكاة الفطر قبل الخروج إلى المصلى","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (1511).","chapter_en":"Giving Zakat al-Fitr before going out to the prayer place","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في صدقة الفطر","group_en":"Collected chapters on what has come regarding Zakat al-Fitr","part_no":14,"group_no":11,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿUmar reported: “The Prophet ﷺ made Ṣadaqat al-Fiṭr—or he said, the charity of Ramadan—obligatory upon every male and female, free person and slave: one ṣāʿ of dates or one ṣāʿ of barley.” The people later considered half a ṣāʿ of wheat equivalent to that. Ibn ʿUmar, may Allah be pleased with them, both, used to give dates. When dates became scarce among the people of Madinah, he gave barley instead. Ibn ʿUmar used to give it on behalf of both young and old, to the extent that he would even give it on behalf of my children. He used to give it to those appointed to receive it, and the people used to give Ṣadaqat al-Fiṭr one or two days before Eid al-Fiṭr."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1511).","voc":["bukhari",1511]},{"num":4291,"demo":false,"sanad":"","matn":["عن عبدالله بن عباس، قال: فَرَضَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  زَكَاةَ الْفِطْرِ طُهْرَةً لِلصَّائِمِ مِنْ اللَّغْوِ وَالرَّفَثِ وَطُعْمَةً لِلْمَسَاكِينِ. مَنْ أَدَّاهَا قَبْلَ الصَّلاةِ فَهِيَ زَكَاةٌ مَقْبُولَةٌ، وَمَنْ أَدَّاهَا بَعْدَ الصَّلاةِ فَهِيَ صَدَقَةٌ مِنْ الصَّدَقَاتِ."],"takhrij":"حسن: رواه أبو داود (1609)، وابن ماجه (1827) كلاهما من حديث مروان بن محمد، قال: حدّثنا أبو يزيد الخولانيّ، عن سيار بن عبدالرحمن الصّدفيّ، عن عكرمة، عن ابن عباس، فذكره. وصحّحه الحاكم (1488) وقال: على شرط البخاريّ.","grade":"حسن","chapter_ar":"باب زكاة الفطر طهرة للصائم من اللغو والرفث","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (1609), Ibn Majah (1827), and authenticated by al-Hakim (1/409).","chapter_en":"Zakat al-Fitr is a purification for the fasting person from idle speech and indecent talk","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في صدقة الفطر","group_en":"Collected chapters on what has come regarding Zakat al-Fitr","part_no":14,"group_no":11,"chapter_no":6,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas said: The Messenger of Allah ﷺ made Zakat al-Fitr obligatory as a purification for the fasting person from idle speech and indecent talk, and as food for the poor. Whoever gives it before the prayer, it is an accepted zakah, and whoever gives it after the prayer, it is just a charity from among the charities."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1609)، وابن ماجه (1827)، وصححه الحاكم (1488)."},{"num":4292,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: وَكَّلَنِي رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  بِحِفْظِ زَكَاةِ رَمَضَانَ، فَأَتَانِي آتٍ، فَجَعَلَ يَحْثُو مِنْ الطَّعَامِ فَأَخَذْتُهُ، وَقُلْتُ: وَالله لَأَرْفَعَنَّكَ إِلَى رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، قَالَ: إِنِّي مُحْتَاجٌ وَعَلَيَّ عِيَالٌ وَلِي حَاجَةٌ شَدِيدَةٌ، قَالَ: فَخَلَّيْتُ عَنْه،ُ فَأَصْبَحْتُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : يَا أَبَا هُرَيْرَةَ مَا فَعَلَ أَسِيرُكَ الْبَارِحَةَ؟ قَالَ: قُلْتُ: يَا رَسُولَ الله شَكَا حَاجَةً شَدِيدَةً وَعِيَالًا، فَرَحِمْتُهُ، فَخَلَّيْتُ سَبِيلَهُ قَالَ: أَمَا إِنَّهُ قَدْ كَذَبَكَ وَسَيَعُودُ ، فَعَرَفْتُ أَنَّهُ سَيَعُودُ لِقَوْلِ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّهُ سَيَعُودُ فَرَصَدْتُهُ، فَجَاءَ يَحْثُو مِنْ الطَّعَامِ، فَأَخَذْتُهُ، فَقُلْتُ: لَأَرْفَعَنَّكَ إِلَى رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَالَ: دَعْنِي، فَإِنِّي مُحْتَاجٌ، وَعَلَيَّ عِيَالٌ لَا أَعُودُ فَرَحِمْتُهُ، فَخَلَّيْتُ سَبِيلَهُ، فَأَصْبَحْتُ، فَقَالَ لِي رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : يَا أَبَا هُرَيْرَةَ مَا فَعَلَ أَسِيرُكَ؟ قُلْتُ: يَا رَسُولَ الله شَكَا حَاجَةً شَدِيدَةً وَعِيَالًا فَرَحِمْتُهُ، فَخَلَّيْتُ سَبِيلَهُ قَالَ: أَمَا إِنَّهُ قَدْ كَذَبَكَ وَسَيَعُودُ فَرَصَدْتُهُ، فَجَاءَ يَحْثُو مِنْ الطَّعَامِ، فَأَخَذْتُهُ، فَقُلْتُ: لَأَرْفَعَنَّكَ إِلَى رَسُولِ الله، وَهَذَا آخِرُ ثَلَاثِ مَرَّاتٍ أَنَّكَ تَزْعُمُ لَا تَعُودُ، ثُمَّ تعود، قَالَ دَعْنِي أُعَلِّمْكَ كَلِمَاتٍ يَنْفَعُكَ الله بِهَا قُلْتُ: مَا ؟ قَالَ: إِذَا أَوَيْتَ إِلَى فِرَاشِكَ فَاقْرَأْ آيَةَ الْكُرْسِيِّ: اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ حَتَّى تَخْتِمَ الْآيَةَ، فَإِنَّكَ لَنْ يَزَالَ عَلَيْكَ مِن الله حَافِظٌ، وَلَا يَقْرَبَنَّكَ شَيْطَانٌ حَتَّى تُصْبِحَ، فَخَلَّيْتُ سَبِيلَهُ، فَأَصْبَحْتُ، فَقَالَ لِي رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَا فَعَلَ أَسِيرُكَ الْبَارِحَةَ؟ قُلْتُ: يَا رَسُولَ الله زَعَمَ أَنَّهُ يُعَلِّمُنِي كَلِمَاتٍ يَنْفَعُنِي الله بِهَا، فَخَلَّيْتُ سَبِيلَهُ قَالَ: مَا هِيَ؟ قُلْتُ: قَالَ لِي: إِذَا أَوَيْتَ إِلَى فِرَاشِكَ فَاقْرَأْ آيَةَ الْكُرْسِيِّ مِنْ أَوَّلِهَا حَتَّى تَخْتِمَ الْآيَةَ: اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ وَقَالَ لِي: لَنْ يَزَالَ عَلَيْكَ مِن الله حَافِظٌ، وَلَا يَقْرَبَكَ شَيْطَانٌ حَتَّى تُصْبِحَ، وَكَانُوا أَحْرَصَ شَيْءٍ عَلَى الخَيْرِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَمَا إِنَّهُ قَدْ صَدَقَكَ وَهُوَ كَذُوبٌ، تَعْلَمُ مَنْ تُخَاطِبُ مُنْذُ ثَلَاثِ لَيَالٍ يَا أَبَا هُرَيْرَةَ؟ قَالَ: لَا. قَالَ: ذَاكَ شَيْطَانٌ ."],"takhrij":"صحيح: ذكره البخاري في الوكالة (2311) تعليقا قال: وقال عثمان بن الهيثم أبو عمرو، حدثنا عوف، عن محمد بن سيرين، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب جمع الإمام زكاة الفطر لتوزيعها على الفقراء","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (2311) in a suspended form, and connected by al-Nasa’i in al-Sunan al-Kubra (10729).","chapter_en":"The ruler collecting Zakat al-Fitr in order to distribute it to the poor","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في صدقة الفطر","group_en":"Collected chapters on what has come regarding Zakat al-Fitr","part_no":14,"group_no":11,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ put me in charge of guarding the Ramadan charity. Then someone came and began scooping up food. I seized him and said, “By Allah, I will take you to the Messenger of Allah ﷺ.” He said, “I am needy, I have dependents, and I am in severe need.” So I let him go. In the morning, the Prophet ﷺ said: “O Abu Hurayrah, what happened to your prisoner last night?” I said, “O Messenger of Allah ﷺ, he complained of severe need and dependents, so I felt mercy for him and let him go.” He said: “Indeed, he lied to you, and he will return.” So I knew he would return because the Messenger of Allah ﷺ had said, “He will return.” I waited for him, and he came again scooping food. I seized him and said, “I will surely take you to the Messenger of Allah ﷺ.” He said, “Leave me, for I am needy and I have dependents. I will not return.” So I felt mercy for him and let him go. In the morning, the Messenger of Allah ﷺ said to me: “O Abu Hurayrah, what happened to your prisoner?” I said, “O Messenger of Allah ﷺ, he complained of severe need and dependents, so I felt mercy for him and let him go.” He said: “Indeed, he lied to you, and he will return.” So I waited for him, and he came again scooping food. I seized him and said, “I will surely take you to the Messenger of Allah ﷺ. This is the third and final time. You keep claiming you will not return, yet you return.” He said, “Leave me, and I will teach you some words by which Allah will benefit you.” I said, “What are they?” He said, “When you go to your bed, recite the Verse of the Throne: ‘Allah — there is no god except Him, the Ever-Living, the Sustainer of all.’ until you complete the verse. Then a guardian from Allah will remain over you, and no devil will come near you until morning.” So I let him go. In the morning, the Messenger of Allah ﷺ said to me: “What happened to your prisoner last night?” I said, “O Messenger of Allah ﷺ, he claimed that he would teach me some words by which Allah would benefit me, so I let him go.” He said: “What were they?” I said, “He told me: when you go to your bed, recite the Verse of the Throne from its beginning until the end: ‘Allah — there is no god except Him, the Ever-Living, the Sustainer of all.’ And he told me: a guardian from Allah will remain over you, and no devil will come near you until morning.” They were the most eager of people for good, so the Prophet ﷺ said: “He has told you the truth, though he is a great liar. Do you know whom you have been speaking with for the last three nights, O Abu Hurayrah?” He said, “No.” He said: “That was a devil.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2311) تعليقا، ووصله النسائي في الكبرى (10729)."},{"num":4293,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: بُنِيَ الإِسْلاَمُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ، وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلاَةِ، وَإِيتَاءِ الزَّكَاةِ، وَالْحَجِّ، وَصَوْمِ رَمَضَانَ."],"takhrij":"متفق عليه: رواه البخاريّ في الإيمان (8)، ومسلم في الإيمان (16/22) كلاهما من حديث حنظلة بن أبي سفيان قال: سمعتُ عكرمة بن خالد، عن ابن عمر، فذكر الحديث، واللّفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب وجوب صوم شهر رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (8) and Muslim (22 no. 16). This is the wording of al-Bukhari.","chapter_en":"The obligation of fasting the month of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: The Messenger of Allah ﷺ said: “Islam is built upon five: testifying that there is no god but Allah and that Muhammad is the Messenger of Allah, establishing the prayer, giving zakah, pilgrimage, and fasting Ramadan.”"]},"intro":{"ar":["قال الله تعالى:","(يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ) [سورة البقرة: ١٨٣].","وقال تعالى:","(شَهْرُ رَمَضَانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ هُدًى لِلنَّاسِ وَبَيِّنَاتٍ مِنَ الْهُدَى وَالْفُرْقَانِ فَمَنْ شَهِدَ مِنْكُمُ الشَّهْرَ فَلْيَصُمْهُ) [سورة البقرة: ١٨٥]."],"en":["Allah Most High said:","“O you who believe, fasting has been prescribed for you as it was prescribed for those before you, so that you may become mindful of Allah.” [Surah al-Baqarah: 183]","And He said:","“The month of Ramadan is the one in which the Quran was sent down as guidance for mankind, with clear proofs of guidance and the criterion. So whoever among you witnesses the month, let him fast it.” [Surah al-Baqarah: 185]"]}},"tuhfa":{},"full":1,"rep":[31,4714],"tks":"متفق عليه: رواه البخاري (8)، ومسلم (16/22)، واللفظ للبخاري."},{"num":4294,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ،  أَنَّ أَعْرَابِيًّا جَاءَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، دُلَّنِي عَلَى عَمَلٍ إِذَا عَمِلْتُهُ دَخَلْتُ الْجَنَّةَ، قَالَ: تَعْبُدُ اللَّهَ لَا تُشْرِكُ بِهِ شَيْئًا، وَتُقِيمُ الصَّلَاةَ الْمَكْتُوبَةَ، وَتُؤَدِّي الزَّكَاةَ الْمَفْرُوضَةَ، وَتَصُومُ رَمَضَانَ، قَالَ: وَالَّذِي نَفْسِي بِيَدِهِ لَا أَزِيدُ عَلَى هَذَا شَيْئًا أَبَدًا، وَلَا أَنْقُصُ مِنْهُ، فَلَمَّا وَلَّى قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ سَرَّهُ أَنْ يَنْظُرَ إِلَى رَجُلٍ مِنْ أَهْلِ الْجَنَّةِ، فَلْيَنْظُرْ إِلَى هَذَا."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1397)، ومسلم في الإيمان (14) كلاهما من طريق عفّان بن مسلم، حدّثنا وُهيب، عن يحيى بن سعيد بن حيان، عن أبي زرعة، عن أبي هريرة، فذكر الحديث. واللّفظ لمسلم، ولفظ البخاريّ نحوه.","grade":"متفق عليه","chapter_ar":"باب وجوب صوم شهر رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1397) and Muslim (14). This is the wording of Muslim.","chapter_en":"The obligation of fasting the month of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah reported that a Bedouin came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, guide me to a deed which, if I do it, I will enter Paradise.” He said: “Worship Allah and associate nothing with Him, establish the prescribed prayer, give the obligatory zakah, and fast Ramadan.” He said: “By the One in whose hand is my soul, I will never add anything to this, nor will I subtract from it.” When he turned away, the Prophet ﷺ said: “Whoever would be pleased to look at a man from the people of Paradise, let him look at this one.”"]}},"tuhfa":{},"full":1,"rep":[3909],"tks":"متفق عليه: رواه البخاري (1397)، ومسلم (14)، واللفظ لمسلم."},{"num":4295,"demo":false,"sanad":"","matn":["عن طَلْحَةَ بن عبيدالله عُبَيْدِ اللَّهِ، يَقُولُ: جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ أَهْلِ نَجْدٍ، ثَائِرُ الرَّأْسِ، يُسْمَعُ دَوِيُّ صَوْتِهِ، وَلاَ يُفْقَهُ مَا يَقُولُ، حَتَّى دَنَا، فَإِذَا هُوَ يَسْأَلُ عَنِ الإِسْلاَمِ، فَقَالَ رَسُولُ اللَّهِ ـ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خَمْسُ صَلَوَاتٍ فِي الْيَوْمِ وَاللَّيْلَةِ. فَقَالَ: هَلْ عَلَىَّ غَيْرُهَا؟ قَالَ: لاَ، إِلاَّ أَنْ تَطَوَّعَ. قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَصِيَامُ رَمَضَانَ. قَالَ: هَلْ عَلَىَّ غَيْرُهُ؟ قَالَ: لاَ، إِلاَّ أَنْ تَطَوَّعَ. قَالَ: وَذَكَرَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الزَّكَاةَ. قَالَ: هَلْ عَلَىَّ غَيْرُهَا؟ قَالَ: لاَ، إِلاَّ أَنْ تَطَوَّعَ. قَالَ: فَأَدْبَرَ الرَّجُلُ وَهُوَ يَقُولُ: وَاللَّهِ لاَ أَزِيدُ عَلَى هَذَا وَلاَ أَنْقُصُ. قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَفْلَحَ إِنْ صَدَقَ."],"takhrij":"متفق عليه: رواه مالك في قصر الصلاة (94) عن عمه أبي سُهيل ابن مالك، عن أبيه، أنه سمع طلحة بن عبيدالله فذكر الحديث، ورواه البخاري في الإيمان (46)، ومسلم في الإيمان (8) كلاهم من طريق مالك، ومضى هذا الحديث بكامله في كتاب الإيمان.","grade":"متفق عليه","chapter_ar":"باب وجوب صوم شهر رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (94), al-Bukhari (46), and Muslim (8).","chapter_en":"The obligation of fasting the month of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Talhah ibn ʿUbaydillah said: A man from Najd came to the Messenger of Allah ﷺ with disheveled hair. The loud murmur of his voice could be heard, but what he was saying could not be understood until he came near, and then it became clear that he was asking about Islam. So the Messenger of Allah ﷺ said: “Five prayers in the day and the night.” He said: “Is there anything else required of me?” He said: “No, unless you do extra voluntary acts.” Then the Messenger of Allah ﷺ said: “And fasting Ramadan.” He said: “Is there anything else required of me?” He said: “No, unless you do extra voluntary acts.” Then the Messenger of Allah ﷺ mentioned zakah, and the man said: “Is there anything else required of me?” He said: “No, unless you do extra voluntary acts.” Then the man turned away saying: “By Allah, I will neither add to this nor reduce from it.” The Messenger of Allah ﷺ said: “He has succeeded, if he is truthful.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه مالك (94)، والبخاري (46)، ومسلم (8)."},{"num":4296,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ أَصْحَابُ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا كَانَ الرَّجُلُ صَائِمًا، فَحَضَرَ الإِفْطَارُ، فَنَامَ قَبْلَ أَنْ يُفْطِرَ لَمْ يَأْكُلْ لَيْلَتَهُ وَلاَ يَوْمَهُ، حَتَّى يُمْسِيَ، وَإِنَّ قَيْسَ بْنَ صِرْمَةَ الأَنْصَارِيَّ كَانَ صَائِمًا، فَلَمَّا حَضَرَ الإِفْطَارُ أَتَى امْرَأَتَهُ، فَقَالَ لَهَا: أَعِنْدَكِ طَعَامٌ؟ قَالَتْ: لاَ، وَلَكِنْ أَنْطَلِقُ، فَأَطْلُبُ لَكَ. وَكَانَ يَوْمَهُ يَعْمَلُ، فَغَلَبَتْهُ عَيْنَاهُ، فَجَاءَتْهُ امْرَأَتُهُ، فَلَمَّا رَأَتْهُ قَالَتْ: خَيْبَةً لَكَ. فَلَمَّا انْتَصَفَ النَّهَارُ غُشِيَ عَلَيْهِ، فَذُكِرَ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَنَزَلَتْ هَذِهِ الآيَةُ: ﴿أُحِلَّ لَكُمْ لَيْلَةَ الصِّيَامِ الرَّفَثُ إِلَى نِسَائِكُمْ﴾ [سورة البقرة: 187]} فَفَرِحُوا بِهَا فَرَحًا شَدِيدًا، وَنَزَلَتْ: ﴿وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الأَبْيَضُ مِنَ الْخَيْطِ الأَسْوَدِ﴾ [سورة البقرة: 187]}."],"takhrij":"صحيح: رواه البخاريّ في الصّوم (1915) عن عبيدالله بن موسى، عن إسرائيل، عن أبي إسحاق، عن البراء، فذكره.","grade":"صحيح","chapter_ar":"باب وجوب صوم شهر رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (1915).","chapter_en":"The obligation of fasting the month of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Al-Bara’ said: The companions of Muhammad ﷺ, when a man was fasting and the time of breaking the fast came, if he fell asleep before eating, he would not eat that night or the following day until evening. Qays ibn Sirmah al-Ansari was fasting, and when the time of breaking the fast came, he went to his wife and said to her, “Do you have any food?” She said, “No, but I will go and look for some for you.” He had spent the day working, so his eyes overcame him and he fell asleep. When his wife came and saw him, she said, “What a loss for you!” Then when midday came, he fainted. That was mentioned to the Prophet ﷺ, so this verse was revealed: “It has been made lawful for you, on the night of fasting, to have intimate relations with your wives.” [Surah al-Baqarah: 187] So they rejoiced greatly at it. And this was also revealed: “And eat and drink until the white thread becomes distinct to you from the black thread.” [Surah al-Baqarah: 187]"]}},"tuhfa":{},"full":1,"rep":[11958],"tks":"صحيح: رواه البخاري (1915)."},{"num":4297,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِنْ قَبْلِكُمْ﴾ [سورة البقرة: 183]، } فَكَانَ النَّاسُ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّوُا الْعَتَمَةَ: حَرُمَ عَلَيْهِمُ الطَّعَامُ وَالشَّرَابُ وَالنِّسَاءُ، وَصَامُوا إِلَى الْقَابِلَةِ. فَاخْتَانَ رَجُلٌ نَفْسَهُ فَجَامَعَ امْرَأَتَهُ وَقَدْ صَلَّى الْعِشَاءَ وَلَمْ يُفْطِرْ. فَأَرَادَ اللَّهُ عَزَّ وَجَلَّ أَنْ يَجْعَلَ ذَلِكَ يُسْرًا لِمَنْ بَقِيَ وَرُخْصَةً وَمَنْفَعَةً، فَقَالَ سُبْحَانَهُ: { عَلِمَ اللَّهُ أَنَّكُمْ كُنْتُمْ تَخْتَانُونَ أَنْفُسَكُمْ }. وَكَانَ هَذَا مِمَّا نَفَعَ اللَّهُ بِهِ النَّاسَ وَرَخَّصَ لَهُمْ وَيَسَّرَ."],"takhrij":"حسن: رواه أبو داود (2313) عن أحمد بن محمد بن شبَّويه، حدّثني علي بن حسين بن واقد، عن أبيه، عن يزيد النحوي، عن عكرمة، عن ابن عباس، فذكره.","grade":"حسن","chapter_ar":"باب وجوب صوم شهر رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (2313).","chapter_en":"The obligation of fasting the month of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿAbbas said regarding the verse: “O you who believe, fasting has been prescribed for you as it was prescribed for those before you” [Surah al-Baqarah: 183]: During the time of the Prophet ﷺ, if people had prayed the night prayer, food, drink, and women became forbidden to them, and they would continue fasting until the next night. Then a man betrayed himself and had relations with his wife after praying the night prayer and before breaking his fast. So Allah, Mighty and Majestic, willed to make that easier for those who remained, as a concession and a benefit, and He said: “Allah knew that you had been betraying yourselves.” [Surah al-Baqarah: 187] This was among the things by which Allah benefited the people, granted them concession, and made matters easy for them."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11959],"tks":"حسن: رواه أبو داود (2313)."},{"num":4298,"demo":false,"sanad":"","matn":["عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ، رَضِيَ اللَّهُ عَنْهُ قَالَ:  لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ: ﴿وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ﴾ كَانَ مَنْ أَرَادَ أَنْ يُفْطِرَ، وَيَفْتَدِيَ، حَتَّى نَزَلَتِ الْآيَةُ الَّتِي بَعْدَهَا، فَنَسَخَتْهَا.","وفي لفظ: كُنَّا فِي رَمَضَانَ عَلَى عَهْدِ رَسُولِ اللَّهِ صلى الله عليه وسلم مَنْ شَاءَ صَامَ، وَمَنْ شَاءَ أَفْطَرَ فَافْتَدَى بِطَعَامِ مِسْكِينٍ، حَتَّى أُنْزِلَتْ هَذِهِ الْآيَةُ ﴿فَمَنْ شَهِدَ مِنْكُمُ الشَّهْرَ فَلْيَصُمْهُ﴾ [البقرة: 185].185]."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4507)، ومسلم في الصيام (1145) من طريق قتيبة بن سعيد، حدّثنا بكر بن مضر، عن عمرو بن الحارث، عن بُكير بن عبدالله بن الأشجّ، عن يزيد مولى سلمة بن الأكوع، عن سلمة، فذكره. ولفظهما سواء، واللفظ الآخر لمسلم.","grade":"متفق عليه","chapter_ar":"باب نسخ قوله تعالى: (وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ)","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (4507) and Muslim (1145). The other wording is from Muslim.","chapter_en":"The abrogation of the verse: “And upon those who are able to fast, but with hardship, is a ransom: feeding a poor person.”","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ said: When this verse was revealed: “And upon those who are able to fast, but with hardship, is a ransom: feeding a poor person.” [Surah al-Baqarah: 184] whoever wished could break the fast and give the ransom, until the verse that came after it was revealed, and it abrogated it. In another wording: During Ramadan in the time of the Messenger of Allah ﷺ, whoever wished would fast, and whoever wished would break the fast and compensate by feeding a poor person, until this verse was revealed:","“So whoever among you witnesses the month, let him fast it.” [Surah al-Baqarah: 185]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4507)، ومسلم (1145)، واللفظ الآخر لمسلم."},{"num":4299,"demo":false,"sanad":"","matn":["عن عبدالله بن عمر قرأ: فِدْيَةٌ طَعَامُ مِسْكِينٍ [البقرة: 184] قال: هي منسوخة."],"takhrij":"صحيح: رواه البخاريّ في الصوم (1949) عن عيّاش، حدّثنا عبدالأعلى، حدّثنا عبيدالله، عن نافع، عن ابن عمر، فذكره.","grade":"صحيح","chapter_ar":"باب نسخ قوله تعالى: (وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ)","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (1949).","chapter_en":"The abrogation of the verse: “And upon those who are able to fast, but with hardship, is a ransom: feeding a poor person.”","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿUmar recited: “A ransom: feeding a poor person.” [Surah al-Baqarah: 184] and said: It is abrogated."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1949)."},{"num":4300,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ قَرَأَ: ﴿وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ﴾ [سورة البقرة: 184] قَالَ: لَيْسَتْ بِمَنْسُوخَةٍ، هُوَ الشَّيْخُ الْكَبِيرُ وَالْمَرْأَةُ الْكَبِيرَةُ لاَ يَسْتَطِيعَانِ أَنْ يَصُومَا، فلْيُطعما مَكَانَ كلِّ يَوْمٍ مِسْكِينًا."],"takhrij":"صحيح: رواه البخاريّ في التفسير (4505) عن إسحاق (هو ابن راهويه)، أخبرنا روح (هو ابن عُبادة)، حدّثنا زكريا بن إسحاق، حدّثنا عمرو ابن دينار، عن عطاء، سمع ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب من قال: هي في حق الكبير والمرضع والحامل وليست بمنسوخة","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (4505).","chapter_en":"Those who said: It applies to the elderly, the nursing mother, and the pregnant woman, and is not abrogated","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbas recited: “And upon those who are able to fast, but with hardship, is a ransom: feeding a poor person.” He said: It is not abrogated. It refers to the very old man and the very old woman who are unable to fast, so they should feed one poor person in place of each day."]},"intro":{"ar":["فهم من هذه الآيات والأحاديث أن الناس على خمسة أجناس:","١- المقيم الصحيح: كان مُخيَّرًا في البداية بين الصوم وبين الإطعام، إن شاء صام، وإن شاء أفطر وأطعم عن كلِّ يومٍ مسكينًا، ثم نُسخ فصار الصوم واجبًا عليه.","٢- المريض والمسافر: فهما لا يصومان، بل يفطران، ويقضيان عدة أيام أخر، وإن صاما أجزأهما.","٣- الشيخ الكبير والمرأة الكبيرة: اللذان لا يستطيعان الصوم، فعليهما الإطعام كلَّ يومٍ مسكينًا على رأي الجمهور.","وهو اختيار البخاري أيضًا، قال: “وأما الشيخ الكبير إذا لم يُطق الصيام فقد أطعم أنس بعد ما كبر عامًا أو عامين كل يوم مسكينًا خبزًا ولحمًا وأفطر.”","كتاب التفسير، باب قوله تعالى:","(أَيَّامًا مَعْدُودَاتٍ فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ فَمَنْ تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌ لَهُ وَأَنْ تَصُومُوا خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ) [البقرة: ١٨٤].","وقال مالك والشافعي في أحد قوليه: لا يجب عليهما إطعام لضعفهما عن الصوم، فهما كالصبي الذي لا تجب عليه الفدية، لأن الله لا يكلّف نفسًا إلا وسعها.","٤- الحامل والمرضع: إذا خافتا على نفسيهما، أو على أولادهما، أفطرتا وأطعمتا.","٥- الحائض والنفساء: عليهما الإفطار مع القضاء."],"en":["From these verses and hadiths, it is understood that people fall into five categories:","1. The resident who is healthy: at first, he was given a choice between fasting and feeding. If he wished, he fasted, and if he wished, he broke the fast and fed one poor person for each day. Then that ruling was abrogated, and fasting became obligatory for him.","2. The sick person and the traveler: they do not fast. Rather, they break the fast and make up the missed days later. If they do fast, it is valid for them.","3. The elderly man and the elderly woman: those who are unable to fast must feed one poor person for each day according to the view of the majority of scholars.","This was also the choice of al-Bukhari. He said: “As for the elderly person who is unable to fast, Anas, after he became old, fed one poor person each day with bread and meat for one or two years, and he did not fast.”","Book of Tafsir, chapter on the verse:","“A limited number of days. So whoever among you is ill or on a journey, then an equal number of other days. And upon those who are able to fast only with hardship is a ransom: feeding a poor person. And whoever volunteers extra good, it is better for him. But to fast is better for you, if only you knew.” [Al-Baqarah: 184]","Malik and al-Shafiʿi, in one of his opinions, said that feeding is not required from them because they are too weak to fast, so they are like a child upon whom no ransom is due, because Allah does not burden a soul beyond its ability.","4. The pregnant woman and the nursing mother: if they fear harm for themselves or for their children, they may break the fast and feed.","5. The menstruating woman and the woman in postnatal bleeding: they must break the fast and make up the missed days later."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (4505)."},{"num":4301,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّهُ قَالَ: رُخَّصَ لِلشَّيْخِ الْكَبِيرِ، وَالْعَجُوزِ الْكَبِيرَةِ فِي ذَلِكَ وَهُمَا يُطِيقَانِ الصَّوْمَ أَنْ يُفْطِرَا إِنْ شَاءَا، وَيُطْعِمَا مَكَانَ كُلِّ يَوْمٍ مِسْكِينًا، ثُمَّ نُسِخَ ذَلِكَ فِي هَذِهِ الْآيَةِ: ﴿فَمَنْ شَهِدَ مِنْكُمُ الشَّهْرَ فَلْيَصُمْهُ﴾ [البقرة: ١٨٥]، وَثَبِتَ لِلشَّيْخِ الْكَبِيرِ وَالْعَجُوزِ الْكَبِيرَةِ إِذَا كَانَا لَا يُطِيقَانِ الصَّوْمَ، وَالْحَامِلِ وَالْمُرْضِعِ إِذَا خَافَتَا أَفْطَرَتَا وَأَطْعَمَتَا مَكَانَ كُلِّ يَوْمٍ مِسْكِينًا."],"takhrij":"صحيح: رواه أبو داود (2318) عن ابن المثنى، حدّثنا ابن أبي عدي، عن سعيد، عن قتادة، عن عروة (كذا والصواب عزرة)، عن سعيد بن جبير، عن ابن عباس، فذكره مختصراً. ومن طريقه رواه البيهقيّ (8077) بتمامه.","grade":"صحيح","chapter_ar":"باب من قال: هي في حق الكبير والمرضع والحامل وليست بمنسوخة","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (2318).","chapter_en":"Those who said: It applies to the elderly, the nursing mother, and the pregnant woman, and is not abrogated","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbas said: Concession was given to the elderly man and the elderly woman in this matter, while they were still able to fast, that they could break the fast if they wished and feed one poor person in place of each day. Then that was abrogated by this verse: “So whoever among you witnesses the month, let him fast it.” [Surah al-Baqarah: 185] But the ruling remained for the very old man and the very old woman when they are no longer able to fast, and for the pregnant woman and the nursing woman if they fear harm: they may break the fast and feed one poor person for each day."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2318)."},{"num":4302,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِذَا دَخَلَ شَهْرُ رَمَضَانَ، فُتِّحَتْ أَبْوَابُ الرَّحْمَةِ، وَغُلِّقَتْ أَبْوَابُ جَهَنَّمَ، وَسُلْسِلَتِ الشَّيَاطِينُ."],"takhrij":"متفق عليه: رواه البخاريّ في الصوم (1899)، ومسلم في الصيام (1079) كلاهما من طريق ابن شهاب الزهري، أخبرني ابن أبي أنس مولى التّيميين، أنّ أباه حدّثه أنه سمع أبا هريرة يقول (فذكره).","grade":"متفق عليه","chapter_ar":"باب فضل شهر رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1899) and Muslim (1079).","chapter_en":"The virtue of the month of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “When the month of Ramadan begins, the gates of heaven are opened, the gates of Hell are closed, and the devils are chained.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10711],"tks":"متفق عليه: رواه البخاري (1899)، ومسلم (1079)."},{"num":4303,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا كَانَ أَوَّلُ لَيْلَةٍ مِنْ شَهْرِ رَمَضَانَ صُفِّدَتِ الشَّيَاطِينُ وَمَرَدَةُ الْجِنِّ، وَغُلِّقَتْ أَبْوَابُ النَّارِ، فَلَمْ يُفْتَحْ مِنْهَا بَابٌ. وَفُتِّحَتْ أَبْوَابُ الْجَنَّةِ فَلَمْ يُغْلَقْ مِنْهَا بَابٌ، وَيُنَادِي مُنَادٍ: يَا بَاغِيَ الْخَيْرِ أَقْبِلْ، وَيَا بَاغِيَ الشَّرِّ أَقْصِرْ. وَلِلَّهِ عُتَقَاءُ مِنَ النَّارِ، وَذَلِكَ كُلَّ لَيْلَةٍ."],"takhrij":"حسن: رواه الترمذيّ (682)، وابن ماجه (1642)، وصحّحه ابن خزيمة (1883)، وابن حبان (3435)، والحاكم (1532) كلّهم من حديث محمد بن العلاء بن كريب، حدّثنا أبو بكر بن عياش، عن الأعمش، عن أبي صالح، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب فضل شهر رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Tirmidhi (682), Ibn Majah (1642), and authenticated by Ibn Khuzaymah (1883) and Ibn Hibban (3435).","chapter_en":"The virtue of the month of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “When the first night of Ramadan comes, the devils and the rebellious jinn are chained, the gates of Hell are closed and none of them is opened, and the gates of Paradise are opened and none of them is closed. A caller calls out: O seeker of good, come forward; O seeker of evil, stop. And Allah frees people from the Fire, and that happens every night.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10712],"tks":"حسن: رواه الترمذي (682)، وابن ماجه (1642)، وصححه ابن خزيمة (1883)، وابن حبان (3435)."},{"num":4304,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَوْ عَنْ أَبِي سَعِيدٍ - هُوَ شَكَّ، يَعْنِي الْأَعْمَشَ -، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ لِلَّهِ عُتَقَاءَ فِي كُلِّ يَوْمٍ وَلَيْلَةٍ، لِكُلِّ عَبْدٍ مِنْهُمْ دَعْوَةٌ مُسْتَجَابَةٌ."],"takhrij":"صحيح: رواه الإمام أحمد (7450) عن أبي معاوية، حدثنا الأعمش، عن أبي صالح، عن أبي هريرة أو أبي سعيد، فذكره.","grade":"صحيح","chapter_ar":"باب فضل شهر رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (7450).","chapter_en":"The virtue of the month of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah or Abu Saʿid — al-Aʿmash was uncertain — said: The Messenger of Allah ﷺ said: “Allah frees people from the Fire every day and every night, and each one of them has a supplication that is answered.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (7450)."},{"num":4305,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ لِلَّهِ عِنْدَ كُلِّ فِطْرٍ عُتَقَاءَ."],"takhrij":"حسن: رواه الإمام أحمد (22202)، والطبراني في الكبير (8089)، والبيهقي في شعب الإيمان (3605) كلّهم من حديث عبدالله بن نمير، حدّثنا الأعمش، عن حسين الخراسانيّ، عن أبي غالب، عن أبي أمامة، فذكره.","grade":"حسن","chapter_ar":"باب فضل شهر رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (22202), al-Tabarani in al-Kabir (8/340), and al-Bayhaqi in Shuʿab al-Iman (3605).","chapter_en":"The virtue of the month of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Abu Umamah al-Bahili reported that the Prophet ﷺ said: “Allah has people whom He frees from the Fire at every breaking of the fast.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (22202)، والطبراني في الكبير (8089)، والبيهقي في شعب الإيمان (3605)."},{"num":4306,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ لِلَّهِ عِنْدَ كُلِّ فِطْرٍ عُتَقَاءَ، وَذَلِكَ فِي كُلِّ لَيْلَةٍ."],"takhrij":"حسن: رواه ابن ماجه (1643) عن أبي كريب، قال: حدثنا أبو بكر بن عياش، عن الأعمش، عن أبي سفيان، عن جابر، فذكره.","grade":"حسن","chapter_ar":"باب فضل شهر رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ibn Majah (1643).","chapter_en":"The virtue of the month of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said: “Allah frees people from the Fire at every breaking of the fast, and that is every night.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (1643)."},{"num":4307,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: دَخَلَ رَمَضَانُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ هَذَا الشَّهْرَ قَدْ حَضَرَكُمْ، وَفِيهِ لَيْلَةٌ خَيْرٌ مِنْ أَلْفِ شَهْرٍ، مَنْ حُرِمَهَا فَقَدْ حُرِمَ الْخَيْرَ كُلَّهُ، وَلاَ يُحْرَمُ خَيْرَهَا إِلاَّ مَحْرُومٌ."],"takhrij":"حسن: رواه ابن ماجه (1644) عن أبي بدر عباد بن الوليد، حدثنا محمد بن بلال، قال: حدثنا عمران القطان، عن قتادة، عن أنس بن مالك، فذكره.","grade":"حسن","chapter_ar":"باب فضل شهر رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ibn Majah (1644).","chapter_en":"The virtue of the month of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Anas said: Ramadan entered, and the Messenger of Allah ﷺ said: “This month has come to you, and in it is a night better than a thousand months. Whoever is deprived of it has been deprived of all good, and none is deprived of its good except one who is truly deprived.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10753],"tks":"حسن: رواه ابن ماجه (1644)."},{"num":4308,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ من أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ،قَالَ: فِي رَمَضَانَ تُفَتَّحُ أَبْوَابُ السَّمَاءِ، وَتُغَلَّقُ أَبْوَابُ النَّارِ، ويُصفَّد فِيهِ كلّ شَيْطَانٍ مَرِيدٍ، وَيُنَادِي مُنَادٍ كلّ لَيْلَةٍ: يَا طَالِبَ الْخَيْرِ هلّمَّ، وَيَا طَالِبَ الشَّرِّ أَمْسِكْ ."],"takhrij":"حسن: رواه النسائيّ (2108)، وأحمد (18794) كلاهما من حديث محمد بن جعفر، حدثنا شعبة، عن عطاء بن السائب، عن عرفجة، قال: كنت في بيت فيه عتبة بن فرقد، فأردتُ أن أحدّث بحديث قال: فكان رجل من أصحاب رسول الله صلى الله عليه وسلم كأنه أولى بالحديث منه. قال: فحدَّث الرجل عن رسول الله صلى الله عليه وسلم أنه قال (فذكر الحديث).","grade":"حسن","chapter_ar":"باب فضل شهر رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Nasa’i (2108) and Ahmad (18794).","chapter_en":"The virtue of the month of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["A man from among the Companions of the Prophet ﷺ reported that the Prophet ﷺ said: “In Ramadan, the gates of heaven are opened, the gates of Hell are closed, every rebellious devil is chained, and a caller calls out every night: O seeker of good, come; O seeker of evil, stop.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10713],"tks":"حسن: رواه النسائي (2108)، وأحمد (18794)."},{"num":4309,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ صَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا، غُفر لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ، وَمَنْ قَامَ لَيْلَةَ الْقَدْرِ إِيمَانًا وَاحْتِسَابًا غُفر لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ."],"takhrij":"متفق عليه: رواه البخاريّ في الصّوم (1901)، ومسلم في صلاة المسافرين (760) كلاهما من طريق هشام الدّستوائيّ، حدّثنا يحيى بن أبي كثير، حدّثنا أبو سلمة بن عبدالرحمن، أنّ أبا هريرة حدّثهم به، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في فضل صيام شهر رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1901) and Muslim (760).","chapter_en":"What has come regarding the virtue of fasting the month of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “Whoever fasts Ramadan with faith and seeking reward will have his previous sins forgiven. And whoever stands in prayer on the Night of Decree with faith and seeking reward will have his previous sins forgiven.”"]}},"tuhfa":{},"full":1,"rep":[4650,10714],"tks":"متفق عليه: رواه البخاري (1901)، ومسلم (760)."},{"num":4310,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ صَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ.","قال عبد الله بن أحمد: قَالَ أَبِي: سَمِعْتُهُ أَرْبَعَ مَرَّاتٍ مِنْ سُفْيَانَ، وَقَالَ مَرَّةً: مَنْ صَامَ رَمَضَانَ ، وَقَالَ مَرَّةً: مَنْ قَامَ ، وَمَنْ قَامَ لَيْلَةَ الْقَدْرِ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ."],"takhrij":"صحيح: رواه الإمام أحمد (7280) عن سفيان (هو ابن عيينة)، عن الزهري، عن أبي سلمة، عن أبي هريرة، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في فضل صيام شهر رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (7280).","chapter_en":"What has come regarding the virtue of fasting the month of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah reported from the Prophet ﷺ: “Whoever fasts Ramadan with faith and seeking reward will have his previous sins forgiven.”"]},"buhuth":{"en":["In al-Sunan al-Kubra of al-Nasa’i (2523), there is an added wording: “and his later sins as well,” but that addition is irregular and unreliable."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (7280)."},{"num":4311,"demo":false,"sanad":"","matn":["عن عَمْرِو بْنِ مرّة الجهنيّ، قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ إِنْ شَهِدْتُ أَنْ لَا إِلَهَ إِلَاّ اللَّهُ، وَأَنَّكَ رَسُولُ اللَّهِ، وَصَلَّيْتُ الصَّلَوَاتِ الْخَمْسَ، وَأَدَّيْتُ الزَّكَاةَ، وَصُمْتُ رَمَضَانَ، وَقُمْتُهُ، فَمِمَّنْ أَنَا؟ قَالَ: مِنَ الصِّدِّيقِينَ وَالشُّهَدَاءِ."],"takhrij":"صحيح: رواه ابن خزيمة (2212)، وابن حبان (3438) كلاهما من حديث الحكم بن نافع، عن شعيب بن أبي حمزة، عن عبدالله بن عبدالرحمن ابن أبي حسين، عن عيسى بن طلحة، قال: سمعت عمرو بن مرة الجهنيّ، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في فضل صيام شهر رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Khuzaymah (2212) and Ibn Hibban (3438).","chapter_en":"What has come regarding the virtue of fasting the month of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["ʿAmr ibn Murrah al-Juhani said: A man came to the Prophet ﷺ and said: “O Messenger of Allah, if I testify that there is no god but Allah and that you are the Messenger of Allah, perform the five prayers, give zakah, fast Ramadan, and stand in prayer during it, then among whom will I be?” He said: “Among the truthful and the martyrs.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10715],"tks":"صحيح: رواه ابن خزيمة (2212)، وابن حبان (3438)."},{"num":4312,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يَقُولَنَّ أَحَدُكُمْ: إِنِّي صُمْتُ رَمَضَانَ كُلَّهُ وَ قُمْتُهُ كُلَّهُ. فَلاَ أَدْرِي أَكَرِهَ التَّزْكِيَةَ، أَوْ قَالَ: لاَ بُدَّ مِنْ نَوْمَةٍ أَوْ رَقْدَةٍ."],"takhrij":"حسن: رواه أبو داود (2415)، والنسائيّ (2109)، وأحمد (20406)، وصحّحه ابن خزيمة (2075)، وابن حبان (3439) كلّهم من حديث يحيى بن سعيد، قال: حدّثنا المهلّب بن أبي حبيبة، قال: حدّثنا الحسن، عن أبي بكرة، فذكره.","grade":"حسن","chapter_ar":"باب الزجر عن قول المرء صمت رمضان كله، وقمت رمضان كله","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (2415), al-Nasa’i (2109), and Ahmad (20406), and authenticated by Ibn Khuzaymah (2075).","chapter_en":"A warning against saying: I fasted all of Ramadan, and I stood all of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Abu Bakrah reported that the Prophet ﷺ said: “None of you should say: I fasted all of Ramadan and I stood all of Ramadan.” The narrator said: I do not know whether he disliked self-praise, or whether he said: “There must have been some sleep or rest.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2415)، والنسائي (2109)، وأحمد (20406)، وصححه ابن خزيمة (2075)."},{"num":4313,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ، رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَجْوَدَ النَّاسِ بِالْخَيْرِ، وَكَانَ أَجْوَدُ مَا يَكُونُ فِي رَمَضَانَ، حِينَ يَلْقَاهُ جِبْرِيلُ، وَكَانَ جِبْرِيلُ ـ عَلَيْهِ السَّلاَمُ ـ يَلْقَاهُ كُلَّ لَيْلَةٍ فِي رَمَضَانَ حَتَّى يَنْسَلِخَ، يَعْرِضُ عَلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْقُرْآنَ، فَإِذَا لَقِيَهُ جِبْرِيلُ ـ عَلَيْهِ السَّلاَمُ ـ كَانَ أَجْوَدَ بِالْخَيْرِ مِنَ الرِّيحِ الْمُرْسَلَةِ."],"takhrij":"متفق عليه: رواه البخاريّ في الصوم (1902)، ومسلم في الفضائل (2308) من طريق إبراهيم بن سعد، أخبرنا ابن شهاب، عن عبيدالله بن عبدالله بن عتبة بن مسعود، عن ابن عباس، فذكره.","grade":"متفق عليه","chapter_ar":"باب قراءة القرآن ومدارسته في شهر رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1902) and Muslim (2308).","chapter_en":"Reciting the Quran and reviewing it in the month of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbas said: The Prophet ﷺ was the most generous of people in doing good, and he was at his most generous in Ramadan when Jibril met him. Jibril, peace be upon him, used to meet him every night in Ramadan until the month ended, and the Prophet ﷺ would review the Quran with him. When Jibril met him, he was more generous in goodness than the sent wind."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1902)، ومسلم (2308)."},{"num":4314,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ، أنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَكَرَ رَمَضَانَ، فَقَالَ: لاَ تَصُومُوا حَتَّى تَرَوُا الْهِلاَلَ، وَلاَ تُفْطِرُوا حَتَّى تَرَوْهُ، فَإِنْ غمَّ عَلَيْكُمْ فَاقْدُرُوا لَهُ ."],"takhrij":"متفق عليه: رواه مالك في الصيام (1) عن نافع، عن عبدالله بن عمر، فذكره. ورواه البخاري في الصوم (1906)، ومسلم في الصيام (1080) كلاهما من طريق مالك، به.","grade":"متفق عليه","chapter_ar":"باب وجوب الصوم لرؤية الهلال والفطر لرؤيته فإن غم أكملت عدة الشهر ثلاثين يومًا","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (1), al-Bukhari (1906), and Muslim (1080).","chapter_en":"The obligation of fasting upon seeing the crescent, and breaking the fast upon seeing it; if it is obscured, the month is completed as thirty days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar reported that the Messenger of Allah ﷺ mentioned Ramadan and said: “Do not fast until you see the crescent, and do not break the fast until you see it. If it is obscured from you, then determine it accordingly.”"]}},"tuhfa":{},"full":1,"rep":[11954],"tks":"متفق عليه: رواه مالك (1)، والبخاري (1906)، ومسلم (1080)."},{"num":4315,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ، أنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الشَّهْرُ تسعٌ وَعِشْرُونَ، فَلاَ تَصُومُوا حَتَّى تَرَوُا الْهِلاَلَ، وَلاَ تُفْطِرُوا حَتَّى تَرَوْهُ، فإنْ غُمَّ عَلَيْكُمْ فَاقْدُرُوا لَهُ ."],"takhrij":"متفق عليه: رواه مالك في الصيام (2) عن عبدالله بن دينار، عن عبدالله ابن عمر، فذكره. ورواه البخاريّ في الصوم (1907) عن عبدالله بن مسلمة (هو القعنبي)، حدّثنا مالك، به، مثله إلاّ أنه قال في آخره: فإن غُمَّ عليكم فأكملوا العِدَّة ثلاثين .","grade":"متفق عليه","chapter_ar":"باب وجوب الصوم لرؤية الهلال والفطر لرؤيته فإن غم أكملت عدة الشهر ثلاثين يومًا","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (2), al-Bukhari (1907), and Muslim (1080 no. 9).","chapter_en":"The obligation of fasting upon seeing the crescent, and breaking the fast upon seeing it; if it is obscured, the month is completed as thirty days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar reported that the Messenger of Allah ﷺ said: “The month is twenty-nine days, so do not fast until you see the crescent, and do not break the fast until you see it. If it is obscured from you, then determine it accordingly.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (2)، والبخاري (1907)، ومسلم (1080/9)."},{"num":4316,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الشَّهْرُ تِسْعٌ وَعِشْرُونَ فَلاَ تَصُومُوا حَتَّى تَرَوْهُ، وَلاَ تُفْطِرُوا حَتَّى تَرَوْهُ، فَإِنْ غُمَّ عَلَيْكُمْ فَاقْدُرُوا لَهُ ثَلاَثِينَ.","قَالَ: فَكَانَ ابْنُ عُمَرَ إِذَا كَانَ شَعْبَانُ تِسْعًا وَعِشْرِينَ نُظِرَ لَهُ، فَإِنْ رُؤِيَ فَذَاكَ، وَإِنْ لَمْ يُرَ وَلَمْ يَحُلْ دُونَ نظره سَحَابٌ وَلاَ قَتَرَةٌ أَصْبَحَ مُفْطِرًا، فَإِنْ حَالَ دُونَ مَنْظَرِهِ سَحَابٌ أَوْ قَتَرَةٌ أَصْبَحَ صَائِمًا.","قَالَ: فَكَانَ ابْنُ عُمَرَ يُفْطِرُ مَعَ النَّاسِ، وَلاَ يَأْخُذُ بِهَذَا الْحِسَابِ."],"takhrij":"صحيح: رواه أبو داود (2320) عن داود بن سليمان العتكيّ، حدّثنا حماد، حدّثنا أيوب، عن نافع، عن ابن عمر، فذكره.","grade":"صحيح","chapter_ar":"باب وجوب الصوم لرؤية الهلال والفطر لرؤيته فإن غم أكملت عدة الشهر ثلاثين يومًا","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (2320).","chapter_en":"The obligation of fasting upon seeing the crescent, and breaking the fast upon seeing it; if it is obscured, the month is completed as thirty days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said: “The month is twenty-nine days, so do not fast until you see it, and do not break the fast until you see it. If it is obscured from you, then count thirty for it.” He said: Ibn ʿUmar, when Shaʿban had reached twenty-nine days, would look for the crescent. If it was seen, then that was it. If it was not seen, and there was neither cloud nor dust blocking his view, he would begin the morning not fasting. But if cloud or dust blocked his view, he would begin the morning fasting.","He said: Ibn ʿUmar used to break the fast with the people and did not follow this calculation."]},"buhuth":{"en":["And qatarah means dust or haze in the air that blocks vision from seeing the crescent."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2320). والقترة: الغبرة في الهواء الحائلة بين الأبصار وبين رؤية الهلال."},{"num":4317,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ، فَإِنْ غُمِّي عَلَيْكُمُ الشَّهْرُ فعدُّوا ثَلَاثِينَ ."],"takhrij":"متفق عليه: رواه البخاريّ في الصوم (1909)، ومسلم في الصيام (1081: 19) كلاهما من طريق شعبة، حدّثنا محمد بن زياد، قال: سمعت أبا هريرة يقول (فذكره) واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب وجوب الصوم لرؤية الهلال والفطر لرؤيته فإن غم أكملت عدة الشهر ثلاثين يومًا","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1909) and Muslim (1081 no. 19). This is the wording of Muslim.","chapter_en":"The obligation of fasting upon seeing the crescent, and breaking the fast upon seeing it; if it is obscured, the month is completed as thirty days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Fast upon seeing it, and break the fast upon seeing it. If the month is obscured from you, then count thirty.”"]},"buhuth":{"en":["The wording in al-Bukhari is: “…if it is obscured from you, then complete the number of Shaʿban as thirty.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11955],"tks":"متفق عليه: رواه البخاري (1909)، ومسلم (1081: 19) واللفظ لمسلم."},{"num":4318,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا رَأَيْتُمُ الْهِلَالَ، فَصُومُوا، وَإِذَا رَأَيْتُمُوهُ، فَأَفْطِرُوا، فَإِنْ غُمَّ عَلَيْكُمْ، فَصُومُوا ثَلَاثِينَ يَوْمًا."],"takhrij":"صحيح: رواه الإمام أحمد (7516)، وصحّحه ابن خزيمة (1908)، وابن حبان (3443) كلّهم من حديث الزهريّ، عن أبي سلمة بن عبدالرحمن، عن أبي هريرة، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب وجوب الصوم لرؤية الهلال والفطر لرؤيته فإن غم أكملت عدة الشهر ثلاثين يومًا","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (7516), and authenticated by Ibn Khuzaymah (1908) and Ibn Hibban (3443).","chapter_en":"The obligation of fasting upon seeing the crescent, and breaking the fast upon seeing it; if it is obscured, the month is completed as thirty days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “When you see the crescent, then fast, and when you see it, then break the fast. If it is obscured from you, then fast thirty days.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه الإمام أحمد (7516)، وصححه ابن خزيمة (1908)، وابن حبان (3443)."},{"num":4319,"demo":false,"sanad":"","matn":["عَنْ أَبِي البَخْتَريّ، قَالَ: خَرَجْنَا لِلْعُمْرَةِ، فَلَمَّا نَزَلْنَا بِبَطْنِ نَخْلَةَ قَالَ: تَرَاءَيْنَا الْهِلَالَ، فَقَالَ بعضُ الْقَوْمِ: هُوَ ابْنُ لَيْلَتَيْنِ. قَالَ: فَلَقِينَا ابنَ عَبَّاسٍ، فَقُلْنَا: إنّا رَأَيْنَا الْهِلَالَ، فَقَالَ بعضُ الْقَوْمِ: هُوَ ابْنُ ثَلَاثٍ، وَقَالَ بعضُ الْقَوْمِ: هُوَ ابْنُ لَيْلَتَيْنِ. فَقَالَ: أيُّ لَيْلَةٍ رَأَيْتُمُوهُ؟ قَالَ: فَقُلْنَا: لَيْلَةَ كَذَا وَكَذَا. فَقَالَ: إنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إنّ اللَّهَ مدَّه لِلرُّؤْيَةِ، فَهُوَ لِلَيْلَةِ رَأَيْتُمُوهُ ."],"takhrij":"صحيح: رواه مسلم في الصيام (1088) من طريق حصين، عن عمرو ابن مُرّة، عن أبي البختريّ (هو سعيد بن فيروز)، به، فذكره.","grade":"صحيح","chapter_ar":"باب وجوب الصوم لرؤية الهلال والفطر لرؤيته فإن غم أكملت عدة الشهر ثلاثين يومًا","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1088).","chapter_en":"The obligation of fasting upon seeing the crescent, and breaking the fast upon seeing it; if it is obscured, the month is completed as thirty days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abu al-Bakhtari said: We went out for ʿUmrah, and when we stopped at the valley of Nakhlah, we looked for the crescent. Some of the people said, “It is three nights old,” and some said, “It is two nights old.” Then we met Ibn ʿAbbas and said: “We saw the crescent.” Some of the people said, “It is three nights old,” and some said, “It is two nights old.” He said: “On which night did you see it?” We said: “On such-and-such night.” He said: The Messenger of Allah ﷺ said: “Allah has extended it for visibility, so it belongs to the night on which you saw it.”"]},"buhuth":{"en":["He also narrated it with the wording: “Allah has indeed extended it for visibility, so if it is obscured from you, then complete the number.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1088)."},{"num":4320,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ تُقَدِّمُوا الشَّهْرَ بِصِيَامِ يَوْمٍ وَلاَ يَوْمَيْنِ، إِلاَّ أَنْ يَكُونَ شَىْءٌ يَصُومُهُ أَحَدُكُمْ، وَلاَ تَصُومُوا حَتَّى تَرَوْهُ، ثُمَّ صُومُوا حَتَّى تَرَوْهُ، فَإِنْ حَالَ دُونَهُ غَمَامَةٌ، فَأَتِمُّوا الْعِدَّةَ ثَلاَثِينَ، ثُمَّ أَفْطِرُوا. وَ الشَّهْرُ تِسْعٌ وَعِشْرُونَ."],"takhrij":"صحيح: رواه أبو داود (2327)، والترمذي (688)، والنسائي (2129، 2130) كلهم من طرق عن سماك بن حرب، عن عكرمة، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب وجوب الصوم لرؤية الهلال والفطر لرؤيته فإن غم أكملت عدة الشهر ثلاثين يومًا","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (2327), al-Tirmidhi (688), and al-Nasa’i (2129, 2130). Al-Tirmidhi said: Hasan Sahih.","chapter_en":"The obligation of fasting upon seeing the crescent, and breaking the fast upon seeing it; if it is obscured, the month is completed as thirty days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ said: “Do not precede the month by fasting one day or two days, unless it is something that one of you normally fasts. And do not fast until you see it. Then continue fasting until you see it. If a cloud comes between you and it, then complete the number as thirty, then break the fast. And the month is twenty-nine days.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2327)، والترمذي (688)، والنسائي (2130، 2129). وقال الترمذي: حسن صحيح."},{"num":4321,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: عَجِبْتُ مِمَّنْ يَتَقَدَّمُ الشَّهْرَ! وَقَدْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا رَأَيْتُمُ الْهِلاَلَ فَصُومُوا، وَإِذَا رَأَيْتُمُوهُ فَأَفْطِرُوا. فَإِنْ غُمَّ عَلَيْكُمْ فَأَكْمِلُوا الْعِدَّةَ ثَلاَثِينَ."],"takhrij":"صحيح: رواه النسائي (2125)، والإمام أحمد (3474)، والدارميّ (1728) كلّهم من حديث عمرو بن دينار، عن محمد بن جبير، عن ابن عباس، فذكره واللفظ للنسائي.","grade":"صحيح","chapter_ar":"باب وجوب الصوم لرؤية الهلال والفطر لرؤيته فإن غم أكملت عدة الشهر ثلاثين يومًا","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasa’i (2125), Ahmad (3474), and al-Darimi (1728). This is the wording of al-Nasa’i.","chapter_en":"The obligation of fasting upon seeing the crescent, and breaking the fast upon seeing it; if it is obscured, the month is completed as thirty days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Ibn ʿAbbas said: I am amazed at those who begin the month early, when the Messenger of Allah ﷺ said: “When you see the crescent, then fast, and when you see it, then break the fast. If it is obscured from you, then complete the number as thirty.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (2125)، والإمام أحمد (3474)، والدارمي (1728)، واللفظ للنسائي."},{"num":4322,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ تُقَدِّمُوا الشَّهْرَ حَتَّى تَرَوُا الْهِلاَلَ، أَوْ تُكْمِلُوا الْعِدَّةَ، ثُمَّ صُومُوا حَتَّى تَرَوُا الْهِلاَلَ أَوْ تُكْمِلُوا الْعِدَّةَ."],"takhrij":"صحيح: رواه أبو داود (2326)، والنسائي (2126)، وابن خزيمة (1911)، وابن حبان (3458)، والدارقطني (2166)، والإمام أحمد (18825) كلّهم من طريق جرير بن عبد الحميد الضبيّ، عن منصور، عن ربعي بن حراش، عن حذيفة، فذكره.","grade":"صحيح","chapter_ar":"باب وجوب الصوم لرؤية الهلال والفطر لرؤيته فإن غم أكملت عدة الشهر ثلاثين يومًا","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (2326), al-Nasa’i (2126), Ibn Khuzaymah (1911), and Ibn Hibban (3458).","chapter_en":"The obligation of fasting upon seeing the crescent, and breaking the fast upon seeing it; if it is obscured, the month is completed as thirty days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Hudhayfah said: The Messenger of Allah ﷺ said: “Do not begin the month early until you see the crescent, or complete the number. Then fast until you see the crescent, or complete the number.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2326)، والنسائي (2126)، وابن خزيمة (1911)، وابن حبان (3458)."},{"num":4323,"demo":false,"sanad":"","matn":["عن جابر بْنِ عبدالله، يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا رَأَيْتُمُ الْهِلَالَ فَصُومُوا، وَإِذَا رَأَيْتُمُوهُ فَأَفْطِرُوا، فَإِنْ أُغْمِيَ عَلَيْكُمْ، فَعُدُّوا ثَلَاثِينَ يَوْمًا."],"takhrij":"صحيح: رواه الإمام أحمد (14526)، وأبو يعلى (2248)، والبيهقي (7937) كلّهم من طريق روح بن عبادة، حدّثنا زكريا، حدّثنا أبو الزبير، أنه سمع جابر بن عبدالله، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب وجوب الصوم لرؤية الهلال والفطر لرؤيته فإن غم أكملت عدة الشهر ثلاثين يومًا","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (14526), Abu Yaʿla (2248), and al-Bayhaqi (4/206).","chapter_en":"The obligation of fasting upon seeing the crescent, and breaking the fast upon seeing it; if it is obscured, the month is completed as thirty days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: The Messenger of Allah ﷺ said: “When you see the crescent, then fast, and when you see it, then break the fast. If it is obscured from you, then count thirty days.”"]},"buhuth":{"en":["Ahmad also narrated it through another chain (14670) with the wording:","“Do not fast until you see the crescent. If it is hidden from you, then complete thirty.”","And Jabir said: The Messenger of Allah ﷺ stayed away from his wives for a month, then came down after twenty-nine days and said:","“The month is only twenty-nine days.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (14526)، وأبو يعلى (2248)، والبيهقي (7937)."},{"num":4324,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَحَفَّظُ مِنْ هلال شَعْبَانَ مَا لاَ يَتَحَفَّظُ مِنْ غَيْرِهِ، ثُمَّ يَصُومُ لِرُؤْيَةِ رَمَضَانَ، فَإِنْ غُمَّ عَلَيْهِ، عدَّ ثَلاَثِينَ يَوْمًا ثُمَّ صَامَ."],"takhrij":"صحيح: رواه أبو داود (2325)، والإمام أحمد (25161)، والدّارقطني (2149)، وصحّحه ابن خزيمة (1910)، وابن حبان (3444)، والحاكم (1540) وعنه البيهقيّ. كلّهم من طريق معاوية بن صالح الحضرميّ، عن عبدالله بن أبي قيس، قال: سمعت عائشة تقول (فذكرته).","grade":"صحيح","chapter_ar":"باب وجوب الصوم لرؤية الهلال والفطر لرؤيته فإن غم أكملت عدة الشهر ثلاثين يومًا","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (2325), Ahmad (25161), and al-Daraqutni (2149), and authenticated by Ibn Khuzaymah (1910).","chapter_en":"The obligation of fasting upon seeing the crescent, and breaking the fast upon seeing it; if it is obscured, the month is completed as thirty days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ was more careful in observing the crescent of Shaʿban than he was with any other crescent. Then he would fast upon seeing Ramadan. If it was obscured from him, he would count thirty days and then fast."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2325)، والإمام أحمد (25161)، والدارقطني (2149)، وصححه ابن خزيمة (1910)."},{"num":4325,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكَرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: صُومُوا الْهِلَالَ لِرُؤْيَتِهِ، وَأَفْطِرُوا لِرُؤْيَتِهِ، فَإِنْ غُمَّ عَلَيْكُمْ، فَأَكْمِلُوا الْعِدَّةَ ثَلَاثِينَ، وَالشَّهْرُ هَكَذَا وَهَكَذَا وَهَكَذَا وَعَقَدَ."],"takhrij":"حسن: رواه الإمام أحمد (20432)، والبزار ـ كشف الأستار (970)، وأبو داود الطيالسيّ (914) وعنه البيهقيّ (7938) كلّهم من حديث عمران القطان، عن قتادة، عن الحسن، عن أبي بكرة، فذكره.","grade":"حسن","chapter_ar":"باب وجوب الصوم لرؤية الهلال والفطر لرؤيته فإن غم أكملت عدة الشهر ثلاثين يومًا","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (20432), al-Bazzar in Kashf al-Astar (970), and Abu Dawud al-Tayalisi (914).","chapter_en":"The obligation of fasting upon seeing the crescent, and breaking the fast upon seeing it; if it is obscured, the month is completed as thirty days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abu Bakrah reported that the Prophet ﷺ said: “Fast when you see the crescent, and break the fast when you see it. If it is obscured from you, then complete the number as thirty. And the month is like this, and this, and this,” and he gestured with his fingers."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (20432)، والبزار في كشف الأستار (970)، وأبو داود الطيالسي (914)."},{"num":4326,"demo":false,"sanad":"","matn":["عن أمِّ سَلَمَةَ، أَخْبَرَتْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَلَفَ لاَ يَدْخُلُ عَلَى بَعْضِ أَهْلِهِ شَهْرًا، فَلَمَّا مَضَى تِسْعَةٌ وَعِشْرُونَ يَوْمًا غَدَا عَلَيْهِنَّ أَوْ رَاحَ، فَقِيلَ لَهُ: يَا نَبِيَّ اللَّهِ، حَلَفْتَ أَنْ لاَ تَدْخُلَ عَلَيْهِنَّ شَهْرًا؟ قَالَ: إِنَّ الشَّهْرَ يَكُونُ تِسْعَةً وَعِشْرِينَ يَوْمًا."],"takhrij":"متفق عليه: رواه البخاريّ في النكاح (5202)، ومسلم في الصيام (1085) كلاهما من طريق ابن جريج، أخبرني يحيى بن عبدالله بن صيفي، أنّ عكرمة بن عبدالرحمن بن الحارث، أخبره، أنّ أمَّ سلمة أخبرته، ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب الشهر يكون تسعًا وعشرين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (5202) and Muslim (1085).","chapter_en":"The month may be twenty-nine days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Umm Salamah reported that the Prophet ﷺ swore that he would not enter upon some of his wives for a month. When twenty-nine days had passed, he went to them in the morning or evening. It was said to him, “O Prophet of Allah, you swore that you would not enter upon them for a month.” He said: “The month may be twenty-nine days.”"]}},"tuhfa":{},"full":1,"rep":[6314,6645],"tks":"متفق عليه: رواه البخاري (5202)، ومسلم (1085)."},{"num":4327,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: آلَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ نِسَائِهِ، وَكَانَتِ انْفَكَّتْ رِجْلُهُ، فَأَقَامَ فِي مَشْرُبَةٍ تِسْعًا وَعِشْرِينَ لَيْلَةً، ثُمَّ نَزَلَ. فَقَالُوا: يَا رَسُولَ اللَّهِ، آلَيْتَ شَهْرًا. فَقَالَ: إِنَّ الشَّهْرَ يَكُونُ تِسْعًا وَعِشْرِينَ."],"takhrij":"صحيح: رواه البخاريّ في الصوم (1911) عن عبد العزيز بن عبدالله، حدثنا سليمان بن بلال، عن حميد (هو الطويل)، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب الشهر يكون تسعًا وعشرين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (1911).","chapter_en":"The month may be twenty-nine days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ kept away from his wives by oath, and his leg had been injured, so he stayed in an upper room for twenty-nine nights, then came down. They said, “O Messenger of Allah, you had sworn to stay away for a month.” He said: “The month may be twenty-nine days.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1911)."},{"num":4328,"demo":false,"sanad":"","matn":["عن عبدالله بن عُمَرَ، عن النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: إِنَّا أُمَّةٌ أُمِّيَّةٌ، لاَ نَكْتُبُ وَلاَ نَحْسُبُ، الشَّهْرُ هَكَذَا وَهَكَذَا. يَعْنِي مَرَّةً تِسْعَةً وَعِشْرِينَ، وَمَرَّةً ثَلاَثِينَ."],"takhrij":"متفق عليه: رواه البخاريّ في الصوم (1913)، ومسلم في الصيام (1080: 15) كلاهما من طريق شعبة، حدّثنا الأسود بن قيس، قال: سمعت سعيد بن عمرو بن سعيد، أنه سمع ابن عمر، فذكره. واللفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب الشهر يكون تسعًا وعشرين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1913) and Muslim (1080 no. 15). This is the wording of al-Bukhari.","chapter_en":"The month may be twenty-nine days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar reported that the Prophet ﷺ said: “We are an unlettered nation. We neither write nor calculate. The month is like this and this,” meaning that sometimes it is twenty-nine days and sometimes thirty."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1913)، ومسلم (1080: 15)، واللفظ للبخاري."},{"num":4329,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ قَالَ: أَصْبَحْنَا يَوْمًا وَنِسَاءُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَبْكِينَ، عِنْدَ كُلِّ امْرَأَةٍ مِنْهُنَّ أَهْلُهَا، فَخَرَجْتُ إِلَى الْمَسْجِدِ، فَإِذَا هُوَ مَلآنُ مِنَ النَّاسِ، فَجَاءَ عُمَرُ بْنُ الْخَطَّابِ فَصَعِدَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهْوَ فِي غُرْفَةٍ لَهُ، فَسَلَّمَ فَلَمْ يُجِبْهُ أَحَدٌ، ثُمَّ سَلَّمَ فَلَمْ يُجِبْهُ أَحَدٌ، ثُمَّ سَلَّمَ فَلَمْ يُجِبْهُ أَحَدٌ، فَنَادَاهُ، فَدَخَلَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَطَلَّقْتَ نِسَاءَكَ؟ فَقَالَ: لاَ؛ وَلَكِنْ آلَيْتُ مِنْهُنَّ شَهْرًا. فَمَكَثَ تِسْعًا وَعِشْرِينَ، ثُمَّ دَخَلَ عَلَى نِسَائِهِ."],"takhrij":"صحيح: رواه البخاريّ في النّكاح (5203) عن علي بن عبدالله (هو ابن المديني)، حدّثنا مروان بن معاوية، حدّثنا أبو يعفور، قال: تذاكرنا عند أبي الضُّحى، فقال: حدّثنا ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب الشهر يكون تسعًا وعشرين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (5203).","chapter_en":"The month may be twenty-nine days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿAbbas said: One day we awoke and the wives of the Prophet ﷺ were weeping, with each woman having her family beside her. I went out to the mosque and found it full of people. Then ʿUmar ibn al-Khattab came and went up to the Prophet ﷺ in an upper room of his. He gave salam, but no one answered him. Then he gave salam again, but no one answered him. Then he gave salam a third time, but no one answered him. Then he called out, and he was allowed to enter upon the Prophet ﷺ. He said: “Have you divorced your wives?” He said: “No, but I have kept away from them by oath for a month.” So he remained away for twenty-nine days, then entered upon his wives."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (5203)."},{"num":4330,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ الْخَطَّابِ، قَالَ: لَمَّا اعْتَزَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نِسَاءَهُ، قُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّمَا كُنْتَ فِي الْغُرْفَةِ تِسْعًا وَعِشْرِينَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الشَّهْرَ يَكُونُ تِسْعًا وَعِشْرِينَ."],"takhrij":"صحيح: رواه ابن خزيمة (1921)، وابن حبان (3453) كلاهما من حديث عمر بن يونس، ثنا عكرمة بن عمار، حدثني سماك أبو زميل، حدثني عبدالله بن عباس، حدثني عمر بن الخطاب، فذكره.","grade":"صحيح","chapter_ar":"باب الشهر يكون تسعًا وعشرين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Khuzaymah (1921) and Ibn Hibban (3453). It was also narrated by Muslim in The Book of Divorce (1479).","chapter_en":"The month may be twenty-nine days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["ʿUmar ibn al-Khattab said: When the Messenger of Allah ﷺ kept away from his wives, I said: “O Messenger of Allah, you were only in the room for twenty-nine days.” The Messenger of Allah ﷺ said: “The month is twenty-nine days.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن خزيمة (1921)، وابن حبان (3453). ورواه مسلم (1479)."},{"num":4331,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَتَانِي جِبْرِيلُ عَلَيْهِ السَّلاَمُ، فَقَالَ: الشَّهْرُ تِسْعٌ وَعِشْرُونَ يَوْمًا."],"takhrij":"صحيح: رواه النسائيّ (2133)، وأحمد (1885) كلاهما من حديث شعبة، عن سلمة بن كهيل، عن أبي الحكم، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب الشهر يكون تسعًا وعشرين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasa’i (2133) and Ahmad (1885).","chapter_en":"The month may be twenty-nine days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿAbbas reported that the Prophet ﷺ said: “Jibril, peace be upon him, came to me and said: The month is twenty-nine days.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (2133)، وأحمد (1885)."},{"num":4332,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ، رَضِيَ اللَّهُ عَنْهُ قَالَ:  ضَرَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ عَلَى الْأُخْرَى، فَقَالَ: الشَّهْرُ هَكَذَا وَهَكَذَا، ثُمَّ نَقَصَ فِي الثَّالِثَةِ إِصْبَعًا."],"takhrij":"صحيح: رواه مسلم في الصيام (1086) من طريق إسماعيل بن أبي خالد، حدّثني محمد بن سعد، عن أبيه، سعد بن أبي وقاص، فذكره.","grade":"صحيح","chapter_ar":"باب الشهر يكون تسعًا وعشرين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1086).","chapter_en":"The month may be twenty-nine days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Saʿd ibn Abi Waqqas said: The Messenger of Allah ﷺ struck one hand upon the other and said: “The month is like this and this,” then on the third time he reduced one finger."]},"buhuth":{"en":["In another wording recorded by him: “The month is like this, and this, and this: ten, and ten, and nine once.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1086)."},{"num":4333,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَمَّا مَضَتْ تِسْعٌ وَعِشْرُونَ لَيْلَةً أَعُدُّهُنَّ، دَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (قَالَتْ: بَدَأَ بِي)، فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّكَ أَقْسَمْتَ أَنْ لَا تَدْخُلَ عَلَيْنَا شَهْرًا، وَإِنَّكَ دَخَلْتَ مِنْ تِسْعٍ وَعِشْرِينَ، أَعُدُّهُنَّ، فَقَالَ: إِنَّ الشَّهْرَ تِسْعٌ وَعِشْرُونَ."],"takhrij":"صحيح: رواه مسلم في الصيام (1083) عن عبد بن حميد، أخبرنا عبد الرزاق، أخبرنا معمر، عن الزهري، أخبرني عروة، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب الشهر يكون تسعًا وعشرين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1083).","chapter_en":"The month may be twenty-nine days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["ʿA’ishah said: When twenty-nine nights had passed, counting them carefully, the Messenger of Allah ﷺ entered upon me. She said: He began with me. I said: “O Messenger of Allah, you had sworn not to enter upon us for a month, yet you entered after twenty-nine, and I counted them.” He said: “The month is twenty-nine days.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1083)."},{"num":4334,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ عمرو بْنِ سعيد بْنِ الْعَاصِ الأمويّ، قَالَ: قِيلَ لِعَائِشَةَ: يَا أمَّ الْمُؤْمِنِينَ، رؤي هَذَا الشَّهْرُ لِتِسْعٍ وَعِشْرِينَ! قَالَتْ: وَمَا يُعْجِبُكُمْ مِنْ ذَاكَ، لَمَا صُمتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تِسْعًا وَعِشْرِينَ أَكْثَرُ مِمَّا صمتُ ثَلَاثِينَ."],"takhrij":"صحيح: رواه الإمام أحمد (24518)، والطبراني في الأوسط (5245)، والدارقطني (2351)، والبيهقي (4/250) كلّهم من طرق عن إسحاق بن سعيد بن عمرو، عن أبيه سعيد بن عمرو بن سعيد بن العاص الأمويّ، عن عائشة، فذكرته. قال الدارقطني: هذا إسناد صحيح حسن .","grade":"صحيح","chapter_ar":"باب الشهر يكون تسعًا وعشرين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (24518), al-Tabarani in al-Awsat (5245), and al-Daraqutni (2351).","chapter_en":"The month may be twenty-nine days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Saʿid ibn ʿAmr ibn Saʿid ibn al-ʿAs said: It was said to ʿA’ishah: “O Mother of the Believers, this month was seen as twenty-nine days.” She said: “Why are you surprised by that? When I fasted with the Messenger of Allah ﷺ, I fasted twenty-nine more often than I fasted thirty.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (24518)، والطبراني في الأوسط (5245)، والدارقطني (2351)."},{"num":4335,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ بْنِ عبدالله، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اعْتَزَلَ نِسَاءَهُ شَهْرًا، فَخَرَجَ إِلَيْنَا فِي تِسْعٍ وَعِشْرِينَ، فَقُلْنَا: إِنَّمَا الشَّهْرُ، وَصَفَّقَ بِيَدَيْهِ ثَلَاثَ مَرَّاتٍ، وَحَبَسَ إصْبعاً وَاحِدَةً فِي الْآخِرَةِ."],"takhrij":"صحيح: رواه مسلم في الصّيام (1084) من طريق الليث، عن أبي الزبير، عن جابر بن عبدالله قال: فذكره.","grade":"صحيح","chapter_ar":"باب الشهر يكون تسعًا وعشرين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1084).","chapter_en":"The month may be twenty-nine days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: The Messenger of Allah ﷺ kept away from his wives for a month, then he came out to them after twenty-nine days and said: “The month is only this way,” and he clapped his hands three times, withholding one finger the last time."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1084)."},{"num":4336,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَمْ مَضَى مِنَ الشَّهْرِ؟. قَالَ: قُلْنَا: اثْنَانِ وَعِشْرُونَ، وَبَقِيَتْ ثَمَانٍ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الشَّهْرُ هَكَذَا، وَالشَّهْرُ هَكَذَا، وَالشَّهْرُ هَكَذَا. ثَلاَثَ مَرَّاتٍ، وَأَمْسَكَ وَاحِدَةً."],"takhrij":"صحيح: رواه ابن ماجه (1656) عن أبي بكر بن أبي شيبة، قال: حدّثنا أبو معاوية، عن الأعمش، عن أبي صالح، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب الشهر يكون تسعًا وعشرين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Majah (1656), Ahmad (7423), Ibn Hibban (3450), and al-Bayhaqi (4/310).","chapter_en":"The month may be twenty-nine days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “How much of the month has passed?” We said: Twenty-two days have passed, and eight remain. Then the Messenger of Allah ﷺ said: “The month is like this, and this, and this,” three times, and he held back one finger."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (1656)، وأحمد (7423)، وابن حبان (3450)، والبيهقي (8539)."},{"num":4337,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ يَتَقَدَّمَنَّ أَحَدُكُمْ رَمَضَانَ بِصَوْمِ يَوْمٍ أَوْ يَوْمَيْنِ، إِلاَّ أَنْ يَكُونَ رَجُلٌ كَانَ يَصُومُ صَوْمَهُ فَلْيَصُمْ ذَلِكَ الْيَوْمَ."],"takhrij":"متفق عليه: رواه البخاريّ في الصوم (1914)، ومسلم في الصيام (1082) كلاهما من طريق هشام (هو ابن أبي عبدالله الدّستوائيّ)، حدّثنا يحيى بن أبي كثير، عن أبي سلمة (هو ابن عبدالرحمن بن عوف)، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب لا تقدّموا رمضان بصوم يوم ولا يومين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1914) and Muslim (1082). This is the wording of al-Bukhari.","chapter_en":"Do not precede Ramadan by fasting one day or two days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “None of you should go ahead of Ramadan by fasting a day or two before it, unless it is a man who regularly fasts, in which case let him fast that day.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1914)، ومسلم (1082). واللفظ للبخاري."},{"num":4338,"demo":false,"sanad":"","matn":["عَنْ صِلَةَ، قَالَ: كُنَّا عِنْدَ عَمَّارٍ فِي الْيَوْمِ الَّذِي يُشَكُّ فِيهِ، فَأُتِيَ بِشَاةٍ، فَتَنَحَّى بَعْضُ الْقَوْمِ. فَقَالَ عَمَّارٌ مَنْ صَامَ هَذَا الْيَوْمَ فَقَدْ عَصَى أَبَا الْقَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه أبو داود (2334)، والترمذيّ (686)، والنسائيّ (2188)، وابن ماجه (1645) كلّهم من طرق عن عمرو بن قيس الملائيّ، عن أبي إسحاق، عن صلة بن زفر، فذكره. وصحّحه ابن خزيمة (1914)، وابن حبان (3585)، والحاكم (1542).","grade":"صحيح","chapter_ar":"باب لا تقدّموا رمضان بصوم يوم ولا يومين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (2334), al-Tirmidhi (686), al-Nasa’i (2188), and Ibn Majah (1645).","chapter_en":"Do not precede Ramadan by fasting one day or two days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Silah said: We were with ʿAmmar on the doubtful day, and a sheep was brought. Some of the people held back, so ʿAmmar said: “Whoever fasts this day has disobeyed Abu al-Qasim ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2334)، والترمذي (686)، والنسائي (2188)، وابن ماجه (1645)."},{"num":4339,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدِ بْنِ كَعْبٍ الْقُرَظِيِّ، قَالَ: دَخَلْتُ عَلَى أَنَسِ بْنِ مَالِكٍ عَنْدَ الْعَصْرِ يَوْمَ يَشُكُّونَ فِيهِ رَمَضَانَ، وَأَنَا أُرِيدُ أَنْ أُسَلِّمَ عَلَيْهِ، فَدَعَا بِطَعَامٍ فَأَكَلَ، فَقُلْتُ: هَذَا الَّذِي تَصْنَعُ سُنَّةٌ؟ قَالَ: نَعَمْ."],"takhrij":"صحيح: رواه الطبرانيّ في الأوسط (9039) من طريق محمد بن جعفر بن أبي كثير، عن زيد بن أسلم، عن محمد بن المنكدر، عن محمد بن كعب القرظي، فذكره.","grade":"صحيح","chapter_ar":"باب لا تقدّموا رمضان بصوم يوم ولا يومين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Tabarani in al-Awsat (9039).","chapter_en":"Do not precede Ramadan by fasting one day or two days","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Muhammad ibn Kaʿb al-Qurazi said: I entered upon Anas ibn Malik at the time of ʿAsr on a day when there was doubt about Ramadan, and I wanted to greet him. He called for food and ate. I said: “Is what you are doing part of the Sunnah?” He said: “Yes.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في الأوسط (9039)."},{"num":4340,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الصَّوْمُ يَوْمَ تَصُومُونَ، وَالْفِطْرُ يَوْمَ تُفْطِرُونَ، وَالأَضْحَى يَوْمَ تُضَحُّونَ."],"takhrij":"حسن: رواه الترمذي (697) عن محمد بن إسماعيل، حدثنا إبراهيم بن المنذر، حدثنا إسحاق بن جعفر بن محمد، حدثني عبدالله بن جعفر، عن عثمان بن محمد الأخنسي، عن سعيد المقبري، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في أن الصوم يوم تصومون، والفطر يوم تفطرون، والأضحى يوم تضحون","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Tirmidhi (697), who said: Hasan Gharib.","chapter_en":"What has come regarding the meaning of: the fast is the day you all fast, the breaking of the fast is the day you all break it, and the sacrifice feast is the day you all offer sacrifice","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “The fast is on the day you all fast, the breaking of the fast is on the day you all break it, and the sacrifice feast is on the day you all offer sacrifice.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (697) وقال: حسن غريب."},{"num":4341,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: شَهْرَانِ لاَ يَنْقُصَانِ، شَهْرَا عيدٍ: رَمَضَانُ، وَذُو الْحَجَّةِ ."],"takhrij":"متفق عليه: رواه البخاريّ في الصوم (1912)، ومسلم في الصيام (1089) كلاهما من طريق معتمر بن سليمان، عن إسحاق بن سويد، وخالد الحذّاء، كلاهما عن عبدالرحمن بن أبي بكرة، عن أبيه، فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب بيان معنى قوله ﷺ: (شهران لا ينقصان)","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari in The Book of Fasting (1912) and Muslim in The Book of Fasting (1089). This is the wording of al-Bukhari.","chapter_en":"Clarifying the meaning of his saying: Two months do not decrease","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abu Bakrah reported that the Prophet ﷺ said: “Two months do not decrease: the two months of the festivals, Ramadan and Dhu al-Hijjah.”"]},"buhuth":{"en":["Regarding his words, “Two months do not decrease,” Ahmad said: the meaning is that the two festival months do not both decrease together in one year, meaning Ramadan and Dhu al-Hijjah. If one of them is short, the other is complete. This was mentioned by al-Tirmidhi after citing the hadith (692).","It was also said that the meaning is that they do not decrease in virtue, whether they are twenty-nine days or thirty days. These two views are well known from the early scholars, as al-Hafiz said in al-Fath (4/125)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1912)، ومسلم (1089). واللفظ للبخاري."},{"num":4342,"demo":false,"sanad":"","matn":["عَنْ كُرَيْبٍ،  أَنَّ أُمَّ الْفَضْلِ بِنْتَ الْحَارِثِ بَعَثَتْهُ إِلَى مُعَاوِيَةَ بِالشَّامِ. قَالَ: فَقَدِمْتُ الشَّامَ، فَقَضَيْتُ حَاجَتَهَا، وَاسْتُهِلَّ عَلَيَّ رَمَضَانُ، وَأَنَا بِالشَّامِ. فَرَأَيْتُ الْهِلَالَ لَيْلَةَ الْجُمُعَةِ، ثُمَّ قَدِمْتُ الْمَدِينَةَ فِي آخِرِ الشَّهْرِ، فَسَأَلَنِي عَبْدُ اللَّهِ بْنُ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا، ثُمَّ ذَكَرَ الْهِلَالَ، فَقَالَ: مَتَى رَأَيْتُمُ الْهِلَالَ؟ فَقُلْتُ: رَأَيْنَاهُ لَيْلَةَ الْجُمُعَةِ، فَقَالَ: أَنْتَ رَأَيْتَهُ؟ فَقُلْتُ: نَعَمْ، وَرَآهُ النَّاسُ، وَصَامُوا وَصَامَ مُعَاوِيَةُ. فَقَالَ: لَكِنَّا رَأَيْنَاهُ لَيْلَةَ السَّبْتِ، فَلَا نَزَالُ نَصُومُ حَتَّى نُكْمِلَ ثَلَاثِينَ، أَوْ نَرَاهُ، فَقُلْتُ: أَوَلَا تَكْتَفِي بِرُؤْيَةِ مُعَاوِيَةَ وَصِيَامِهِ؟ فَقَالَ: لَا، هَكَذَا أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه مسلم في الصيام (1087) من طريق إسماعيل بن جعفر، عن محمد بن أبي حرملة، عن كريب، به، فذكره.","grade":"صحيح","chapter_ar":"باب الهلال إذا رآه أهل بلدة، هل يلزم بقية البلاد الصوم؟","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1087).","chapter_en":"If the people of one town see the crescent, are the rest of the lands required to fast?","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Kurayb reported that Umm al-Fadl bint al-Harith sent him to Muʿawiyah in Syria. He said: I arrived in Syria and completed her errand, and Ramadan began while I was there. I saw the crescent on the night of Friday. Then I came to Madinah at the end of the month, and ʿAbdullah ibn ʿAbbas asked me, then mentioned the crescent and said: “When did you see the crescent?” I said: “We saw it on the night of Friday.” He said: “Did you yourself see it?” I said: “Yes, and the people saw it, and they fasted, and Muʿawiyah fasted.” He said: “But we saw it on the night of Saturday, so we will continue fasting until we complete thirty days or see it.” I said: “Will you not be satisfied with the sighting of Muʿawiyah and his fasting?” He said: “No. This is how the Messenger of Allah ﷺ commanded us.”"]},"buhuth":{"en":["The Permanent Committee for Scholarly Research, Daʿwah, and Fatwa issued fatwa no. (319):","“Whoever does not see the crescent in their region, whether the sky is clear or cloudy, must complete the count as thirty if it is not seen by others in another region. If it is established for them that the crescent was seen in another region, then they must follow what the Muslim ruler in their land decides concerning fasting or breaking the fast, because his ruling in such a matter removes disagreement among the jurists regarding whether differing horizons are to be considered or not.","If the ruler in their land is not Muslim, then they act according to what the council of the Islamic center in their land decides regarding fasting based on the crescent sighting in another region or breaking the fast, in accordance with the view that differing horizons are taken into account.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1087)."},{"num":4343,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عُمَرَ، قَالَ: تَرَاءَى النَّاسُ الْهِلاَلَ، فَأَخْبَرْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنِّي رَأَيْتُهُ فَصَامَهُ وَأَمَرَ النَّاسَ بِصِيَامِهِ."],"takhrij":"صحيح: رواه أبو داود (2342) عن محمود بن خالد وعبدالله بن عبدالرحمن السمرقنديّ ـ وأنا لحديثه أتقن ـ، قالا: حدّثنا مروان (وهو ابن محمد)، عن عبدالله بن وهب، عن يحيى بن عبدالله بن سالم، عن أبي بكر بن نافع، عن أبيه، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب في شهادة الواحد على رؤية هلال رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (2342), and authenticated by Ibn Hibban (3447).","chapter_en":"Regarding the testimony of one person for the sighting of the Ramadan crescent","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Ibn ʿUmar said: The people went out to look for the crescent, and I informed the Messenger of Allah ﷺ that I had seen it. So he fasted and commanded the people to fast."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2342)، وصححه ابن حبان (3447)."},{"num":4344,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي رَأَيْتُ الْهِلاَلَ ـ يَعْنِي هلال رَمَضَانَ ـ فَقَالَ: أَتَشْهَدُ أَنْ لاَ إِلَهَ إلاّ اللَّهُ؟ قَالَ: نَعَمْ، قَالَ: أَتَشْهَدُ أنّ مُحَمَّدًا رَسُولُ اللَّهِ؟ قَالَ: نَعَمْ. قَالَ: يَا بِلاَلُ، أذّن فِي النَّاسِ أن يصوموا غداً ."],"takhrij":"حسن: رواه أبو داود (2340)، والترمذي (691) كلاهما من حديث الوليد بن أبي ثور، عن سماك، عن عكرمة، عن ابن عباس، فذكره.","grade":"حسن","chapter_ar":"باب في شهادة الواحد على رؤية هلال رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (2340) and al-Tirmidhi (691).","chapter_en":"Regarding the testimony of one person for the sighting of the Ramadan crescent","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Ibn ʿAbbas said: A Bedouin came to the Prophet ﷺ and said: “I have seen the crescent,” meaning the crescent of Ramadan. He said: “Do you testify that there is no god but Allah?” He said: Yes. He said: “Do you testify that Muhammad is the Messenger of Allah?” He said: Yes. He said: “O Bilal, announce to the people that they should fast tomorrow.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2340)، والترمذي (691)."},{"num":4345,"demo":false,"sanad":"","matn":["عَنْ حسين بْنِ الْحَارِثِ الجدليّ ـ من جديلة قيس ـ، أنّ أَمِيرَ مَكَّةَ خَطَبَ، ثُمَّ قَالَ: عَهِدَ إِلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ نَنْسُكَ لِلرُّؤْيَةِ، فَإِنْ لَمْ نَرَهُ وَشَهِدَ شَاهِدَا عَدْلٍ نَسَكْنَا بِشَهَادَتِهِمَا، فَسَأَلْتُ الْحُسَيْنَ ابن الْحَارِثِ: مَنْ أَمِيرُ مَكَّةَ؟ قَالَ: لاَ أَدْرِي، ثُمَّ لَقِيَنِي بَعْدُ قَالَ: هُوَ الْحَارِثُ بْنُ حَاطِبٍ أَخُو مُحَمَّدِ بْنِ حَاطِبٍ. ثُمَّ قَالَ الأَمِيرُ: إنّ فِيكُمْ مَنْ هُوَ أَعْلَمُ بِاللَّهِ وَرَسُولِهِ مِنِّي. وَشَهِدَ هَذَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَوْمَأَ بِيَدِهِ إِلَى رَجُلٍ ـ قَالَ الْحُسَيْنُ: فَقُلْتُ لِشَيْخٍ إِلَى جَنْبِي: مَنْ هَذَا الَّذِي أَوْمَأَ إِلَيْهِ الأَمِيرُ؟ قَالَ: هَذَا عبدالله بْنُ عُمَرَ، وَصَدَقَ. كَانَ أَعْلَمَ بِاللَّهِ مِنْهُ. فَقَالَ: بِذَلِكَ أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. ."],"takhrij":"حسن: رواه أبو داود (2338) عن محمد بن عبد الرحيم أبي يحيى البزار، ثنا سعيد بن سليمان، ثنا عبّاد، عن أبي مالك الأشجعيّ، ثنا حسين بن الحارث الجدلي، فذكره.","grade":"حسن","chapter_ar":"باب في شهادة رجلين على رؤية هلال شوال","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (2338).","chapter_en":"Regarding the testimony of two men for the sighting of the Shawwal crescent","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["Husayn ibn al-Harith al-Jadali — from Jadilah Qays — reported that the governor of Makkah delivered a sermon and then said: The Messenger of Allah ﷺ instructed us that we perform the rites based on sighting. If we do not see it, and two upright witnesses testify, then we perform the rites based on their testimony. I asked Husayn ibn al-Harith: “Who was the governor of Makkah?” He said: “I do not know.” Then he met me later and said: “It was al-Harith ibn Hatib, the brother of Muhammad ibn Hatib.” Then the governor said: “Among you is one who is more knowledgeable about Allah and His Messenger than I am, and this has been testified to from the Messenger of Allah ﷺ,” and he pointed with his hand to a man. Husayn said: I asked an old man beside me: “Who is this person the governor pointed to?” He said: “This is ʿAbdullah ibn ʿUmar, and he spoke the truth. He was more knowledgeable about Allah than him.” Then he said: “This is what the Messenger of Allah ﷺ commanded us.”"]},"buhuth":{"en":["Understanding of the chapter: The majority of scholars used the hadiths of this chapter as proof that the crescent of Shawwal is not established except by the testimony of two upright men.","Al-Hafiz Ibn al-Qayyim said in Zad al-Maʿad (2/49–50):","“Part of his guidance ﷺ was that he commanded the people to begin fasting on the testimony of one Muslim man, and to end it on the testimony of two.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2338)."},{"num":4346,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ، مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: اخْتَلَفَ النَّاسُ فِي آخِرِ يَوْمٍ مِنْ رَمَضَانَ. فَقَدِمَ أَعْرَابِيَّانِ فَشَهِدَا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِاللَّهِ لأَهَلاَّ الْهِلاَلَ أَمْسِ عَشِيَّةً، فَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النَّاسَ أَنْ يُفْطِرُوا.","زَادَ خَلَفٌ فِي حَدِيثِهِ: وَأَنْ يَغْدُوا إِلَى مُصَلاَّهُمْ."],"takhrij":"صحيح: رواه أبو داود (2339) عن مسدّد، وخلف بن هشام المقرئ، قالا: حدّثنا أبو عوانة، عن منصور، عن ربعي بن حراش، عن رجل من أصحاب النبيّ صلى الله عليه وسلم، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في شهادة رجلين على رؤية هلال الفطر بعد الزوال","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (2339).","chapter_en":"What has come regarding the testimony of two men about sighting the crescent of breaking the fast after midday","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["A man from the Companions of the Prophet ﷺ said: The people differed concerning the last day of Ramadan. Then two Bedouins came and testified before the Prophet ﷺ by Allah that they had seen the crescent the previous evening. So the Messenger of Allah ﷺ commanded the people to break their fast. Khalaf added in his version: “and that they should go out the next morning to their prayer place.”"]},"buhuth":{"en":["Al-Daraqutni also narrated it through another chain with the wording: “The Prophet ﷺ began the morning fasting in order to complete the thirty days of Ramadan. Then two Bedouins came and testified that there is no god but Allah and that they had seen it the previous evening, so he commanded them to break the fast.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2339)."},{"num":4347,"demo":false,"sanad":"","matn":["عَنْ أَبِي عُمَيْرِ بْنِ أَنَسٍ، عَنْ عُمُومَةٍ، لَهُ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّ رَكْبًا جَاءُوا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَشْهَدُونَ أَنَّهُمْ رَأَوُا الْهِلاَلَ بِالأَمْسِ، فَأَمَرَهُمْ أَنْ يُفْطِرُوا، وَإِذَا أَصْبَحُوا أَنْ يَغْدُوا إِلَى مُصَلاَّهُمْ."],"takhrij":"حسن: رواه أبو داود (1157)، والنسائي (1557)، والدارقطني (2003) كلهم من حديث شعبة، عن جعفر بن إياس، عن أبي عمير بن أنس، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في شهادة رجلين على رؤية هلال الفطر بعد الزوال","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (1157), al-Nasa’i (1557), and al-Daraqutni (2003).","chapter_en":"What has come regarding the testimony of two men about sighting the crescent of breaking the fast after midday","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["Abu ʿUmayr ibn Anas reported from some of his paternal uncles among the Companions of the Prophet ﷺ that a group of riders came to the Prophet ﷺ testifying that they had seen the crescent the day before. So he commanded them to break the fast, and when morning came, to go out to their prayer place."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1157)، والنسائي (1557)، والدارقطني (2003)."},{"num":4348,"demo":false,"sanad":"","matn":["عَنْ حَفْصَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ،  قَالَ: مَنْ لَمْ يُبَيِّتِ الصِّيَامَ مِنَ اللَّيْلِ، فَلَا صِيَامَ لَهُ."],"takhrij":"صحيح: رواه أبو داود (2454)، وابن خزيمة (1933)، والبيهقي (7909) كلّهم من طرق عن عبدالله بن وهب، حدّثني ابن لهيعة، ويحى بن أيوب، عن عبدالله بن أبي بكر بن حزم، عن ابن شهاب، عن سالم، عن أبيه، عن حفصة زوج النبيّ صلى الله عليه وسلم ، فذكرته.","grade":"صحيح","chapter_ar":"باب إيجاب النية للصوم الواجب قبل طلوع الفجر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (2454), Ibn Khuzaymah (1933), al-Nasa’i (2332), and al-Tirmidhi (730).","chapter_en":"The obligation of intending the obligatory fast before dawn","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":17,"content":{"translation":{"en":["Hafsah reported that the Prophet ﷺ said: “Whoever does not make the intention for fasting during the night has no fast.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2454)، وابن خزيمة (1933)، والنسائي (2332)، والترمذي (730)."},{"num":4349,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ، رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَسَحَّرُوا، فَإِنَّ فِي السَّحُورِ بَرَكَةً."],"takhrij":"متفق عليه: رواه البخاريّ في الصوم (1923) من طريق شعبة، ومسلم في الصيام (1095) من طريق ابن عليّة ـ كلاهما عن عبد العزيز بن صُهيب، عن أنس، به.","grade":"متفق عليه","chapter_ar":"باب الترغيب في السحور","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1923) and Muslim (1095).","chapter_en":"Encouragement to eat the pre-dawn meal","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["Anas ibn Malik reported that the Prophet ﷺ said: “Take the pre-dawn meal, for there is blessing in the pre-dawn meal.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1923)، ومسلم (1095)."},{"num":4350,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَسَحَّرُوا، فَإِنَّ فِي السَّحُورِ بَرَكَةً."],"takhrij":"حسن: رواه الإمام أحمد (8898) عن عبد الرزاق وهو في مصنفه abdrazzaq(7601) قال: أخبرنا سفيان، عن ابن أبي ليلى، عن عطاء، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب الترغيب في السحور","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (8898) and ʿAbd al-Razzaq (7601).","chapter_en":"Encouragement to eat the pre-dawn meal","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Take the pre-dawn meal, for there is blessing in the pre-dawn meal.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (8898)، وعبد الرزاق (7601)."},{"num":4351,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مَسْعُودٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: تَسَحَّرُوا فإنّ فِي السَّحُورِ بَرَكَةً ."],"takhrij":"حسن: رواه النسائي (2144) عن محمد بن بشار، قال: حدّثنا عبدالرحمن بن مهدي، قال: حدّثنا أبو بكر بن عياش، عن عاصم، عن زرّ، عن عبدالله، فذكره.","grade":"حسن","chapter_ar":"باب الترغيب في السحور","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Nasa’i (2144) and Ibn Khuzaymah (1936).","chapter_en":"Encouragement to eat the pre-dawn meal","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["ʿAbdullah ibn Masʿud reported that the Prophet ﷺ said: “Take the pre-dawn meal, for there is blessing in the pre-dawn meal.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (2144)، وابن خزيمة (1936)."},{"num":4352,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ، مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: دَخَلْتُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَتَسَحَّرُ فَقَالَ: إِنَّهَا بَرَكَةٌ أَعْطَاكُمُ اللَّهُ إِيَّاهَا فَلاَ تَدَعُوهُ."],"takhrij":"صحيح: رواه النسائيّ (2162) عن إسحاق بن منصور، قال: أنبأنا عبدالرحمن، قال: حدّثنا شعبة، عن عبد الحميد صاحب الزيادي، قال: سمعت عبدالله بن الحارث يحدّث عن رجل، فذكره.","grade":"صحيح","chapter_ar":"باب الترغيب في السحور","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasa’i (2162) and Ahmad (23142, 23113).","chapter_en":"Encouragement to eat the pre-dawn meal","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["A man from the Companions of the Prophet ﷺ said: I entered upon the Prophet ﷺ while he was taking the pre-dawn meal, and he said: “It is a blessing that Allah has given you, so do not abandon it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (2162)، والإمام أحمد (23142، 23113)."},{"num":4353,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى الْمُتَسَحِّرِينَ."],"takhrij":"حسن: رواه ابن حبان (3467) عن أحمد بن الحسن بن أبي الصغير، حدّثنا إبراهيم بن منقذ، حدّثنا إدريس بن يحيى، عن عبدالله بن عياش بن عباس، عن عبدالله بن سليمان الطويل، عن نافع، عن ابن عمر، فذكره.","grade":"حسن","chapter_ar":"باب الترغيب في السحور","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ibn Hibban (3467).","chapter_en":"Encouragement to eat the pre-dawn meal","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said: “Indeed Allah and His angels send blessings upon those who eat the pre-dawn meal.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[570],"tks":"حسن: رواه ابن حبان (3467)."},{"num":4354,"demo":false,"sanad":"","matn":["عَنْ عُبْدَالِلَهِ بْنِ عَمْرِو بْنِ الْعَاصِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَسَحَّرُوا وَلَوْ بِجَرْعَةٍ مِنْ مَاءٍ .."],"takhrij":"حسن: رواه ابن حبان في \"صحيحه\" (3476) عن أحمد بن يحى بن زهير بتُستر، قال: حدّثنا إبراهيم بن راشد الآدميّ، قال: حدّثنا محمد بن بلال، قال: حدثنا عمران القطان، عن قتادة، عن عقبة بن وسّاج، عن عبدالله بن عمرو، فذكره.","grade":"حسن","chapter_ar":"باب الترغيب في السحور","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ibn Hibban in his Sahih (3476).","chapter_en":"Encouragement to eat the pre-dawn meal","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr said: The Messenger of Allah ﷺ said: “Take the pre-dawn meal, even if only with a sip of water.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان في صحيحه (3476)."},{"num":4355,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: السَّحُورُ أَكْلُهُ بَرَكَةٌ، فَلَا تَدَعُوهُ، وَلَوْ أَنْ يَجْرَعَ أَحَدُكُمْ جُرْعَةً مِنْ مَاءٍ، فَإِنَّ اللَّهَ عَزَّ وَجَلَّ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى الْمُتَسَحِّرِينَ."],"takhrij":"حسن: رواه الإمام أحمد (11086) عن إسماعيل (هو ابن علية)، عن هشام الدّستوائيّ، قال: حدّثنا يحيى بن أبي كثير، عن أبي رفاعة، عن أبي سعيد الخدريّ، فذكره.","grade":"حسن","chapter_ar":"باب الترغيب في السحور","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (11281, 11396, 11086).","chapter_en":"Encouragement to eat the pre-dawn meal","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: The Messenger of Allah ﷺ said: “The pre-dawn meal is a blessed meal, so do not leave it, even if one of you only swallows a sip of water, for Allah, Mighty and Majestic, and His angels send blessings upon those who eat the pre-dawn meal.”"]},"buhuth":{"en":["His saying, “There is blessing in the pre-dawn meal,” means that eating this meal is done for a pure act of worship, which is fasting, and fasting in its entirety is blessed. The pre-dawn meal is one of the means leading into that blessing. It also has other benefits, including strengthening the body to carry out the fast, so the blessing of fasting is connected to the blessing of the pre-dawn meal."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (11281، 11396، 11086)."},{"num":4356,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ الْعَاصِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  فَصْلُ مَا بَيْنَ صِيَامِنَا وَصِيَامِ أَهْلِ الْكِتَابِ، أَكْلَةُ السَّحَرِ."],"takhrij":"صحيح: رواه مسلم في الصيام (1096) من طريق موسى بن عُلَي، عن أبيه، عن أبي قيس مولى عمرو بن العاص، عن عمرو بن العاص، فذكره.","grade":"صحيح","chapter_ar":"باب فصل ما بين صيامنا وصيام أهل الكتاب","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1096).","chapter_en":"The difference between our fasting and the fasting of the People of the Book","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["ʿAmr ibn al-ʿAs reported that the Messenger of Allah ﷺ said: “The difference between our fasting and the fasting of the People of the Book is the pre-dawn meal.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1096)."},{"num":4357,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: أَرْسَلَ إِلَيَّ عُمَرُ بْنُ الْخَطَّابِ يَدْعُونِي إِلَى السَّحُورِ، وَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَمَّاهُ الْغَدَاءَ الْمُبَارَكَ."],"takhrij":"حسن: رواه الطبراني في \"الأوسط\" (505) عن أحمد بن القاسم بن مساور الجوهريّ، قال: حدّثنا محمد بن إبراهيم أخو أبي معمر، قال: حدّثنا سفيان بن عيينة، عن إبراهيم بن ميسرة، عن طاوس، عن ابن عباس، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تسمية السحور بالغداء المبارك","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Tabarani in al-Awsat (505) and al-Khatib in his History (1/387).","chapter_en":"What has come regarding calling the pre-dawn meal the blessed morning meal","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Ibn ʿAbbas said: ʿUmar ibn al-Khattab sent for me, inviting me to the pre-dawn meal, and said: The Messenger of Allah ﷺ called it the blessed morning meal."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (505)، والخطيب في تاريخه (358)."},{"num":4358,"demo":false,"sanad":"","matn":["عَنِ الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: عَلَيْكُمْ بِغَدَاءِ السُّحُورِ، فَإِنَّهُ هُوَ الْغَدَاءُ الْمُبَارَكُ."],"takhrij":"حسن: رواه النسائيّ (2164) عن سويد بن نصر، قال: أنبأنا عبدالله (هو ابن المبارك)، عن بقية بن الوليد، قال: أخبرني بحير بن سعد، عن خالد بن معدان، عن المقدام بن معديكرب، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تسمية السحور بالغداء المبارك","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Nasa’i (2164) and Ahmad (17192).","chapter_en":"What has come regarding calling the pre-dawn meal the blessed morning meal","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Al-Miqdam ibn Maʿdi Karib reported that the Prophet ﷺ said: “Hold firmly to the morning meal of the pre-dawn time, for it is the blessed morning meal.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (2164)، والإمام أحمد (17192)."},{"num":4359,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: نِعْمَ سَحُورُ الْمُؤْمِنِ التَّمْرُ."],"takhrij":"حسن: رواه أبو داود (2345)، والبيهقيّ (8117) كلاهما من طريق محمد بن أبي الوزير أبي المطرف، حدّثنا محمد بن موسى، عن سعيد المقبريّ، عن أبي هريرة، قال: فذكره.","grade":"حسن","chapter_ar":"باب استحباب السحور بالتمر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (2345) and al-Bayhaqi (4/236–237).","chapter_en":"The recommendation of taking the pre-dawn meal with dates","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":21,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “How excellent are dates as the believer’s pre-dawn meal.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2345)، والبيهقي (8117)."},{"num":4360,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَذَلِكَ عِنْدَ السُّحُورِ يَا أَنَسُ، إِنِّي أُرِيدُ الصِّيَامَ أَطْعِمْنِي شَيْئًا. فَأَتَيْتُهُ بِتَمْرٍ وَإِنَاءٍ فِيهِ مَاءٌ، وَذَلِكَ بَعْدَ مَا أَذَّنَ بِلاَلٌ. فَقَالَ: يَا أَنَسُ، انْظُرْ رَجُلاً يَأْكُلُ مَعِي. فَدَعَوْتُ زَيْدَ بْنَ ثَابِتٍ، فَجَاءَ فَقَالَ: إِنِّي قَدْ شَرِبْتُ شَرْبَةَ سَوِيقٍ، وَأَنَا أُرِيدُ الصِّيَامَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَأَنَا أُرِيدُ الصِّيَامَ. فَتَسَحَّرَ مَعَهُ، ثُمَّ قَامَ فَصَلَّى رَكْعَتَيْنِ، ثُمَّ خَرَجَ إِلَى الصَّلاَةِ."],"takhrij":"صحيح: رواه النسائيّ (2167) من طريق عبد الرزاق ـ وهو في مصنفه abdrazzaq(7605) ـ وعنه الإمام أحمد (13033) عن معمر، عن قتادة، عن أنس، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب السحور بالسويق والتمر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasa’i (2167), ʿAbd al-Razzaq in his Musannaf (7605), and Ahmad (13033).","chapter_en":"The pre-dawn meal with roasted grain flour and dates","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":22,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ said at the time of the pre-dawn meal: “O Anas, I intend to fast, so feed me something.” So I brought him dates and a vessel containing water, and that was after Bilal had given the call to prayer. He said: “O Anas, look for a man to eat with me.” So I called Zayd ibn Thabit. He came and said: “I already drank a drink of roasted grain flour, and I intend to fast.” The Messenger of Allah ﷺ said: “And I also intend to fast.” So he took the pre-dawn meal with him, then stood and prayed two units of prayer, then went out to the prayer."]},"buhuth":{"en":["His words, “and that was after Bilal had given the call to prayer,” mean the first call to prayer that would be made during the night for the voluntary night prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (2167)، وعبد الرزاق في مصنفه (7605)، وأحمد (13033)."},{"num":4361,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ، أنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إنّ بِلاَلاً يُؤَذِّنُ بِلَيْلٍ، فَكُلُوا وَاشْرَبُوا حَتَّى يُنَادِيَ ابنُ أمّ مَكْتُومٍ ثُمَّ قَالَ: وَكَانَ رَجُلاً أَعْمَى، لاَ يُنَادِي حَتَّى يُقَالَ لَهُ: أَصْبَحْتَ أَصْبَحْتَ."],"takhrij":"متفق عليه: رواه مالك في الصلاة (14) عن عبدالله بن دينار، عن ابن عمر، فذكر الحديث. ورواه البخاري في الأذان (617، 620) من طريق مالك، به، مثله.","grade":"متفق عليه","chapter_ar":"باب استحباب تأخير السحور إلى أن يتبين الفجر الصادق","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (14), al-Bukhari (617, 620), and Muslim (1092).","chapter_en":"The recommendation of delaying the pre-dawn meal until true dawn becomes clear","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar reported that the Messenger of Allah ﷺ said: “Bilal gives the call to prayer at night, so eat and drink until Ibn Umm Maktum gives the call.” Then he said: He was a blind man and would not call until it was said to him, “Morning has come, morning has come.”"]},"buhuth":{"en":["In another wording: “The Messenger of Allah ﷺ had two callers to prayer: Bilal and Ibn Umm Maktum, the blind man. The Messenger of Allah ﷺ said: Bilal gives the call to prayer at night, so eat and drink until Ibn Umm Maktum gives the call to prayer.”","He said: There was only enough time between them for this one to come down and that one to go up.","His words, “There was only enough time between them…” mean that Bilal used to call before dawn, then remain waiting after his call for supplication and the like, while watching for dawn. When dawn was about to appear, he would come down and inform Ibn Umm Maktum, who would prepare himself for purification and other matters, then go up and begin the call to prayer at the first appearance of dawn."]}},"tuhfa":{},"full":1,"dr":1,"rep":[1872],"tks":"متفق عليه: رواه مالك (14)، والبخاري (617، 620)، ومسلم (1092)."},{"num":4362,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ: رَضِيَ اللَّهُ عَنْهَا أَنَّ بِلاَلاً، كَانَ يُؤَذِّنُ بِلَيْلٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كُلُوا وَاشْرَبُوا حَتَّى يُؤَذِّنَ ابْنُ أُمِّ مَكْتُومٍ، فَإِنَّهُ لاَ يُؤَذِّنُ حَتَّى يَطْلُعَ الْفَجْرُ. قَالَ الْقَاسِمُ: وَلَمْ يَكُنْ بَيْنَ أَذَانِهِمَا إِلاَّ أَنْ يَرْقَى ذَا وَيَنْزِلَ ذَا."],"takhrij":"متفق عليه: رواه البخاريّ في الصوم (1918، 1919) عن عبيد بن إسماعيل، عن أبي أسامة، عن عبيدالله، عن نافع، عن ابن عمر، والقاسم بن محمد، عن عائشة، فذكرته. ورواه مسلم في الصيام (1092/38) عن عبيد الله، عن نافع، عن ابن عمر وحده. ثم رواه عن عبيد الله، حدثنا القاسم، عن عائشة عن النبي صلى الله عليه وسلم بمثله، ولم يسق لفظه.","grade":"متفق عليه","chapter_ar":"باب استحباب تأخير السحور إلى أن يتبين الفجر الصادق","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1918, 1919) and Muslim (1092 no. 38).","chapter_en":"The recommendation of delaying the pre-dawn meal until true dawn becomes clear","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["The Mother of the Believers, ʿA’ishah, reported that Bilal used to give the call to prayer at night, so the Messenger of Allah ﷺ said: “Eat and drink until Ibn Umm Maktum gives the call to prayer, for he does not give the call until dawn appears.” Al-Qasim said: There was only enough time between their two calls for one to go up and the other to come down."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1918، 1919)، ومسلم (1092/38)."},{"num":4363,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَالَ: إِنَّ ابْنَ أُمِّ مَكْتُومٍ يُؤَذِّنُ بِلَيْلٍ، فَكُلُوا وَاشْرَبُوا حَتَّى يُؤَذِّنَ بِلَالٌ."],"takhrij":"صحيح: رواه أبو يعلى (4385) عن مصعب بن عبدالله، حدثني ابن الدراوردي، عن هشام بن عروة، عن عروة، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب استحباب تأخير السحور إلى أن يتبين الفجر الصادق","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Abu Yaʿla (4385), Ibn Khuzaymah (406), and from him Ibn Hibban (3472).","chapter_en":"The recommendation of delaying the pre-dawn meal until true dawn becomes clear","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["ʿA’ishah reported that the Prophet ﷺ said: “Eat and drink until Bilal gives the call to prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو يعلى (4385)، وابن خزيمة (406)، وعنه ابن حبان (3472)."},{"num":4364,"demo":false,"sanad":"","matn":["عَنْ ابْنِ مَسْعُودٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ يمنعنَّ أَحَدَكُمْ ـ أَوْ أَحَدًا مِنْكُمْ ـ أَذَانُ بِلاَلٍ مِنْ سَحُورِهِ، فَإِنَّهُ يُؤَذِّنُ ـ أَوْ يُنَادِي ـ بِلَيْلٍ لِيَرْجِعَ قَائِمَكُمْ، ولينتبه نَائِمَكُمْ، وَلَيْسَ أَنْ يَقُولَ: الْفَجْرُ أَوِ الصُّبْحُ، وَقَالَ بِأَصَابِعِهِ وَرَفَعَهَا إِلَى فَوْقُ، وَطَأْطَأَ إِلَى أَسْفَلُ ـ حَتَّى يَقُولَ هَكَذَا . وَقَالَ زُهَيْرٌ (وهو ابْنُ معاوية الجعفي) بِسَبَّابَتَيْهِ إِحْدَاهُمَا فَوْقَ الأُخْرَى، ثُمَّ مدَّها عَنْ يَمِينِهِ وَشِمَالِهِ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (621)، ومسلم في الصيام (1093) كلاهما من طريق سليمان التيميّ، عن أبي عثمان النّهدي، عن عبدالله بن مسعود، فذكره.","grade":"متفق عليه","chapter_ar":"باب استحباب تأخير السحور إلى أن يتبين الفجر الصادق","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (621) and Muslim (1093).","chapter_en":"The recommendation of delaying the pre-dawn meal until true dawn becomes clear","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Ibn Masʿud reported that the Prophet ﷺ said: “Let not Bilal’s call to prayer prevent any one of you, or one among you, from his pre-dawn meal, for he gives the call, or calls out, at night so that the one praying at night may return, and the one sleeping may wake up. It is not the dawn,” and he gestured with his fingers, raising them upward and lowering them downward, “until it appears like this.” And Zuhayr — who is Ibn Muʿawiyah al-Juʿfi — demonstrated with his two index fingers, placing one above the other, then stretching them right and left."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (621)، ومسلم (1093)."},{"num":4365,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جندب، قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا يَغُرَّنَّ أَحَدَكُمْ نِدَاءُ بِلَالٍ مِنَ السَّحُورِ، وَلَا هَذَا الْبَيَاضُ حَتَّى يَسْتَطِيرَ .","وفي رواية: لا يغرنّ من سحوركم أذان بلال، ولا بياض الأفق المستطيل هكذا حتى يستطير هكذا حكاه حماد بيديه. قال: يعني معترضاً.","وفي رواية: لَا يَغُرَّنَّكُمْ نِدَاءُ بِلَالٍ، وَلَا هَذَا الْبَيَاضُ حَتَّى يَبْدُوَ الْفَجْرُ أَوْ قَالَ: حَتَّى يَنْفَجِرَ الْفَجْرُ .."],"takhrij":"صحيح: رواه مسلم في الصيام (1094) من طرق عن سوادة بن حنظلة القشيريّ، قال: سمعت سمرة بن جندب يقول (فذكر الحديث بكلّ هذه الألفاظ).","grade":"صحيح","chapter_ar":"باب استحباب تأخير السحور إلى أن يتبين الفجر الصادق","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1094).","chapter_en":"The recommendation of delaying the pre-dawn meal until true dawn becomes clear","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Samurah ibn Jundub said: I heard the Prophet ﷺ say: “Let not Bilal’s call distract any of you from the pre-dawn meal, nor this whiteness, until it spreads across.” In another wording: “Let not Bilal’s call for your pre-dawn meal deceive you, nor the vertical whiteness of the horizon like this, until it spreads out like this,” and Hammad demonstrated it with his hands. He said: meaning horizontally across.","In another wording: “Let not Bilal’s call deceive you, nor this whiteness, until dawn appears,” or he said, “until dawn breaks forth.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1094)."},{"num":4366,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَزَيْدَ بْنَ ثَابِتٍ رَضِيَ اللَّهُ عَنْهُ تَسَحَّرَا، فَلَمَّا فَرَغَا مِنْ سَحُورِهِمَا قَامَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الصَّلاَةِ فَصَلَّى. قُلْنَا لأَنَسٍ: كَمْ كَانَ بَيْنَ فَرَاغِهِمَا مِنْ سَحُورِهِمَا وَدُخُولِهِمَا فِي الصَّلاَةِ؟ قَالَ: كَقَدْرِ مَا يَقْرَأُ الرَّجُلُ خَمْسِينَ آيَةً."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1134) عن يعقوب بن إبراهيم، قال: حدثنا روح، قال: حدثنا سعيد، عن قتادة، عن أنس بن مالك، فذكره. ورواه مسلم في الصوم (1097) من وجه آخر عن وكيع، عن هشام، عن قتادة به، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب استحباب تأخير السحور إلى أن يتبين الفجر الصادق","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1134) and Muslim (1097). This is the wording of al-Bukhari.","chapter_en":"The recommendation of delaying the pre-dawn meal until true dawn becomes clear","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet of Allah ﷺ and Zayd ibn Thabit took the pre-dawn meal. When they finished their pre-dawn meal, the Prophet of Allah ﷺ stood for the prayer and prayed. We said to Anas: How much time was there between their finishing the pre-dawn meal and entering the prayer? He said: The amount of time in which a man would recite fifty verses."]},"buhuth":{"en":["His words, “he stood for the prayer and prayed,” mean the dawn prayer.","And his words, “their entering the prayer,” mean the morning prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1134)، ومسلم (1097)، واللفظ للبخاري."},{"num":4367,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يَمْنَعَنَّكُمْ أَذَانُ بِلَالٍ مِنَ السُّحُورِ، فَإِنَّ فِي بَصَرِهِ شَيْئًا."],"takhrij":"صحيح: رواه أحمد (12428)، وأبو يعلى (2967)، والبزارـ كشف الأستار (982) ـ كلّهم من طريق محمد بن بِشْر، حدّثنا سعيد، عن قتادة، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب استحباب تأخير السحور إلى أن يتبين الفجر الصادق","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (12428), Abu Yaʿla (2917), and al-Bazzar in Kashf al-Astar (982).","chapter_en":"The recommendation of delaying the pre-dawn meal until true dawn becomes clear","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ said: “Let not Bilal’s call to prayer prevent you from the pre-dawn meal, for there is some weakness in his sight.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (12428)، وأبو يعلى (2967)، والبزار في كشف الأستار (982)."},{"num":4368,"demo":false,"sanad":"","matn":["عن أُنيسة بنت حبيب خُبَيْبٍ، قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا أَذَّنَ ابْنُ أُمِّ مَكْتُومٍ فَكُلُوا وَاشْرَبُوا، وَإِذَا أَذَّنَ بِلَالٌ فَلَا تَأْكُلُوا وَلَا تَشْرَبُوا، فَإِنْ كَانَتِ الْوَاحِدَةُ مِنَّا لَيَبْقَى عَلَيْهَا الشَّيْءُ مِنْ سَحُورِهَا فَتَقُولُ لِبِلَالٍ: أَمْهِلْ حَتَّى أَفْرَغَ مِنْ سَحُورِي."],"takhrij":"صحيح: رواه النسائيّ (640)، وابن خزيمة (404)، وابن حبان (3474)، وأحمد (27440) كلّهم من طريق هشيم، قال: حدّثنا منصور بن زاذان، عن خبيب بن عبدالرحمن، عن عمّته أنيسة بنت حبيب، فذكرته.","grade":"صحيح","chapter_ar":"باب استحباب تأخير السحور إلى أن يتبين الفجر الصادق","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasa’i (640), Ibn Khuzaymah (404), Ibn Hibban (3474), and Ahmad (27440).","chapter_en":"The recommendation of delaying the pre-dawn meal until true dawn becomes clear","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Unaysah bint Habib said: The Messenger of Allah ﷺ said: “When Ibn Umm Maktum gives the call to prayer, then eat and drink, and when Bilal gives the call, then do not eat or drink.” One of us would still have something left from her pre-dawn meal, so we would say to Bilal: Wait until I finish my pre-dawn meal."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (640)، وابن خزيمة (404)، وابن حبان (3474)، وأحمد (27440)."},{"num":4369,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ، رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنْتُ أَتَسَحَّرُ فِي أَهْلِي، ثُمَّ تَكُونُ سُرْعَتِي أَنْ أُدْرِكَ السُّجُودَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه البخاريّ في الصوم (1920) عن محمد بن عبيدالله، حدّثنا عبد العزيز بن أبي حازم، عن أبيه، عن حازم، عن سهل بن سعد، فذكره.","grade":"صحيح","chapter_ar":"باب استحباب تأخير السحور إلى أن يتبين الفجر الصادق","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (1920).","chapter_en":"The recommendation of delaying the pre-dawn meal until true dawn becomes clear","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Sahl ibn Saʿd said: I used to eat the pre-dawn meal with my family, then I would hurry so that I could catch the prostration with the Messenger of Allah ﷺ."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1920)."},{"num":4370,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:  تَسَحَّرْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قُمْنَا إِلَى الصَّلَاةِ، قُلْتُ: كَمْ كَانَ قَدْرُ مَا بَيْنَهُمَا؟ قَالَ: خَمْسِينَ آيَةً."],"takhrij":"متفق عليه: رواه البخاريّ في الصوم (1921)، ومسلم في الصيام (1097) كلاهما من طريق هشام (هو الدستوائي)، حدّثنا قتادة، عن أنس، عن زيد بن ثابت، فذكره. واللفظ لمسلم. ولفظ البخاري: قال: كم كان بين الأذان والسَّحور؟ قال: قدرُ خمسين آية .","grade":"متفق عليه","chapter_ar":"باب استحباب تأخير السحور إلى أن يتبين الفجر الصادق","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1921) and Muslim (1097). This is the wording of Muslim.","chapter_en":"The recommendation of delaying the pre-dawn meal until true dawn becomes clear","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Zayd ibn Thabit said: We took the pre-dawn meal with the Messenger of Allah ﷺ, then we stood for the prayer. I said: How much time was there between the two? He said: The amount of fifty verses."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1921)، ومسلم (1097). واللفظ لمسلم."},{"num":4371,"demo":false,"sanad":"","matn":["عَنْ عَدِيِّ بْنِ حَاتِمٍ، قَالَ: لَمَّا نَزَلَتْ: ﴿حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ مِنَ الْفَجْرِ﴾ [سورة الْبَقَرَةِ: 187] عَمَدْتُ إِلَى عِقَالٍ أَسْوَدَ وَإِلَى عِقَالٍ أَبْيَضَ، فجعلتها تَحْتَ وِسَادَتِي، فَجَعَلْتُ أَنْظُرُ فِي اللَّيْلِ فَلاَ يَسْتَبِينُ لِي، فَغَدَوْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْتُ لَهُ ذَلِكَ فَقَالَ: إِنَّمَا ذَلِكَ سَوَادُ اللَّيْلِ وَبَيَاضُ النَّهَارِ .","وفي رواية: إِنِّي أَجْعَلُ تَحْتَ وِسَادَتِي عِقَالَيْنِ، عِقَالًا أَبْيَضَ وَعِقَالًا أَسْوَدَ. أَعْرِفُ اللَّيْلَ مِنَ النَّهَارِ. فَقَالَ رَسُولُ اللهِ صلى الله عليه وسلم: إِنَّ وِسَادَتَكَ لَعَرِيضٌ! إِنَّمَا هُوَ سَوَادُ اللَّيْلِ وَبَيَاضُ النَّهَارِ .."],"takhrij":"متفق عليه: رواه البخاريّ في الصوم (1916)، ومسلم في الصيام (1090) كلاهما من حديث حصين بن عبدالرحمن، عن الشعبي، عن عدي ابن حاتم، فذكره. والرواية الثانية عند مسلم.","grade":"متفق عليه","chapter_ar":"باب استحباب تأخير السحور إلى أن يتبين الفجر الصادق","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1916) and Muslim (1090).","chapter_en":"The recommendation of delaying the pre-dawn meal until true dawn becomes clear","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["ʿAdi ibn Hatim said: When the verse was revealed: “Until the white thread becomes distinct to you from the black thread of dawn” [al-Baqarah: 187], I took a black rope and a white rope and placed them under my pillow. I kept looking at them during the night, but I could not distinguish between them. So in the morning I went to the Messenger of Allah ﷺ and mentioned that to him, and he said: “What is meant is only the blackness of the night and the whiteness of the day.” In another wording: “I place beneath my pillow two ropes, one white and one black, so that I may know the night from the day.” The Messenger of Allah ﷺ said: “Your pillow must be very wide! It only means the blackness of the night and the whiteness of the day.”","And in the narration of Abu Dawud (2349): “The Messenger of Allah ﷺ laughed and said: Your pillow…”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1916)، ومسلم (1090). والرواية الثانية عند مسلم."},{"num":4372,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْفَجْرُ فَجْرَانِ: فَأَمَّا الْفَجْرُ الَّذِي يَكُونُ كَذَنَبِ السَّرْحَانِ فَلَا تَحِلُّ الصَّلَاةُ فِيهِ، وَلَا يَحْرُمُ الطَّعَامُ، وَأَمَّا الَّذِي يَذْهَبُ مُسْتَطِيلًا فِي الْأُفُقِ فَإِنَّهُ يُحِلُّ الصَّلَاةَ، وَيُحَرِّمُ الطَّعَامَ."],"takhrij":"صحيح: رواه الحاكم (688) عن أبي بكر محمد بن أحمد بن حاتم الداربردي بمرو، ثنا عبدالله بن روح المدائني، ثنا يزيد بن هارون، أنبأنا ابن أبي ذئب، عن الحارث بن عبدالرحمن، عن محمد بن عبدالرحمن بن ثوبان، عن جابر، فذكره.","grade":"صحيح","chapter_ar":"باب استحباب تأخير السحور إلى أن يتبين الفجر الصادق","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Hakim (688).","chapter_en":"The recommendation of delaying the pre-dawn meal until true dawn becomes clear","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: The Messenger of Allah ﷺ said: “Dawn is of two kinds. As for the dawn that looks like the tail of a wolf, prayer is not allowed at that time, nor is food made unlawful. But as for the dawn that spreads across the horizon, that is what makes prayer lawful and food unlawful.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الحاكم (688)."},{"num":4373,"demo":false,"sanad":"","matn":["عن قيس بْنِ طَلْقٍ، عَنْ أَبِيهِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كُلُوا وَاشْرَبُوا، وَلاَ يَهِيدَنَّكُمُ السَّاطِعُ الْمُصْعِدُ، فَكُلُوا وَاشْرَبُوا حَتَّى يَعْتَرِضَ لَكُمُ الأَحْمَرُ."],"takhrij":"حسن: رواه أبو داود (2348)، والترمذي (705) وابن خزيمة (1930) كلهم من طريق ملازم بن عمرو، عن عبدالله بن النعمان، حدّثني قيس بن طلق، عن أبيه، فذكره.","grade":"حسن","chapter_ar":"باب استحباب تأخير السحور إلى أن يتبين الفجر الصادق","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (2348), al-Tirmidhi (705), and authenticated by Ibn Khuzaymah (1930). Al-Tirmidhi said: Hasan Gharib.","chapter_en":"The recommendation of delaying the pre-dawn meal until true dawn becomes clear","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Qays ibn Talq reported from his father that the Messenger of Allah ﷺ said: “Eat and drink, and do not let the rising vertical light alarm you. Eat and drink until the red light spreads across before you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2348)، والترمذي (705)، وصححه ابن خزيمة (1930). قال الترمذي: حسن غريب."},{"num":4374,"demo":false,"sanad":"","matn":["عَنْ زِرِّ بْنِ حُبَيْشٍ، قَالَ: تَسَحَّرْتُ ثُمَّ انْطَلَقْتُ إِلَى الْمَسْجِدِ، فَمَرَرْتُ بِمَنْزِلِ حُذَيْفَةَ بْنِ الْيَمَانِ فَدَخَلْتُ عَلَيْهِ، فَأَمَرَ بِلَقْحَةٍ فَحُلِبَتْ، وَبِقِدْرٍ فَسُخِّنَتْ، ثُمَّ قَالَ: ادْنُ فَكُلْ، فَقُلْتُ: إِنِّي أُرِيدُ الصَّوْمَ، فَقَالَ: وَأَنَا أُرِيدُ الصَّوْمَ، فَأَكَلْنَا وَشَرِبْنَا، ثُمَّ أَتَيْنَا الْمَسْجِدَ، فَأُقِيمَتِ الصَّلَاةُ، ثُمَّ قَالَ حُذَيْفَةُ: هَكَذَا فَعَلَ بِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قُلْتُ: أَبَعْدَ الصُّبْحِ؟ قَالَ: نَعَمْ، هُوَ الصُّبْحُ غَيْرَ أَنْ لَمْ تَطْلُعِ الشَّمْسُ، قَالَ: وَبَيْنَ بَيْتِ حُذَيْفَةَ، وَبَيْنَ الْمَسْجِدِ كَمَا بَيْنَ مَسْجِدِ ثَابِتٍ وَبُسْتَانِ حَوْطٍ، وَقَدْ قَالَ حَمَّادٌ أَيْضًا، وَقَالَ حُذَيْفَةُ: هَكَذَا صَنَعْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَصَنَعَ بِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: رواه الإمام أحمد (23361) من طريق حماد بن سلمة واللفظ له ـ، والنسائي (2152) من طريق سفيان، وابن ماجه (1695) من طريق أبي بكر ابن عياش، كلّهم عن عاصم بن بهدلة، عن زرّ بن حبيش، فذكره مختصراً.","grade":"حسن","chapter_ar":"باب استحباب تأخير السحور إلى أن يتبين الفجر الصادق","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (23361), al-Nasa’i (2152), and Ibn Majah (1695).","chapter_en":"The recommendation of delaying the pre-dawn meal until true dawn becomes clear","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Zir ibn Hubaysh said: I ate the pre-dawn meal, then I set out for the mosque. On the way I passed by the house of Hudhayfah ibn al-Yaman and entered upon him. He ordered that a she-camel be milked and that a cooking pot be heated, then he said: Come near and eat. I said: I intend to fast. He said: I also intend to fast. So we ate and drank, then we went to the mosque, and the prayer was called to begin. Then Hudhayfah said: “This is how the Messenger of Allah ﷺ did with me.” I said: After dawn? He said: Yes, it was dawn, except that the sun had not yet risen. And the distance between Hudhayfah’s house and the mosque was like the distance between Thabit’s mosque and the garden of Hawt. Hammad also said: Hudhayfah said: “This is how I did with the Prophet ﷺ, and how the Prophet ﷺ did with me.”"]},"buhuth":{"en":["Al-Nasa’i said — as quoted in Tuhfat al-Ashraf (3/32):","“We do not know anyone who raised it to the Prophet except ʿAsim. If its attribution is authentic, then its meaning is that it was near daytime, like the saying of Allah Most High: ‘When you divorce women and they have reached their term’ [al-Baqarah: 231], meaning when they are close to reaching it; and like a person saying: ‘We reached the destination,’ meaning we came near it.” End quote."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (23361)، والنسائي (2152)، وابن ماجه (1695)."},{"num":4375,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا سَمِعَ أَحَدُكُمُ النِّدَاءَ، وَالإِنَاءُ عَلَى يَدِهِ فَلاَ يَضَعْهُ حَتَّى يَقْضِيَ حَاجَتَهُ مِنْهُ."],"takhrij":"حسن: رواه أبو داود (2350) والدارقطني في سننه(2182)، والحاكم (1552) كلهم عن عبدالأعلى بن حماد، ثنا حماد، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب الرجل يسمع النداء والإناء في يده","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (2350), and from him al-Daraqutni (2182) and al-Hakim (1552).","chapter_en":"A man hears the call while the vessel is in his hand","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":24,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “If one of you hears the call while the vessel is in his hand, then he should not put it down until he finishes what he needs from it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2350)، وعنه الدارقطني (2182)، والحاكم (1552)."},{"num":4376,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ يَزَالُ النَّاسُ بِخَيْرٍ مَا عَجَّلُوا الْفِطْرَ."],"takhrij":"متفق عليه: رواه مالك في الصيام (6) عن أبي حازم بن دينار، عن سهل ابن سعد، فذكره. ورواه البخاريّ في الصوم (1957) عن عبدالله بن يوسف، أخبرنا مالك، به، مثله. ورواه مسلم (1098) من حديث يعقوب وسفيان كلاهما عن أبي حازم به، مثله.","grade":"متفق عليه","chapter_ar":"باب استحباب تعجيل الإفطار","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (6), al-Bukhari (1957), and Muslim (1098).","chapter_en":"The recommendation to hasten the breaking of the fast","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Sahl ibn Saʿd al-Saʿidi reported that the Messenger of Allah ﷺ said: “The people will remain upon goodness so long as they hasten the breaking of the fast.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه مالك (6)، والبخاري (1957)، ومسلم (1098)."},{"num":4377,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تَزَالُ أُمَّتِي عَلَى سُنَّتِي مَا لَمْ تَنْتَظِرْ بِفِطْرِهَا النُّجُومَ.","قَالَ: وَكَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا كَانَ صَائِمًا أَمَرَ رَجُلًا، فَأَوْفَى عَلَى شَيْءٍ، فَإِذَا قَالَ: غَابَتِ الشَّمْسُ أَفْطَرَ."],"takhrij":"صحيح: رواه ابن خزيمة (2061) وعنه ابن حبان (3510)، والحاكم (1584) كلّهم من حديث محمد بن أبي صفوان الثقفي، حدّثنا عبدالرحمن ابن مهدي، حدّثنا سفيان، عن أبي حازم، عن سهل بن سعد، فذكره.","grade":"صحيح","chapter_ar":"باب استحباب تعجيل الإفطار","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Khuzaymah (2061), and from him Ibn Hibban (3510), and al-Hakim (1584).","chapter_en":"The recommendation to hasten the breaking of the fast","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Sahl ibn Saʿd said: The Messenger of Allah ﷺ said: “My nation will remain upon my Sunnah so long as they do not wait for the stars before breaking their fast.” He said: When the Prophet ﷺ was fasting, he would instruct a man to climb up to a high place, and when he said, “The sun has set,” he would break his fast."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن خزيمة (2061)، وعنه ابن حبان (3510)، والحاكم (1584)."},{"num":4378,"demo":false,"sanad":"","matn":["عَنْ أَبِي عَطِيَّةَ، قَالَ:  دَخَلْتُ أَنَا وَمَسْرُوقٌ عَلَى عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا. فَقَالَ لَهَا مَسْرُوقٌ: رَجُلَانِ مِنْ أَصْحَابِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كِلَاهُمَا لَا يَأْلُو عَنِ الْخَيْرِ: أَحَدُهُمَا يُعَجِّلُ الْمَغْرِبَ، وَالْإِفْطَارَ، وَالْآخَرُ يُؤَخِّرُ الْمَغْرِبَ، وَالْإِفْطَارَ، فَقَالَتْ: مَنْ يُعَجِّلُ الْمَغْرِبَ وَالْإِفْطَارَ؟ قَالَ: عَبْدُ اللَّهِ فَقَالَتْ: هَكَذَا كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُ."],"takhrij":"صحيح: رواه مسلم في الصيام (1099) من طريق عُمارة بن عُمير، عن أبي عطية (هو الوادعي مختلف في اسمه)، به، فذكره.","grade":"صحيح","chapter_ar":"باب استحباب تعجيل الإفطار","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1099).","chapter_en":"The recommendation to hasten the breaking of the fast","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Abu ʿAtiyyah said: Masruq and I entered upon ʿA’ishah, may Allah be pleased with her. Masruq said to her: “There are two men among the Companions of Muhammad ﷺ, and neither of them falls short in goodness. One of them hastens the sunset prayer and the breaking of the fast, while the other delays the sunset prayer and the breaking of the fast.” She said: “Which one hastens the sunset prayer and the breaking of the fast?” He said: “ʿAbdullah” — meaning Ibn Masʿud. She said: “This is how the Messenger of Allah ﷺ used to do.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1099)."},{"num":4379,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ يَزَالُ الدِّينُ ظَاهِرًا مَا عَجَّلَ النَّاسُ الْفِطْرَ؛ لأَنَّ الْيَهُودَ وَالنَّصَارَى يُؤَخِّرُونَ."],"takhrij":"حسن: رواه أبو داود (2353)، وابن ماجه (1698) كلاهما من حديث محمد بن عمرو، عن أبي سلمة، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب استحباب تعجيل الإفطار","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (2353) and Ibn Majah (1698).","chapter_en":"The recommendation to hasten the breaking of the fast","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “The religion will remain manifest so long as people hasten the breaking of the fast, because the Jews and Christians delay it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2353)، وابن ماجه (1698)."},{"num":4380,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن أَبِي أَوْفَى، قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ وَهُوَ صَائِمٌ، فَلَمَّا غَابَتِ الشَّمْسُ قَالَ لِبَعْضِ الْقَوْمِ: يَا فُلاَنُ، قمْ فَاجْدَحْ لَنَا، فَقَالَ: يَا رَسُولَ اللَّهِ لَوْ أَمْسَيْتَ. قَالَ: انْزِلْ فَاجْدَحْ لَنَا. قَالَ: يَا رَسُولَ اللَّهِ فَلَوْ أَمْسَيْتَ. قَالَ: انْزِلْ فَاجْدَحْ لَنَا. قَالَ: إنّ عَلَيْكَ نَهَارًا، قـال: انْزِلْ فَاجْدَحْ لَنَا. فَنَزَلَ فَجَدَحَ لَهُمْ فَشَرِبَ النبيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَالَ: إِذَا رَأَيْتُمُ اللَّيْلَ قَدْ أَقْبَلَ مِنْ هَاهُنَا فَقَدْ أَفْطَرَ الصَّائِمُ."],"takhrij":"متفق عليه: رواه البخاريّ في الصوم (1955)، ومسلم في الصيام (1101) كلاهما من طريق أبي إسحاق سليمان الشيبانيّ، عن عبدالله بن أبي أوفى، به. واللفظ للبخاري، ولفظ مسلم نحوه.","grade":"متفق عليه","chapter_ar":"باب متى يحل فطر الصائم؟","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1955) and Muslim (1101). This is the wording of al-Bukhari.","chapter_en":"When does it become lawful for the fasting person to break the fast?","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":26,"content":{"translation":{"en":["ʿAbdullah ibn Abi Awfa said: We were with the Messenger of Allah ﷺ on a journey while he was fasting. When the sun set, he said to one of the people: “O so-and-so, get down and prepare a drink for us.” He said: “O Messenger of Allah, if only you would wait until evening becomes darker.” He said: “Get down and prepare a drink for us.” He said: “O Messenger of Allah, if only you would wait until evening becomes darker.” He said: “Get down and prepare a drink for us.” He said: “There is still daylight upon you.” He said: “Get down and prepare a drink for us.” So he got down and prepared it for them, and the Prophet ﷺ drank, then said: “When you see the night coming from this direction, then the fasting person has broken his fast.”"]},"buhuth":{"en":["His words, “prepare a drink for us,” mean to stir roasted grain flour with water and mix it until it becomes even. The same can be done with milk and similar things. The mijdah is a stick with a curved head used to stir drinks, and sometimes it has three prongs. See al-Nihayah (1/700).","The name of the unnamed Companion is Bilal, as mentioned in some narrations."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1955)، ومسلم (1101)، واللفظ للبخاري."},{"num":4381,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بن الْخَطَّابِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِذَا أَقْبَلَ اللَّيْلُ مِنْ هَاهُنَا، وَأَدْبَرَ النَّهَارُ مِنْ هَاهُنَا، وَغَرَبَتِ الشَّمْسُ فقـد أَفْطَرَ الصَّائِمُ ."],"takhrij":"متفق عليه: رواه البخاري في الصوم (1954)، ومسلم في الصيام (1100) كلاهما من طريق هشام بن عروة، قال: سمعت أبي يقول: سمعت عاصم بن عمر بن الخطاب، عن أبيه رضي الله عنه، فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب متى يحل فطر الصائم؟","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1954) and Muslim (1100). This is the wording of al-Bukhari.","chapter_en":"When does it become lawful for the fasting person to break the fast?","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":26,"content":{"translation":{"en":["ʿUmar ibn al-Khattab said: The Messenger of Allah ﷺ said: “When the night comes from this direction, and the day departs from this direction, and the sun has set, then the fasting person has broken the fast.”"]},"buhuth":{"en":["His words, “then the fasting person has broken the fast,” mean that he has come under the ruling of one whose fast is over, even if he has not yet eaten. It was also said that it means the time of breaking the fast has begun, and it has become permissible for him to break it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1954)، ومسلم (1100)، واللفظ للبخاري."},{"num":4382,"demo":false,"sanad":"","matn":["عَنْ سَلْمَانَ بْنِ عَامِرٍ، عَمِّهَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا كَانَ أَحَدُكُمْ صَائِمًا فَلْيُفْطِرْ عَلَى التَّمْرِ، فَإِنْ لَمْ يَجِدِ التَّمْرَ فَعَلَى الْمَاءِ، فَإِنَّ الْمَاءَ طَهُورٌ."],"takhrij":"حسن: رواه أبو داود (2355)، والترمذي (695)، وابن ماجه (1699)، وأحمد (16228)، وصحّحه ابن خزيمة (2067)، والحاكم (1575) كلّهم من طرق عن عاصم الأحول، عن حفصة بنت سيرين، عن الرباب، عن عمّها سلمان بن عامر، فذكره.","grade":"حسن","chapter_ar":"باب ما يستحب أن يفطر عليه","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (2355), al-Tirmidhi (695), who graded it Hasan, Ibn Majah (1699), and Ahmad (16228).","chapter_en":"What it is recommended to break the fast with","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":27,"content":{"translation":{"en":["Salman ibn ʿAmir al-Dabbi said: The Messenger of Allah ﷺ said: “When one of you is fasting, let him break his fast with dates. If he does not find dates, then with water, for water is purifying.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2355)، والترمذي (695) وحسنه، وابن ماجه (1699)، وأحمد (16228)."},{"num":4383,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ، يَقُولُ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُفْطِرُ عَلَى رُطَبَاتٍ قَبْلَ أَنْ يُصَلِّيَ، فَإِنْ لَمْ تَكُنْ رُطَبَاتٌ فَعَلَى تَمَرَاتٍ، فَإِنْ لَمْ تَكُنْ حَسَا حَسَوَاتٍ مِنْ مَاءٍ."],"takhrij":"صحيح: رواه أبو داود (2356) وعنه الدارقطني (2278) عن الإمام أحمد وهو في مسنده ahmad(12676)، والترمذي (696) والدارقطني (2277)، والبيهقي (4/239) من أوجه آخر أيضاً ـ كلّهم من حديث عبد الرزاق، حدثنا جعفر بن سليمان، حدثنا ثابت البناني، أنه سمع أنس بن مالك، فذكره.","grade":"صحيح","chapter_ar":"باب ما يستحب أن يفطر عليه","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (2356), al-Daraqutni (2278), Ahmad (12676), and al-Tirmidhi (696), who graded it Hasan.","chapter_en":"What it is recommended to break the fast with","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":27,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ used to break his fast with fresh dates before he prayed. If there were no fresh dates, then with dry dates, and if there were no dry dates, he would take a few sips of water."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2356)، والدارقطني (2278)، وأحمد (12676)، والترمذي (696) وحسنه."},{"num":4384,"demo":false,"sanad":"","matn":["عن أنس، أنَّ النبيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَبْدَأُ إذَا أفْطَرَ بالتّمرِ."],"takhrij":"صحيح:  رواه النسائي في الكبرى (3304) عن موسى بن حزام الترمذي، قال: أخبرنا يحيى –وهو ابن آدم-، قال: حدثنا يزيد بن عبد العزيز، عن رَقبة، عن بُريد بن أبي مريم، عن أنس، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما يستحب أن يفطر عليه","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasa’i in al-Kubra (3304).","chapter_en":"What it is recommended to break the fast with","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":27,"content":{"translation":{"en":["Anas reported that the Prophet ﷺ used to begin with dates when he broke his fast."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي في الكبرى (3304)."},{"num":4385,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: مَا رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَطُّ صَلَّى صَلَاةَ الْمَغْرِبِ حَتَّى يُفْطِرَ، وَلَوْ كَانَ عَلَى شَرْبَةٍ مِنْ مَاءٍ."],"takhrij":"صحيح: رواه أبو يعلى (3792) وعنه ابن حبان (3504) عن أبي بكر بن أبي شيبة، حدّثنا حسين بن علي الجعفي، عن زائدة، عن حُميد، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب استحباب الإفطار قبل أداء صلاة المغرب","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Abu Yaʿla (3792) and Ibn Hibban (3504).","chapter_en":"The recommendation to break the fast before performing the sunset prayer","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":28,"content":{"translation":{"en":["Anas said: I never saw the Messenger of Allah ﷺ ever pray the sunset prayer before breaking his fast, even if only with a drink of water."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو يعلى (3792)، وابن حبان (3504)."},{"num":4386,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ فَطَّرَ صَائِمًا كَانَ لَهُ مِثْلُ أَجْرِهِ، غَيْرَ أَنَّهُ لاَ يَنْقُصُ مِنْ أَجْرِ الصَّائِمِ شَيْئًا."],"takhrij":"صحيح: رواه الترمذي (807)، وابن ماجه (1746) وصحّحه ابن خزيمة (2064)، وابن حبان (3429) كلّهم من حديث عبد الملك بن أبي سليمان، قال: حدثني عطاء بن أبي رباح، عن زيد بن خالد الجهني، فذكره.","grade":"صحيح","chapter_ar":"باب في فضل من أفطر صائماً","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Tirmidhi (807), Ibn Majah (1746), and authenticated by Ibn Khuzaymah (2064) and Ibn Hibban (3429).","chapter_en":"The virtue of one who gives food to a fasting person to break the fast","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":29,"content":{"translation":{"en":["Zayd ibn Khalid al-Juhani said: The Messenger of Allah ﷺ said: “Whoever gives a fasting person food with which to break his fast will have a reward equal to his, without that decreasing anything from the reward of the fasting person.”"]},"buhuth":{"en":["Ahmad also narrated it (17033) and added: “And whoever equips a fighter in the path of Allah, or looks after his family in his absence, will be written a reward equal to his, without that decreasing anything from the reward of the fighter.”","Al-Tirmidhi said: Hasan Sahih."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (807)، وابن ماجه (1746)، وصححه ابن خزيمة (2064)، وابن حبان (3429)."},{"num":4387,"demo":false,"sanad":"","matn":["عن مَرْوَانَ ـ يَعْنِي ابْنَ سالم المقنع ـ قَالَ: رَأَيْتُ ابْنَ عُمَرَ يَقْبِضُ عَلَى لِحْيَتِهِ فَيَقْطَعُ مَا زَادَ عَلَى الْكَفِّ، وَقَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَفْطَرَ قَالَ: ذَهَبَ الظَّمَأُ وَابْتَلَّتِ الْعُرُوقُ، وَثَبَتَ الأَجْرُ إِنْ شَاءَ اللَّهُ."],"takhrij":"حسن: رواه أبو داود (2357)، والنسائي في \"الكبرى\" (3315) كلاهما من حديث علي بن حسن، أخبرنا الحسين بن واقد، أخبرنا مروان المقنع فذكره.","grade":"حسن","chapter_ar":"باب ما يقوله عند الإفطار","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (2357) and al-Nasa’i in al-Kubra (3315).","chapter_en":"What a person says when breaking the fast","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["Marwan ibn Salim al-Muqannaʿ said: I saw Ibn ʿUmar grasp his beard and cut what exceeded a handful, and he said: When the Messenger of Allah ﷺ broke his fast, he would say: “The thirst has gone, the veins are moistened, and the reward is confirmed, if Allah wills.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11118],"tks":"حسن: رواه أبو داود (2357)، والنسائي في الكبرى (3315)."},{"num":4388,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَفْطَرَ عِنْدَ قَوْمٍ دَعَا لَهُمْ، فَقَالَ: أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ ."],"takhrij":"حسن: رواه ابن السني في عمل اليوم والليلة (482)، والطبراني في الدّعاء (925) كلاهما من حديث عمران القطان، عن قتادة، عن أنس، فذكره.","grade":"حسن","chapter_ar":"باب ما يقول من أفطر عند قوم","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ibn al-Sunni in ʿAmal al-Yawm wa al-Laylah (482) and al-Tabarani in al-Duʿa’ (925).","chapter_en":"What one says when he breaks his fast with a people","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["Anas ibn Malik said: When the Messenger of Allah ﷺ broke his fast with a people, he would supplicate for them, saying: “May the fasting people break their fast with you, may the righteous eat your food, and may the angels pray for you.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11119],"tks":"حسن: رواه ابن السني في عمل اليوم والليلة (482)، والطبراني في الدعاء (925)."},{"num":4389,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ الباهلي قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: بَيْنَا أَنَا نَائِمٌ أَتَانِي رَجُلَانِ، فَأَخَذَا بضَبْعي، فَأَتَيَا بِي جَبَلًا وَعْراً، فَقَالَا: اصْعَدْ. فَقُلْتُ: إِنِّي لَا أُطِيقُهُ. فَقَالَا: إِنَّا سَنُسَهِّلُهُ لَكَ. فَصَعِدْتُ حَتَّى إِذَا كنتُ فِي سَوَاءِ الْجَبَلِ إِذَا بِأَصْوَاتٍ شَدِيدَةٍ. قُلْتُ: مَا هَذِهِ الْأَصْوَاتُ؟ قَالُوا: هَذَا عُوَاءُ أَهْلِ النَّارِ، ثُمَّ انْطُلِقَ بِي، فَإِذَا أَنَا بِقَوْمٍ مُعَلَّقِينَ بِعَرَاقِيبِهِمْ مُشَقَّقَةٍ أَشْدَاقُهُمْ تَسِيلُ أَشْدَاقُهُمْ دماً. قَالَ: قُلْتُ: مَنْ هَؤُلَاءِ؟ قَالَا: الَّذِينَ يُفْطِرُونَ قَبْلَ تَحِلَّةِ صَوْمِهِمْ الحديث."],"takhrij":"صحيح: رواه ابن خزيمة (1986) وعنه ابن حبان (7491)، والحاكم (1568)، وعنه البيهقي (8006) كلّهم من حديث بشر بن بكر، حدثني ابن جابر، حدثني سليم بن عامر، حدثني أبو أمامة الباهلي، فذكر الحديث في سياق أطول وهو مذكور في موضعه. قال الحاكم: صحيح على شرط مسلم.","grade":"صحيح","chapter_ar":"باب الترهيب من الإفطار قبل غروب الشمس","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Khuzaymah (1986), Ibn Ḥibbān (7491), al-Ḥākim (1568), and al-Bayhaqī (4/216).","chapter_en":"Warning against breaking the fast before sunset","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":32,"content":{"translation":{"en":["Abū Umāmah al-Bāhilī said: I heard the Messenger of Allah ﷺ say: “While I was sleeping, two men came to me and took hold of my upper arms. They brought me to a rugged mountain and said: ‘Climb.’ I said: ‘I cannot manage it.’ They said: ‘We will make it easy for you.’ So I climbed. When I reached the middle of the mountain, I suddenly heard loud cries. I asked: ‘What are these sounds?’ They said: ‘This is the howling of the people of the Fire.’ Then I was taken onward, and I saw people hanging by their Achilles tendons, with the sides of their mouths torn open and blood flowing from them. I asked: ‘Who are these?’ They replied: ‘These are the people who break their fast before the lawful time for ending their fast.’”"]},"buhuth":{"en":["“Before the lawful time for ending their fast” means that they break their fast before the proper time of ifṭār."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن خزيمة (1986)، وابن حبان (7491)، والحاكم (1568)، والبيهقي (8006)."},{"num":4390,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثَلاَثَةٌ لاَ تُرَدُّ دَعْوَتُهُمُ: الإِمَامُ الْعَادِلُ، وَالصَّائِمُ حَتَّى يُفْطِرَ، وَدَعْوَةُ الْمَظْلُومِ يَرْفَعُهَا اللَّهُ دُونَ الْغَمَامِ يَوْمَ الْقِيَامَةِ، وَتُفْتَحُ لَهَا أَبْوَابُ السَّمَاءِ. وَيَقُولُ: بِعِزَّتِي لأَنْصُرَنَّكِ وَلَوْ بَعْدَ حِينٍ."],"takhrij":"حسن: رواه ابن ماجه (1752)، والترمذي (3598)، وأحمد (10183). وصحّحه ابن خزيمة (1901)، وابن حبان (3428).كلّهم من حديث سعدان الجهني، عن سعد أبي مجاهد الطائيّ ـ وكان ثقة ـ، عن أبي مدلة ـ وكان ثقة ـ، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب الترهيب من الإفطار قبل غروب الشمس","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ibn Majah (1752), al-Tirmidhi (3598), Ahmad (9743), and authenticated by Ibn Khuzaymah (1901).","chapter_en":"Warning against breaking the fast before sunset","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":32,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “There are three whose supplication is not rejected: the just ruler, the fasting person until he breaks his fast, and the supplication of the oppressed. Allah raises it above the clouds on the Day of Resurrection, the gates of heaven are opened for it, and He says: By My might, I will surely support you, even if after some time.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10941],"tks":"حسن: رواه ابن ماجه (1752)، والترمذي (3598)، وأحمد (10183)، وصححه ابن خزيمة (1901)."},{"num":4391,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثَلَاثُ دَعَوَاتٍ لَا تُرَدُّ، دَعْوَةُ الْوَالِدِ، وَدَعْوَةُ الصَّائِمِ، وَدَعْوَةُ الْمُسَافِرِ."],"takhrij":"حسن: رواه البيهقي (6392)، والضياء في المختارة (2057) كلاهما من طريق أبي العباس محمد بن يعقوب، حدّثنا إبراهيم بن بكر المروزي، حدثنا السهمي عبدالله بن بكر، حدثنا حميد الطويل، عن أنس بن مالك، فذكره.","grade":"حسن","chapter_ar":"باب الترهيب من الإفطار قبل غروب الشمس","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Bayhaqi (3/345) and al-Diya’ in al-Mukhtarah (2057).","chapter_en":"Warning against breaking the fast before sunset","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في وجوب الصيام وفضله وأحكامه","group_en":"Collected sections on the obligation of fasting, its virtue, and its rulings","part_no":15,"group_no":1,"chapter_no":32,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ said: “Three supplications are not rejected: the supplication of a parent, the supplication of the fasting person, and the supplication of the traveler.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10942],"tks":"حسن: رواه البيهقي (6392)، والضياء في المختارة (2057)."},{"num":4392,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : قَالَ اللَّهُ: كلُّ عَمَلِ ابْنِ آدَمَ لَهُ إلاّ الصِّيَامَ فَإِنَّهُ لِي وَأَنَا أَجْزِي بِهِ، وَالصِّيَامُ جُنّة، وَإِذَا كَانَ يَوْمُ صَوْمِ أَحَدِكُمْ فَلاَ يَرْفُثْ وَلاَ يَصْخَبْ، فإنْ سابَّهُ أحدٌ أَوْ قَاتَلَهُ فَلْيَقُلْ: إنّي امْرؤٌ صَائِمٌ. وَالَّذِي نفسُ مُحَمَّدٍ بِيَدِهِ لَخلُوفُ فمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ. لِلصَّائِمِ فَرْحَتَانِ يَفْرَحُهُمَا: إِذَا أَفْطَرَ فَرِحَ، وَإِذَا لَقِيَ ربَّهُ فَرِحَ بِصَوْمِهِ ."],"takhrij":"متفق عليه: رواه البخاريّ في الصوم (1904)، ومسلم في الصيام (1151: 163) كلاهما من طريق ابن جريج، أخبرني عطاء (هو ابن أبي رباح)، عن أبي صالح الزّيّات، أنه سمع أبا هريرة رضي الله عنه يقول (فذكره). واللفظ للبخاريّ، ولفظ مسلم قريب منه.","grade":"متفق عليه","chapter_ar":"باب الترغيب في الصوم مطلقاً وما جاء في فضله","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1904) and Muslim (1151 no. 163). This is the wording of al-Bukhari.","chapter_en":"Encouragement toward fasting in general and what has come regarding its virtue","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في صيام التطوع والترغيب فيه","group_en":"Collection of reports on voluntary fasting and encouragement toward it","part_no":15,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Allah said: Every deed of the son of Adam is for him except fasting. It is for Me, and I alone reward for it. Fasting is a shield. So when it is the day of fasting for one of you, he should not speak obscenely and he should not raise his voice in argument. If someone insults him or fights him, let him say: I am a fasting person. By the One in whose hand is the soul of Muhammad, the change in the smell of the fasting person’s mouth is more pleasant to Allah than the fragrance of musk. The fasting person has two joys that delight him: when he breaks his fast, he rejoices, and when he meets his Lord, he rejoices in his fasting.”"]},"buhuth":{"en":["His saying, “Fasting is a shield,” with the letter jim pronounced with dammah, means it is a covering and protection from sins in this world and from the Fire in the Hereafter.","His saying, “he should not speak obscenely,” means he should avoid indecent speech. The term can also be used for sexual relations and what leads to them.","His saying, “and he should not raise his voice in argument,” and in Muslim’s wording, “and he should not shout,” carries the same meaning; it refers to quarreling and loud disputation.","His saying, “the change in the smell of the fasting person’s mouth,” refers to the altered odor of the fasting person’s mouth caused by fasting."]}},"tuhfa":{},"full":1,"dr":1,"rep":[4626],"tks":"متفق عليه: رواه البخاري (1904)، ومسلم (1151: 163)، واللفظ للبخاري."},{"num":4393,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَالَّذِي نَفْسِي بِيَدِهِ لَخُلُوفُ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ، إِنَّمَا يَذَرُ شَهْوَتَهُ وَطَعَامَهُ وَشَرَابَهُ مِنْ أَجْلِي، فَالصِّيَامُ لِي وَأَنَا أَجْزِي بِهِ. كُلُّ حَسَنَةٍ بِعَشْرِ أَمْثَالِهَا إِلَى سَبْعِمِائَةِ ضِعْفٍ إِلاَّ الصِّيَامَ فَهُوَ لِي وَأَنَا أَجْزِي بِهِ."],"takhrij":"متفق عليه: رواه مالك في الصيام (58) عن أبي الزّناد، عن الأعرج، عن أبي هريرة، فذكره. ورواه البخاريّ في الصِّيام (1894) من طريق مالك، به","grade":"متفق عليه","chapter_ar":"باب الترغيب في الصوم مطلقاً وما جاء في فضله","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Malik (58), al-Bukhari (1894), and Muslim (1151 no. 162).","chapter_en":"Encouragement toward fasting in general and what has come regarding its virtue","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في صيام التطوع والترغيب فيه","group_en":"Collection of reports on voluntary fasting and encouragement toward it","part_no":15,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “By the One in whose hand is my soul, the change in the smell of the fasting person’s mouth is more pleasant to Allah than the fragrance of musk. He leaves his desire, his food, and his drink for My sake. Fasting is for Me, and I reward for it. Every good deed is multiplied ten times up to seven hundred times, except fasting; it is for Me, and I reward for it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (58)، والبخاري (1894)، ومسلم (1151/162)."},{"num":4394,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ، عن النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يرويه عَنْ ربكم قَالَ: لِكُلِّ عَمَلٍ كَفَّارَةٌ، وَالصَّوْمُ لِي، وَأَنَا أَجْزِي بِهِ، وَلَخَلُوفُ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ."],"takhrij":"صحيح: رواه البخاري في التوحيد (7538) عن آدم، عن شعبة، حدثنا محمد بن زياد، سمعت أبا هريرة يقول: فذكره. ولم يذكر مسلم بهذا السياق.","grade":"صحيح","chapter_ar":"باب الترغيب في الصوم مطلقاً وما جاء في فضله","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (7538).","chapter_en":"Encouragement toward fasting in general and what has come regarding its virtue","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في صيام التطوع والترغيب فيه","group_en":"Collection of reports on voluntary fasting and encouragement toward it","part_no":15,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah reported from the Prophet ﷺ, narrating from his Lord, that He said: “Every deed has an expiation, but fasting is for Me, and I reward for it. And the change in the smell of the fasting person’s mouth is more pleasant to Allah than the fragrance of musk.”"]},"buhuth":{"en":["His saying, “Every deed,” means every sinful act has an expiation,","and “an expiation” means an act of obedience that wipes it away."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (7538)."},{"num":4395,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، وَأَبِي سَعِيدٍ، رَضِيَ اللَّهُ عَنْهُمَا قَالَا: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ:  إِنَّ الصَّوْمَ لِي وَأَنَا أَجْزِي بِهِ، إِنَّ لِلصَّائِمِ فَرْحَتَيْنِ: إِذَا أَفْطَرَ فَرِحَ، وَإِذَا لَقِيَ اللَّهَ فَرِحَ، وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَخُلُوفُ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ."],"takhrij":"صحيح: رواه مسلم في الصوم (1151: 165) عن أبي بكر بن أبي شيبة، حدثنا محمد بن فضيل، عن أبي سنان، عن أبي صالح، عن أبي هريرة، وأبي سعيد فذكراه.","grade":"صحيح","chapter_ar":"باب الترغيب في الصوم مطلقاً وما جاء في فضله","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1151 no. 165).","chapter_en":"Encouragement toward fasting in general and what has come regarding its virtue","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في صيام التطوع والترغيب فيه","group_en":"Collection of reports on voluntary fasting and encouragement toward it","part_no":15,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah and Abu Saʿid said: The Messenger of Allah ﷺ said: “Indeed Allah, Mighty and Majestic, says: Fasting is for Me, and I reward for it. The fasting person has two joys: when he breaks his fast, he rejoices, and when he meets Allah, he rejoices. By the One in whose hand is the soul of Muhammad, the change in the smell of the fasting person’s mouth is more pleasant to Allah than the fragrance of musk.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1151: 165)."},{"num":4396,"demo":false,"sanad":"","matn":["عن الْحَارِثِ الأشعريَّ حَدَّثَهُ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ أَمَرَ يَحْيَى بْنَ زَكَرِيَّا بِخَمْسِ كَلِمَاتٍ أَنْ يَعْمَلَ بِهَا وَيَأْمُرَ بَنِي إِسْرَائِيلَ أَنْ يَعْمَلُوا بِهَا، وَإِنَّهُ كَادَ أَنْ يُبْطِئَ بِهَا، فَقَالَ عِيسَى: إِنَّ اللَّهَ أَمَرَكَ بِخَمْسِ كَلِمَاتٍ لِتَعْمَلَ بِهَا وَتَأْمُرَ بَنِي إِسْرَائِيلَ أَنْ يَعْمَلُوا بِهَا، فَإِمَّا أَنْ تَأْمُرَهُمْ وَإِمَّا أَنَا آمُرُهُمْ. فَقَالَ يَحْيَى: أَخْشَى إِنْ سَبَقْتَنِي بِهَا أَنْ يُخْسَفَ بِي أَوْ أُعَذَّبَ، فَجَمَعَ النَّاسَ فِي بَيْتِ الْمَقْدِسِ فَامْتَلأَ الْمَسْجِدُ وَقَعَدُوا عَلَى الشُّرَفِ، فَقَالَ: إِنَّ اللَّهَ أَمَرَنِي بِخَمْسِ كَلِمَاتٍ أَنْ أَعْمَلَ بِهِنَّ وَآمُرَكُمْ أَنْ تَعْمَلُوا بِهِنَّ. أَوَّلُهُنَّ أَنْ تَعْبُدُوا اللَّهَ وَلاَ تُشْرِكُوا بِهِ شَيْئًا وَإِنَّ مَثَلَ مَنْ أَشْرَكَ بِاللَّهِ كَمَثَلِ رَجُلٍ اشْتَرَى عَبْدًا مِنْ خَالِصِ مَالِهِ بِذَهَبٍ أَوْ وَرِقٍ فَقَالَ هَذِهِ دَارِي وَهَذَا عَمَلِي فَاعْمَلْ وَأَدِّ إِلَىَّ فَكَانَ يَعْمَلُ وَيُؤَدِّي إِلَى غَيْرِ سَيِّدِهِ فَأَيُّكُمْ يَرْضَى أَنْ يَكُونَ عَبْدُهُ كَذَلِكَ وَإِنَّ اللَّهَ أَمَرَكُمْ بِالصَّلاَةِ فَإِذَا صَلَّيْتُمْ فَلاَ تَلْتَفِتُوا فَإِنَّ اللَّهَ يَنْصِبُ وَجْهَهُ لِوَجْهِ عَبْدِهِ فِي صَلاَتِهِ مَا لَمْ يَلْتَفِتْ وَآمُرُكُمْ بِالصِّيَامِ فَإِنَّ مَثَلَ ذَلِكَ كَمَثَلِ رَجُلٍ فِي عِصَابَةٍ مَعَهُ صُرَّةٌ فِيهَا مِسْكٌ فَكُلُّهُمْ يَعْجَبُ أَوْ يُعْجِبُهُ رِيحُهَا وَإِنَّ رِيحَ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ."],"takhrij":"صحيح: رواه الترمذيّ (2863)، والإمام أحمد (17170)، وصحّحه ابن خزيمة (1895)، وابن حبان (6233)، والحاكم (1/421) كلّهم من طريق يحيى بن أبي كثير، عن زيد بن سلام، عن جده ممطور، عن الحارث الأسدي، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الترغيب في الصوم مطلقاً وما جاء في فضله","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Tirmidhi (2863), Ahmad (17170), and authenticated by Ibn Khuzaymah (1895) and Ibn Hibban (6233).","chapter_en":"Encouragement toward fasting in general and what has come regarding its virtue","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في صيام التطوع والترغيب فيه","group_en":"Collection of reports on voluntary fasting and encouragement toward it","part_no":15,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Al-Harith al-Ashʿari reported that the Prophet ﷺ said: “Allah commanded Yahya ibn Zakariyya with five words: that he act upon them and command the Children of Israel to act upon them. He nearly delayed in conveying them, so ʿIsa said: Allah has commanded you with five words so that you may act upon them and command the Children of Israel to act upon them; either you convey them or I will. Yahya said: I fear that if you precede me with them, I may be swallowed up or punished. So he gathered the people in Jerusalem until the mosque was full and they overflowed onto the raised places. He said: Allah has commanded me with five words, that I act upon them and command you to act upon them. The first is that you worship Allah and associate nothing with Him. The example of the one who associates partners with Allah is like a man who bought a servant with his pure wealth, with gold or silver, and said: This is my house and this is my work, so work and deliver the earnings to me; yet he worked and delivered them to someone other than his master. Which of you would be pleased for his servant to be like that? Allah has commanded you to pray, so when you pray, do not turn away, for Allah turns His face toward the face of His servant in prayer so long as he does not turn away. And I command you to fast, for the example of that is like a man in a group carrying a pouch of musk, and all of them admire its fragrance — or are pleased by its fragrance — and indeed the smell of the fasting person is more pleasant to Allah than the fragrance of musk.”"]},"buhuth":{"en":["Al-Tirmidhi said: “A Hasan Sahih Gharib hadith.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2863)، وأحمد (17170)، وصححه ابن خزيمة (1895)، وابن حبان (6233)."},{"num":4397,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، قَالَ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: مُرْنِي بِأَمْرٍ، آخُذُهُ عَنْكَ. قَالَ: عَلَيْكَ بِالصَّوْمِ، فَإِنَّهُ لاَ مِثْلَ لَهُ."],"takhrij":"صحيح: رواه النسائي (2220) عن عمرو بن علي، عن عبدالرحمن، قال: حدثنا مهدي بن ميمون، قال: أخبرني محمد بن عبدالله بن أبي يعقوب، قال: أخبرني رجاء بن حيوة، عن أبي أمامة، قال (فذكره).","grade":"صحيح","chapter_ar":"باب الترغيب في الصوم مطلقاً وما جاء في فضله","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasa’i (2220) and Ahmad (22220, 22195, 22142, 22141), and authenticated by Ibn Hibban (3425). Both narrated it through the route of Mahdi ibn Maymun in a longer form.","chapter_en":"Encouragement toward fasting in general and what has come regarding its virtue","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في صيام التطوع والترغيب فيه","group_en":"Collection of reports on voluntary fasting and encouragement toward it","part_no":15,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abu Umamah said: I came to the Messenger of Allah ﷺ and said: Command me with something that I may take from you. He said: “Hold fast to fasting, for there is nothing equal to it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (2220)، وأحمد (22220، 22195، 22142، 22141)، وصححه ابن حبان (3425)."},{"num":4398,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ صَامَ يَوْمًا فِي سَبِيلِ اللَّهِ بَعَّدَ اللَّهُ وَجْهَهُ عَنِ النَّارِ سَبْعِينَ خَرِيفًا."],"takhrij":"متفق عليه: رواه البخاريّ في الجهاد والسير (2840)، ومسلم في الصيام (1153: 168) كلاهما من طريق عبد الرزاق، أخبرنا ابن جريج، أخبرني يحيى بن سعيد، وسهيل بن أبي صالح، أنهما سمعا النّعمان بن أبي عيّاش الزُّرقي يحدّث عن أبي سعيد الخدريّ، فذكره. ولفظهما سواء، إلا أن البخاري قال: بعَّد .","grade":"متفق عليه","chapter_ar":"باب ما جاء في فضل الصوم في سبيل الله","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2840) and Muslim (1153 no. 168).","chapter_en":"What has come regarding the virtue of fasting in the path of Allah","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في صيام التطوع والترغيب فيه","group_en":"Collection of reports on voluntary fasting and encouragement toward it","part_no":15,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: I heard the Messenger of Allah ﷺ say: “Whoever fasts one day in the path of Allah, Allah will distance his face from the Fire by seventy autumns.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2840)، ومسلم (1153: 168)."},{"num":4399,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ صَامَ يَوْمًا فِي سَبِيلِ اللَّهِ، زَحْزَحَ اللهُ وَجْهَهُ عَنِ النَّارِ بِذَلِكَ سَبْعِينَ خَرِيفًا."],"takhrij":"صحيح: رواه النسائي (2244)، وأحمد (7990) كلاهما من حديث أنس بن عياض، عن سُهيل بن أبي صالح، عن أبيه، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في فضل الصوم في سبيل الله","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasa’i (2244) and Ahmad (7990).","chapter_en":"What has come regarding the virtue of fasting in the path of Allah","part_en":"The Book of Fasting","group_ar":"جموع ما جاء في صيام التطوع والترغيب فيه","group_en":"Collection of reports on voluntary fasting and encouragement toward it","part_no":15,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Whoever fasts one day in the path of Allah, Allah will move his face away from the Fire by means of it by seventy autumns.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (2244)، وأحمد (7990)."}]);